#!/usr/bin/env node
/**
 * suite-lyric.js —— 【第 64 轮·删除合并】歌词：锚点 / 单写者 / 双击跳转 / 手动定位 / 迷你歌词
 * 成员 10 个：sim-lyric-anchor-sync.js、sim-lyric-dash-fade.js、sim-lyric-double-tap-seek.js、sim-lyric-manual-position.js、sim-lyric-resume-instant.js、sim-lyric-scroll-single-writer.js、sim-mini-lyric-return-timing.js、sim-local-toggle-source-lyric.js、sim-seek-lyric-follow.js、sim-board-nav.js
 *
 * 本文件由「成员源码原样嵌入」生成：每个成员在套件里仍然是**它自己那份源码**，
 * 跑在独立的作用域里（自己的 require / process / console / __dirname / __filename /
 * module / exports），彼此不共享变量；成员的 `process.exit(c)` 由套件记录退出码
 *（不真的退出 —— 与 run.py 的 runner 同一种 shim，行为逐字等价）。
 *
 * 为什么合并：scripts/ 里躺着上百个两三千字节的独立脚本，用户第 64 轮明确要求
 * 「删除合并 scripts 文件夹中的脚本文件」；套件把同主题的契约收进一个文件，
 * 覆盖率一个成员都不少（合并前逐文件 __EXIT__ 与合并后逐成员 exit 已逐项比对）。
 *
 * 注意：scripts/ 不参与打包（不进 App bundle），所以这一步**不省电、不降温** ——
 * 省电的改动都在 src/ 与 ios/ 里（见改动清单第六十四轮）。
 *
 * 运行：python "C:\Users\Q\AppData\Local\Temp\lx-jsrun\run.py" scripts/suite-lyric.js --brief
 *   `--brief` 只看 FAIL / ===== / 结果 行；去掉 `--brief` 看每个成员的全部输出。
 * 也可以用真实 node 跑（`node scripts/suite-lyric.js`、`npm run lint:sound-effect-dsp`）：
 * 成员一律用 path.resolve(__dirname, '..') 定位工程根，套件把**自己的** __dirname
 * 传下去，所以两种环境下指向同一棵树。
 * 退出码：全部成员 exit 0 时为 0，否则为第一个非 0 的成员退出码。
 */
'use strict'

const THEME = "歌词：锚点 / 单写者 / 双击跳转 / 手动定位 / 迷你歌词"

const MEMBERS = [
  { n: "sim-lyric-anchor-sync.js", s: "// 歌词时钟锚点滞后模型复刻：灵动岛/控制中心歌词恒定慢半拍的根因验证\n//\n// 机制：灵动岛/控制中心/锁屏歌词由原生 GCD 时钟驱动（AppDelegate.mm\n// com.lxmusic.nowplaying.lyric 串行队列，0.12s tick）：\n//   position = 锚点位置 LXNowPlayingLyricAnchorElapsedMs\n//            + (CACurrentMediaTime*1000 − 锚点系统时间) × playbackRate\n// 锚点由 JS 周期性回传的「引擎真实位置快照」重置（两条链路）：\n//   A) 1s 慢校准：getPosition（桥往返1）→ await getPlaybackEngineState（桥往返2）\n//      → reanchorNowPlayingLyric（桥去程3 + 主队列排队）\n//   B) 换行元数据发布：getPosition（桥往返1）→ updateNowPlayingInfo（桥去程2）\n//      → LXSetNowPlayingInfo → LXRefreshNowPlayingLyricAnchor（从缓存 elapsed 重锚）\n//\n// 根因：快照位置是「过去时刻」的值，旧逻辑把锚点系统时间钉在「现在」——\n//   时钟值 = P(t_snap) + (t − t_apply) × rate = P(t) − (t_apply − t_snap) × rate\n// 即歌词时钟恒定回拨一个「快照年龄」（完整桥接往返 ≈ 100~300ms），且每次\n// 校准/换行都重新回拨 → 恒定滞后。App 内歌词走原生 4Hz 位置事件（无桥接\n// 滞后）→ App 内准、灵动岛/控制中心慢半拍，即「灵动岛歌词不同步」。\n//\n// 修法（快照时刻回放）：\n//   - nativeFlac 路径：新增 StreamingFlacPlayerModule.getPositionStamped，原生在\n//     renderQueue 取位置时同拍打 CACurrentMediaTime 毫秒戳；重锚时锚点系统时间\n//     = min(snapshotAt, now) → 与真实播放位置零偏差\n//   - AVPlayer 路径（TrackPlayerModule 在 node_modules，无法打原生戳）：JS 以\n//     「往返一半」估计快照年龄，重锚时锚点系统时间 = now − ageMs → 残余误差\n//     ≤ ±往返/4（远小于旧行为的整段往返）\n//   - 元数据/播放态发布链路：metadata 携带 elapsedTimeSnapshotAt / elapsedTimeAgeMs\n//     （自定义透传键，不进系统 info 字典），LXSetNowPlayingInfo /\n//     LXSetNowPlayingPlaybackState 在写入位置缓存时同步解析戳，\n//     LXRefreshNowPlayingLyricAnchor 据此回放；无戳时清零防旧戳错配。\n//\n// 进度条基线（第二批断言）：系统进度条从每次发布的 ElapsedPlaybackTime 基线外推。\n// 旧行为把快照时刻的过去值直接写进 info / 缓存，且原生 tick 行变化重发缓存时\n// elapsed 仍是上次发布的旧值 → 基线每次发布回拨一个快照年龄（前台 ~150ms，\n// 熄屏后 JS 挂起、只剩原生 tick 重发 → 回拨持续增大，进度条后跳、时间倒退）。\n// 修法 = 写系统基线时把快照推进到「现在」（LXAdvanceElapsedToNowSec），tick 重发\n// 前把基线刷新为时钟外推值；缓存 (值, 戳) 必须成对更新（错配会把歌词时钟推超前）。\n//\n// 本脚本 1:1 复刻锚点更新公式与外推公式，逐条验证 10 个断言（均带反例）。\n\n'use strict';\n\n// ---------------------------------------------------------------------------\n// 模型基元\n// ---------------------------------------------------------------------------\n\nconst RATE = 1;\n\n// 校准链路时序参数（毫秒，典型 RN 桥量级）：up1/down1 = getPosition 去程/回程，\n// rtt2 = getPlaybackEngineState 往返，up2 = reanchor 去程 + 主队列排队\nconst up1 = 75, down1 = 75, rtt2 = 120, up2 = 60;\n\n// 真实播放位置：音频在时刻 t 的真值（线性，速率恒定）\nconst truePosition = (t0Ms, tMs) => (t0Ms + (tMs - 0) * RATE);\n\n// 歌词时钟状态（复刻 AppDelegate.mm 静态量）\nconst makeClock = () => ({ anchorElapsedMs: 0, anchorSystemMs: 0, hold: false });\n\n// 复刻 LXReanchorNowPlayingLyric(elapsedMs, snapshotAtMs, ageMs)（修复后）\n// - snapshotAtMs > 0：锚点系统时间 = min(snapshotAt, now)（快照时刻精确回放）\n// - 否则 ageMs > 0：锚点系统时间 = now − min(ageMs, 1000)（年龄补偿）\n// - 都无：锚点系统时间 = now（旧行为——快照位置钉在现在）\nconst reanchor = (clock, elapsedMs, snapshotAtMs, ageMs, nowMs) => {\n  clock.anchorElapsedMs = elapsedMs;\n  let anchorSystemMs = nowMs;\n  if (snapshotAtMs > 0) {\n    anchorSystemMs = Math.min(snapshotAtMs, nowMs);\n  } else if (ageMs > 0) {\n    anchorSystemMs = nowMs - Math.min(ageMs, 1000);\n  }\n  clock.anchorSystemMs = anchorSystemMs;\n};\n\n// 复刻 tick 的位置计算（hold 冻结语义同原生）\nconst clockPosition = (clock, nowMs) => (clock.hold\n  ? clock.anchorElapsedMs\n  : clock.anchorElapsedMs + (nowMs - clock.anchorSystemMs) * RATE);\n\n// 复刻 LXResolveElapsedSnapshotAtMs（元数据发布链路的戳解析）\nconst resolveSnapshotAt = (payload, nowMs) => {\n  if (payload.elapsedTimeSnapshotAt > 0) return Math.min(payload.elapsedTimeSnapshotAt, nowMs);\n  if (payload.elapsedTimeAgeMs > 0) return nowMs - Math.min(payload.elapsedTimeAgeMs, 1000);\n  return 0;\n};\n\n// ---------------------------------------------------------------------------\n// 场景模拟\n// ---------------------------------------------------------------------------\n\n// 模拟「每秒校准」完整时序（与 playProgress 慢路径逐段对应）：\n//   t_req      JS 发起 getPositionStamped\n//   t_snap     = t_req + up1                    原生 renderQueue 产生快照（up1 = 去程）\n//   t_recv     = t_req + up1 + down1            JS 收到（stamped.ageMs = up1，往返对称假设）\n//   t_engine   = t_recv + rtt2                  await getPlaybackEngineState 往返\n//   t_apply    = t_engine + up2                 reanchor 去程 + 主队列排队，原生消费\n// mode: 'legacy'（旧行为）| 'stamped'（原生戳）| 'age'（年龄估计，JS 补偿量 =\n// (t_engine − t_req) − stamped.ageMs，即「发起→重锚前」总流逝 − 去程偏移）\nconst simulateCalibration = ({ up1 = 75, down1 = 75, rtt2 = 120, up2 = 60, periodMs = 1000, durationMs = 30000, mode }) => {\n  const clock = makeClock();\n  clock.anchorElapsedMs = 0;\n  clock.anchorSystemMs = 0;\n  let maxLead = 0;\n  const samples = [];\n  for (let t = 0; t <= durationMs; t += 12) {\n    if (t > 0 && t % periodMs === 0) {\n      const tReq = t - up1 - down1 - rtt2 - up2; // 使 t_apply 落在整点上\n      const tSnap = tReq + up1;\n      const snapPos = truePosition(0, tSnap);\n      if (mode === 'stamped') {\n        reanchor(clock, snapPos, tSnap, 0, t);\n      } else if (mode === 'age') {\n        // JS 侧补偿量：总流逝(up1+down1+rtt2) − stamped.ageMs(up1) = down1 + rtt2\n        reanchor(clock, snapPos, 0, down1 + rtt2, t);\n      } else {\n        reanchor(clock, snapPos, 0, 0, t);\n      }\n    }\n    const lag = truePosition(0, t) - clockPosition(clock, t);\n    maxLead = Math.max(maxLead, -lag);\n    samples.push(lag);\n  }\n  // 稳态 = 最后 1/3 样本的中位数（排除启动瞬态）\n  const tail = samples.slice(samples.length - Math.floor(samples.length / 3)).sort((a, b) => a - b);\n  const steadyLag = tail[Math.floor(tail.length / 2)];\n  return { steadyLag, maxLead };\n};\n\n// 模拟「换行元数据发布重锚」：JS 在 t_snap 取快照（桥往返 rtt 后发起发布），\n// 原生 t_apply 处理 metadata（elapsed + 戳解析），LXRefreshNowPlayingLyricAnchor\n// 用 (缓存 elapsed, 缓存戳) 重锚。每 lineEveryMs 一次。带反例（无戳 payload）。\nconst simulateMetadataReanchor = ({ rtt = 150, lineEveryMs = 5000, durationMs = 30000, withStamp }) => {\n  const clock = makeClock();\n  let cachedStampAt = 0; // LXNowPlayingElapsedSnapshotAtMs\n  const samples = [];\n  for (let t = 0; t <= durationMs; t += 12) {\n    if (t > 0 && t % lineEveryMs === 0) {\n      const tSnap = t - rtt; // 快照产生 → JS 收到 → 发起发布 → 原生 t_apply 处理\n      const snapPos = truePosition(0, tSnap);\n      // 复刻 LXSetNowPlayingInfo 的 elapsedTime 分支：缓存位置 + 解析戳\n      const payload = withStamp\n        ? { elapsedTimeSnapshotAt: tSnap }\n        : {};\n      cachedStampAt = resolveSnapshotAt(payload, t);\n      // 复刻 LXRefreshNowPlayingLyricAnchor：从缓存 (elapsed, stamp) 重锚\n      reanchor(clock, snapPos, cachedStampAt, 0, t);\n    }\n    samples.push(truePosition(0, t) - clockPosition(clock, t));\n  }\n  const tail = samples.slice(samples.length - Math.floor(samples.length / 3)).sort((a, b) => a - b);\n  return { steadyLag: tail[Math.floor(tail.length / 2)] };\n};\n\n// ---------------------------------------------------------------------------\n// 进度条基线模型（控制中心进度条后跳 / 左侧时间倒退）\n// ---------------------------------------------------------------------------\n\n// 系统进度条：从最近一次发布的 (elapsedBase, publishAt) 外推。\n// republish 返回回拨幅度（旧显示值 − 新基线，> 0 即进度条后跳）。\nconst makeProgressBar = () => ({ base: 0, publishAt: 0 });\nconst progressAt = (bar, t) => bar.base + (t - bar.publishAt) * RATE;\nconst republish = (bar, t, elapsedMs) => {\n  const before = progressAt(bar, t);\n  bar.base = elapsedMs;\n  bar.publishAt = t;\n  return before - elapsedMs;\n};\n\n// 熄屏/后台场景：JS 定时器挂起、不再发布元数据，换行只靠原生 tick 重发缓存。\n// 旧行为：缓存 elapsed 是后台前最后一次 JS 发布的快照值，tick 重发即回拨，\n// 且随时间持续增大（几秒级——进度条后跳、时间倒退的主害场景）。\n// 修复后：tick 重发前把基线刷新为歌词时钟外推的「现在」位置 → 零回拨。\nconst simulateBackgroundProgress = ({ lineEveryMs = 5000, rtt = 150, durationMs = 60000, mode }) => {\n  const bar = makeProgressBar();\n  let cachedElapsedMs = 0; // LXNowPlayingInfoCache[ElapsedPlaybackTime]\n  let cachedStampAt = 0;   // LXNowPlayingElapsedSnapshotAtMs（成对更新语义）\n  let maxBackward = 0;\n  let published = false;\n  for (let t = 0; t <= durationMs; t += 12) {\n    const isLine = t > 0 && t % lineEveryMs === 0;\n    if (!isLine) continue;\n    if (!published) {\n      // 进后台前最后一次 JS 换行发布：快照产生于 t − rtt\n      const tSnap = t - rtt;\n      const snapPos = truePosition(0, tSnap);\n      if (mode === 'legacy') {\n        cachedElapsedMs = snapPos; // 旧行为：快照值原样进缓存，戳 = 0\n        cachedStampAt = 0;\n      } else {\n        // 修复后：LXAdvanceElapsedToNowSec 推进到现在 + 戳成对更新为 now\n        cachedElapsedMs = snapPos + Math.min(t - tSnap, 1000) * RATE;\n        cachedStampAt = t;\n      }\n      published = true;\n      maxBackward = Math.max(maxBackward, republish(bar, t, cachedElapsedMs));\n      continue;\n    }\n    // 原生 tick 行变化重发（行变化只在播放中发生）\n    if (mode === 'legacy') {\n      // 旧行为：重发缓存旧值 → 基线被拉回后台前的位置\n      maxBackward = Math.max(maxBackward, republish(bar, t, cachedElapsedMs));\n    } else {\n      // 修复后：重发前把基线刷新为时钟外推的「现在」（复刻 tick 的\n      // positionMs 刷新），缓存对同步滚动\n      const clockNow = cachedElapsedMs + (t - cachedStampAt) * RATE;\n      maxBackward = Math.max(maxBackward, republish(bar, t, clockNow));\n      cachedElapsedMs = clockNow;\n      cachedStampAt = t;\n    }\n  }\n  return { maxBackward };\n};\n\n// ---------------------------------------------------------------------------\n// 断言\n// ---------------------------------------------------------------------------\n\nlet pass = 0, fail = 0;\nconst check = (name, ok, detail) => {\n  console.log(`  ${ok ? '✓' : '✗'} ${name}${detail ? '  — ' + detail : ''}`);\n  ok ? pass++ : fail++;\n};\n\nconsole.log('sim-lyric-anchor-sync：灵动岛/控制中心歌词锚点滞后模型\\n');\n\n// 断言1（缺陷复现/反例）：旧行为——快照位置被钉在现在，稳态滞后 = 完整快照年龄\n// （快照产生于去程结束：t_snap = t_req + up1，年龄 = t_apply − t_snap = 255ms）\n{\n  const { steadyLag } = simulateCalibration({ mode: 'legacy' });\n  const expected = down1 + rtt2 + up2;\n  check('旧行为稳态滞后 = 完整快照年龄（缺陷存在）',\n    Math.abs(steadyLag - expected) < 5,\n    `稳态滞后 ${steadyLag.toFixed(1)}ms，预期 ≈ ${expected}ms`);\n}\n\n// 断言2（修复验证，断言1的反例）：原生戳回放 → 滞后归零\n{\n  const { steadyLag, maxLead } = simulateCalibration({ mode: 'stamped' });\n  check('原生戳回放稳态滞后 ≤ 1ms（修复生效，与断言1互为反例）',\n    Math.abs(steadyLag) <= 1 && maxLead <= 1,\n    `稳态滞后 ${steadyLag.toFixed(3)}ms，最大超前 ${maxLead.toFixed(3)}ms`);\n}\n\n// 断言3：AVPlayer 年龄估计 → 残余 = reanchor 去程 up2（对称往返下不可再消），\n// 远小于旧行为的完整快照年龄\n{\n  const { steadyLag, maxLead } = simulateCalibration({ mode: 'age' });\n  const expected = up2;\n  const legacy = down1 + rtt2 + up2;\n  check('年龄估计残余 = reanchor 去程（60ms），远小于旧行为（255ms）',\n    Math.abs(steadyLag - expected) < 5 && maxLead <= 1 && steadyLag < legacy / 4,\n    `稳态滞后 ${steadyLag.toFixed(1)}ms，预期 ≈ ${expected}ms（旧行为 ${legacy}ms）`);\n}\n\n// 断言4（兼容回退）：snapshotAt=0 且 ageMs=0 → 旧行为（老版本 JS 调用不受影响）\n{\n  const clock = makeClock();\n  const t = 5000, tSnap = 4850;\n  reanchor(clock, truePosition(0, tSnap), 0, 0, t);\n  const lag = truePosition(0, t + 100) - clockPosition(clock, t + 100);\n  check('无戳调用回退旧行为（滞后 = 快照年龄，兼容老调用方）',\n    Math.abs(lag - (t - tSnap)) < 1,\n    `滞后 ${lag.toFixed(1)}ms ≈ 快照年龄 ${t - tSnap}ms`);\n}\n\n// 断言5（钳制）：异常未来戳被钳到 now，时钟不超前\n{\n  const clock = makeClock();\n  const t = 5000, tSnap = 4850, future = t + 400;\n  reanchor(clock, truePosition(0, tSnap), future, 0, t);\n  const lead = clockPosition(clock, t) - truePosition(0, t);\n  check('未来戳被钳制到 now（时钟永不超前真实位置）',\n    lead <= 0.001,\n    `钳制后超前 ${lead.toFixed(3)}ms`);\n}\n\n// 断言6（hold 冻结）：hold 时时钟停在锚点位置，重锚只更新停驻点\n{\n  const clock = makeClock();\n  reanchor(clock, 42000, 0, 0, 5000);\n  clock.hold = true;\n  const p1 = clockPosition(clock, 5100);\n  const p2 = clockPosition(clock, 5900);\n  check('hold 冻结：时钟停驻锚点位置不外推（暂停/缓冲语义保持）',\n    p1 === 42000 && p2 === 42000,\n    `t+100ms=${p1}ms，t+900ms=${p2}ms`);\n}\n\n// 断言7（换行元数据链路，带反例）：带戳 payload 稳态滞后 0，无戳 payload 滞后 = 快照年龄\n{\n  const withStamp = simulateMetadataReanchor({ withStamp: true });\n  const noStamp = simulateMetadataReanchor({ withStamp: false });\n  check('换行元数据带戳 → 稳态滞后 0（换行链路修复生效）',\n    Math.abs(withStamp.steadyLag) <= 1,\n    `带戳滞后 ${withStamp.steadyLag.toFixed(3)}ms`);\n  check('换行元数据无戳（反例）→ 稳态滞后 = 快照年龄（证明戳必要）',\n    Math.abs(noStamp.steadyLag - 150) < 5,\n    `无戳滞后 ${noStamp.steadyLag.toFixed(1)}ms ≈ 150ms`);\n}\n\n// 断言8（进度条后跳缺陷复现/反例）：熄屏后原生 tick 行变化重发旧缓存 →\n// 基线被拉回后台前位置，回拨随时间持续增大（用户报「进度条后跳、时间倒退」）\n{\n  const { maxBackward } = simulateBackgroundProgress({ mode: 'legacy' });\n  check('熄屏旧行为：tick 重发旧缓存 → 回拨 ≥ 5s 且持续增大（缺陷存在）',\n    maxBackward > 5000,\n    `最大回拨 ${(maxBackward / 1000).toFixed(1)}s`);\n}\n\n// 断言9（修复验证，断言8的反例）：tick 重发前刷新基线为时钟外推值 → 零回拨\n{\n  const { maxBackward } = simulateBackgroundProgress({ mode: 'fixed' });\n  check('熄屏修复后：基线随 tick 滚动推进 → 回拨 ≤ 1ms（与断言8互为反例）',\n    maxBackward <= 1,\n    `最大回拨 ${maxBackward.toFixed(3)}ms`);\n}\n\n// 断言10（成对更新防回归）：缓存值推进而戳不推进（错配）→ 歌词时钟超前快照年龄。\n// 守护本批进度条修复不得破坏上一批歌词修复：LXRefreshNowPlayingLyricAnchor 读\n// 同一缓存对重锚，值/戳必须成对更新\n{\n  const t0 = 5000, tSnap = t0 - 150;\n  const clock = makeClock();\n  const advanced = truePosition(0, t0); // 值已推进到「现在」\n  reanchor(clock, advanced, tSnap, 0, t0); // 但戳错配仍为快照时刻\n  const lead = clockPosition(clock, t0 + 1000) - truePosition(0, t0 + 1000);\n  check('值推进而戳不推进（错配反例）→ 歌词时钟超前快照年龄（证明缓存对必须成对更新）',\n    Math.abs(lead - 150) < 5,\n    `超前 ${lead.toFixed(1)}ms ≈ 快照年龄 150ms`);\n}\n\n// ---------------------------------------------------------------------------\n// seek 后控制中心进度基线（nativeFlac 路径无 info 发布的缺口）\n// ---------------------------------------------------------------------------\n\n// nativeFlac 路径 TrackPlayer 已 reset、无原生 seek 事件：seek 后若不发布 info，\n// 控制中心进度条基线停留在 seek 前的位置继续外推 → 与真实位置偏差 = seek 幅度\n// （进度条完全不跟 seek）。修复 = seek 落点确认 + 引擎 playing 后发布基线\n// （syncNowPlayingState('play')，对齐上游「playing → 重锚 + 广播」范式）。\nconst simulateSeekBaseline = ({ publishAfterSeek, seekAtMs = 10000, seekTargetSec = 120, rtt = 150, fastResyncMs = 300, observeMs = 5000 }) => {\n  let baselineSec = 0, baselineAtMs = 0;\n  let published = false;\n  let maxError = 0;\n  for (let t = 0; t <= seekAtMs + observeMs; t += 12) {\n    if (t >= seekAtMs && publishAfterSeek && !published && t >= seekAtMs + fastResyncMs) {\n      // 快路径发布：elapsed 快照产生于发布前 rtt（桥往返），原生推进到现在 →\n      // 基线 ≈ 落点 + (fastResyncMs − rtt) 的播放量\n      baselineSec = seekTargetSec + Math.max(0, fastResyncMs - rtt) / 1000;\n      baselineAtMs = t;\n      published = true;\n    }\n    const truePos = t < seekAtMs ? t / 1000 : seekTargetSec + (t - seekAtMs) / 1000;\n    const shown = baselineSec + (t - baselineAtMs) / 1000;\n    // 口径：只统计「基线已定」的误差——发布前窗口（≤300ms）显示旧位置是任何\n    // 方案都有的固有发布延迟，不是基线失联（断言11 不发布 = published 恒 false，\n    // 全程都在统计，口径一致）\n    if (published || !publishAfterSeek) maxError = Math.max(maxError, Math.abs(shown - truePos));\n  }\n  return { maxError };\n};\n\n// 断言11（缺口复现/反例）：nativeFlac seek 后不发布 info → 基线失联\n{\n  const { maxError } = simulateSeekBaseline({ publishAfterSeek: false });\n  check('nativeFlac seek 后不发布基线（旧行为）→ 控制中心进度条偏差 = seek 幅度（缺陷存在）',\n    maxError > 100,\n    `最大偏差 ${maxError.toFixed(1)}s（seek 幅度 110s）`);\n}\n\n// 断言12（修复验证，断言11的反例）：落点确认 + playing 发布基线 → 偏差 ≤ 快照年龄\n{\n  const { maxError } = simulateSeekBaseline({ publishAfterSeek: true });\n  check('nativeFlac seek 后快路径发布基线（修复）→ 偏差 ≤ 快照年龄（与断言11互为反例）',\n    maxError <= 0.3,\n    `最大偏差 ${(maxError * 1000).toFixed(0)}ms（≈ 快照年龄 150ms）`);\n}\n\nconsole.log(`\\n结果: ${pass} 通过, ${fail} 失败`);\nprocess.exit(fail ? 1 : 0);\n" },
  { n: "sim-lyric-dash-fade.js", s: "/**\n * sim-lyric-dash-fade.js\n *\n * 「歌词手动定位虚线的左端淡出」契约（`PlayLine.tsx` 的 DASH_FADE_* 与 getDashColor）。\n *\n * 需求原文：「歌词进度跳转虚线，改为从左端向右边 1/3 的地方开始淡出，也就是颜色能\n * 看得见，三分之一前是透明看不见的。」拆成两条可判定的东西：\n *   ① 左起 1/3 段：每一小段的 alpha **恰好是 0**（不是「很淡」，是看不见）；\n *   ② 跨过 1/3 之后：必须真的看得见 —— 在很短的宽度内淡入到该处的渐变值；\n *      如果把淡入摊到剩下的 2/3 上，1/3 之后的一大半仍然只有 0.0x 的不透明度，\n *      用户看到的还是「看不见」，需求等于没做（这正是本次修掉的行为）。\n *\n * A. 数值模型：从源码解析 DASH_FADE_START_RATIO / DASH_FADE_SPAN_RATIO /\n *    DASH_ALPHA_MIN / DASH_ALPHA_MAX，1:1 复刻 getDashColor 的算式，在多种行宽下\n *    逐段验证 ①②③（含「右端恰好等于渐变上限、全程单调不超上限」），并用**旧算式**\n *    （摊到 1-START）和**把 SPAN 调到 0.6**作为反例，证明断言真的能拦住「假装看得见」。\n * B. 结构不变量：淡出必须作用在**真正被渲染出来的每一小段**上（不是死代码）、段数按\n *    缩放后的段宽推算（字号放大后仍铺满不右空）、不得退回 iOS 渲染不可靠的\n *    borderStyle:'dashed'、也不许把 opacity 打到容器/色块上（那会把「只剩虚线」变成\n *    「虚线也没了」）。\n *\n * 契约强度说明：B 是源码文本级静态断言，通过 ≠ 能编译 ≠ 真机观感；A 是模型级，\n * 证明的是「算式满足需求」，不含 RN 布局与真实屏幕上的视觉阈值判断。\n *\n * 运行：node scripts/sim-lyric-dash-fade.js\n * 退出码：不变量全过且反例全被拦下时为 0，否则 1。\n */\n\n'use strict'\n\nconst fs = require('fs')\nconst path = require('path')\n\nconst ROOT = path.join(__dirname, '..')\nconst read = (p) => fs.readFileSync(path.join(ROOT, p), 'utf8').replace(/\\r\\n/g, '\\n')\n/** 去行注释与块注释：否则「把某行注释掉」的篡改会被当成仍然存在 */\nconst stripComments = (src) => src.replace(/\\/\\*[\\s\\S]*?\\*\\//g, '').replace(/\\/\\/[^\\n]*/g, '')\n\nconst FILE = 'src/screens/PlayDetail/components/PlayLine.tsx'\nconst SRC = read(FILE)\nconst CODE = stripComments(SRC)\n\n/** 只允许数字与四则运算的常量求值（源码里写作 1 / 3） */\nconst evalConst = (src, name) => {\n  const m = new RegExp('const\\\\s+' + name + '\\\\s*=\\\\s*([^\\\\n]+)').exec(src)\n  if (!m) return null\n  const expr = m[1].replace(/;+\\s*$/, '').trim()\n  if (!/^[\\d\\s.+\\-*/()]+$/.test(expr)) return null\n  try {\n    const v = Function('\"use strict\";return (' + expr + ')')()\n    return typeof v === 'number' && isFinite(v) ? v : null\n  } catch (e) {\n    return null\n  }\n}\n\nconst P = {\n  start: evalConst(CODE, 'DASH_FADE_START_RATIO'),\n  span: evalConst(CODE, 'DASH_FADE_SPAN_RATIO'),\n  min: evalConst(CODE, 'DASH_ALPHA_MIN'),\n  max: evalConst(CODE, 'DASH_ALPHA_MAX'),\n}\n\nlet pass = 0, fail = 0\nconst check = (name, ok, detail) => {\n  console.log(`  ${ok ? '✓' : '✗'} ${name}${detail ? '  — ' + detail : ''}`)\n  ok ? pass++ : fail++\n}\n\n// ---------------------------------------------------------------------------\n// A. 数值模型\n// ---------------------------------------------------------------------------\n\n/**\n * 复刻 getDashColor 的 alpha 部分。mode：\n *   'span'    —— 源码现在用的：跨过 1/3 后在 SPAN 宽度内淡入（钳到 1）\n *   'legacy'  —— 本次修掉的旧算式：摊到剩下的 (1 - START) 上\n *   'noclamp' —— 少了上下钳制的写法（会超出渐变上限）\n */\nconst alphaWith = (ratio, p = P, mode = 'span') => {\n  let fadeIn\n  if (mode === 'legacy') fadeIn = ratio <= p.start ? 0 : (ratio - p.start) / (1 - p.start)\n  else if (mode === 'noclamp') fadeIn = (ratio - p.start) / p.span\n  else fadeIn = Math.min(Math.max((ratio - p.start) / p.span, 0), 1)\n  return (p.min + (p.max - p.min) * ratio) * fadeIn\n}\n\n/** 与源码同口径的段序列：ratio = index / (dashCount - 1)，dashCount 由「段宽 + 间距」推算 */\nconst seriesFor = (dashWidth, dashLen = 3, dashGap = 2) => {\n  const count = Math.floor((dashWidth + dashGap) / (dashLen + dashGap))\n  return Array.from({ length: count }, (_, i) => (count > 1 ? i / (count - 1) : 1))\n}\n\n// 虚线可用宽度实测域：小歌词（iPhone SE 宽 320，虚线 marginLeft 30）到 iPad 横屏\nconst WIDTHS = [200, 260, 300, 414, 620]\nconst EPS = 1e-9\n\n/** ① 左 1/3 段每一小段必须恰好不可见，且 1/3 段要真的存在（不是只剩一两个点） */\nconst leftThirdInvisible = (p = P, mode = 'span') => {\n  const bad = []\n  let minSegs = Infinity\n  for (const w of WIDTHS) {\n    const rs = seriesFor(w)\n    const inThird = rs.filter((r) => r <= p.start + EPS)\n    minSegs = Math.min(minSegs, inThird.length)\n    for (const r of inThird) {\n      const a = alphaWith(r, p, mode)\n      if (a !== 0) bad.push(`宽${w}: ratio=${r.toFixed(4)} alpha=${a.toFixed(4)}`)\n    }\n  }\n  return {\n    ok: bad.length === 0 && minSegs >= 3,\n    detail: bad.length\n      ? `左 1/3 内仍有可见段：${bad.slice(0, 3).join('；')}`\n      : `左 1/3 内全为 0（最窄一行也有 ${minSegs} 段落在这一区间）`,\n  }\n}\n\n/** ② 淡入必须在「过 1/3 之后不远」就完成，而不是快到右端才现形 */\nconst fadeDoneRatio = (p = P, mode = 'span', dashWidth = 300) => {\n  for (const r of seriesFor(dashWidth)) {\n    if (r <= p.start + EPS) continue\n    const grad = p.min + (p.max - p.min) * r\n    if (alphaWith(r, p, mode) >= grad - 1e-6) return r\n  }\n  return null\n}\n\nconst visibleAfterThird = (p = P, mode = 'span') => {\n  const done = fadeDoneRatio(p, mode)\n  const mid = alphaWith(0.5, p, mode)\n  const ok = done != null && done <= 0.5 && mid >= 0.25\n  return {\n    ok,\n    detail: `淡入完成于 ${done == null ? '未完成' : done.toFixed(4)}（要求 ≤ 0.5）；中线处 alpha=${mid.toFixed(3)}（要求 ≥ 0.25）`,\n  }\n}\n\n/** ③ 渐变本身：右端恰好等于上限、全程单调不减、任何一段都不超过上限 */\nconst gradientIntact = (p = P, mode = 'span') => {\n  const alphas = seriesFor(414).map((r) => alphaWith(r, p, mode))\n  const last = alphas[alphas.length - 1]\n  const over = alphas.filter((a) => a > p.max + EPS).length\n  let mono = true\n  for (let i = 1; i < alphas.length; i++) if (alphas[i] < alphas[i - 1] - EPS) mono = false\n  return {\n    ok: Math.abs(last - p.max) < EPS && over === 0 && mono,\n    detail: `右端 ${last.toFixed(4)}（上限 ${p.max}）；超上限段 ${over}；单调 ${mono}`,\n  }\n}\n\nconsole.log('sim-lyric-dash-fade：歌词定位虚线「左 1/3 透明、其后可见」契约\\n')\nconsole.log('--- A. 数值模型（逐段 alpha） ---')\n\ncheck('常量齐备：START = 1/3、SPAN ∈ (0, 1/4]、0 < MIN < MAX < 1',\n  P.start != null && Math.abs(P.start - 1 / 3) < 1e-9 && P.span != null && P.span > 0 && P.span <= 0.25 &&\n    P.min != null && P.max != null && P.min > 0 && P.min < P.max && P.max < 1,\n  `START=${P.start} SPAN=${P.span} MIN=${P.min} MAX=${P.max}`)\n\n{\n  const r = leftThirdInvisible()\n  check('断言 1：左起 1/3 段每一小段的 alpha 恰好为 0（透明看不见）', r.ok, r.detail)\n}\n{\n  const r = visibleAfterThird()\n  check('断言 2：跨过 1/3 后不远即完成淡入，且中线处已经明显可见', r.ok, r.detail)\n}\n{\n  const r = gradientIntact()\n  check('断言 3：右端等于渐变上限、全程单调不减、无一段超上限', r.ok, r.detail)\n}\n{\n  // 段数与行宽无关地成立：五种行宽下，可见段起点都落在 [1/3, 1/3+SPAN] 内\n  const starts = WIDTHS.map((w) => {\n    for (const r of seriesFor(w)) {\n      if (alphaWith(r) > 0) return r\n    }\n    return null\n  })\n  const ok = starts.every((s) => s != null && s > P.start && s <= P.start + P.span + 0.02)\n  check('断言 4：200~620pt 五种行宽下，第一段可见点的位置一致（不随行宽漂移）',\n    ok, `首可见点 ${starts.map((s) => (s == null ? 'x' : s.toFixed(3))).join(' / ')}`)\n}\n\nconsole.log('\\n--- A2. 反例自检（同一套断言必须能拦住「假装看得见」） ---')\n{\n  const legacy = visibleAfterThird(P, 'legacy')\n  const legacyMid = alphaWith(0.5, P, 'legacy')\n  check('反例 ①：旧算式（淡入摊到剩下 2/3）→ 断言 2 失败',\n    !legacy.ok, `旧算式淡入完成于 ${fadeDoneRatio(P, 'legacy').toFixed(3)}、中线 alpha=${legacyMid.toFixed(3)}（正是本次修掉的「后面还是看不见」）`)\n}\n{\n  const wide = visibleAfterThird({ ...P, span: 0.6 })\n  check('反例 ②：SPAN 调到 0.6（换汤不换药的摊开式）→ 断言 2 失败',\n    !wide.ok, `淡入完成于 ${fadeDoneRatio({ ...P, span: 0.6 }).toFixed(3)}（> 0.5 即判失败）`)\n}\n{\n  const noClamp = gradientIntact(P, 'noclamp')\n  check('反例 ③：去掉上下钳制 → 断言 3 失败（段色会盖过右端上限）',\n    !noClamp.ok, noClamp.detail)\n}\n\n// ---------------------------------------------------------------------------\n// B. 结构不变量\n// ---------------------------------------------------------------------------\n\n/** 单条不变量集合。拆成函数是为了反例能对**篡改后的源码**跑同一套判断。 */\nconst structural = (code) => {\n  const out = []\n  const add = (n, ok, d = '') => out.push({ name: n, ok, detail: d })\n\n  {\n    const wired = /dashCount > 0[\\s\\S]{0,240}?Array\\.from\\(\\{\\s*length:\\s*dashCount\\s*\\}[\\s\\S]{0,320}?backgroundColor:\\s*getDashColor\\(index\\)/.test(code)\n    add('invariant 1: 每一小段的底色都来自 getDashColor(index)（淡出不是死代码）', wired,\n      wired ? '已接线' : '渲染里找不到逐段上色的调用')\n  }\n\n  {\n    const step = /const\\s+dashStep\\s*=\\s*scaleSizeW\\(DASH_LEN\\)\\s*\\+\\s*scaleSizeW\\(DASH_GAP\\)/.test(code)\n    const count = /const\\s+dashCount\\s*=\\s*dashWidth\\s*>\\s*0\\s*&&\\s*dashStep\\s*>\\s*0\\s*\\?\\s*Math\\.floor\\(\\(dashWidth\\s*\\+\\s*scaleSizeW\\(DASH_GAP\\)\\)\\s*\\/\\s*dashStep\\)\\s*:\\s*0/.test(code)\n    add('invariant 2: 段数按缩放后的段宽/间距推算（字号放大后仍铺满、不留右侧空白）', step && count,\n      `dashStep 缩放=${step} dashCount 算式=${count}`)\n  }\n\n  {\n    const dashed = /borderStyle\\s*:\\s*['\"]dashed['\"]/.test(code)\n    add(\"invariant 3: 未使用 borderStyle:'dashed'（iOS 上 1px 虚线边框不可见）\", !dashed,\n      dashed ? '出现了 dashed 边框写法' : '仍是自绘色块')\n  }\n\n  {\n    const opacityOnParts = /(?:^|\\n)\\s*(?:dash|line)\\s*:\\s*\\{[^}]*\\bopacity\\b/.test(code)\n    add('invariant 4: 淡出只用颜色 alpha（dash/line 样式里不挂 opacity）', !opacityOnParts,\n      opacityOnParts ? '样式里出现了 opacity' : '未出现')\n  }\n\n  {\n    const spanShape = /\\(ratio\\s*-\\s*DASH_FADE_START_RATIO\\)\\s*\\/\\s*DASH_FADE_SPAN_RATIO/.test(code)\n    const legacyShape = /1\\s*-\\s*DASH_FADE_START_RATIO/.test(code)\n    add('invariant 5: 淡入宽度取 DASH_FADE_SPAN_RATIO，且没有退回 (1 - START) 的摊开式',\n      spanShape && !legacyShape, `取 SPAN=${spanShape} 旧算式残留=${legacyShape}`)\n  }\n\n  {\n    const height = /const\\s+DASH_HEIGHT\\s*=\\s*1/.test(code)\n    const used = /height:\\s*DASH_HEIGHT/.test(code)\n    const len = /const\\s+DASH_LEN\\s*=\\s*3/.test(code) && /const\\s+DASH_GAP\\s*=\\s*2/.test(code)\n    add('invariant 6: 虚线仍是 1px 高的小色块拼出来的（DASH_LEN/GAP/HEIGHT 齐备）',\n      height && used && len, `高=${height && used} 段长/间距=${len}`)\n  }\n\n  return out\n}\n\nconsole.log('\\n--- B. 结构不变量（PlayLine.tsx） ---')\nconst results = []\nfor (const r of structural(CODE)) results.push({ group: '不变量', ...r })\n\nconsole.log('\\n--- C. 反例自检（篡改后的源码必须被同一套不变量拦下） ---')\nconst tamper = [\n  {\n    label: '① 逐段上色改回单色（淡出形同不存在）',\n    mutate: (s) => s.replace('backgroundColor: getDashColor(index)', 'backgroundColor: rgb'),\n  },\n  {\n    label: '② 段数写死（字号放大后虚线铺不满）',\n    mutate: (s) => s.replace(/const\\s+dashCount\\s*=[\\s\\S]{0,120}?:\\s*0/, 'const dashCount = 40'),\n  },\n  {\n    label: '③ 淡入退回摊开式（1/3 之后仍看不见）',\n    mutate: (s) => s.replace('(ratio - DASH_FADE_START_RATIO) / DASH_FADE_SPAN_RATIO', '(ratio - DASH_FADE_START_RATIO) / (1 - DASH_FADE_START_RATIO)'),\n  },\n  {\n    label: '④ 用 opacity 做淡出（会把色块本身也吃掉）',\n    mutate: (s) => s.replace(/dash:\\s*\\{/, 'dash: {\\n    opacity: 0.5,'),\n  },\n]\nfor (const c of tamper) {\n  const patched = c.mutate(CODE)\n  if (patched === CODE) {\n    results.push({ group: '反例', name: `反例 ${c.label}`, ok: false, detail: '替换未命中：源码已变，反例失效需同步' })\n    continue\n  }\n  const failed = structural(patched).filter((r) => !r.ok)\n  results.push({\n    group: '反例',\n    name: `反例 ${c.label} 被拦下`,\n    ok: failed.length > 0,\n    detail: failed.length\n      ? `命中：${failed.map((r) => r.name.split(':')[0]).join('、')}`\n      : '未被任何不变量拦下（守卫无效）',\n  })\n}\n\n// ---------------------------------------------------------------------------\n// 输出\n// ---------------------------------------------------------------------------\n\nlet lastGroup = ''\nfor (const r of results) {\n  if (r.group !== lastGroup) {\n    console.log(`\\n--- ${r.group} ---`)\n    lastGroup = r.group\n  }\n  if (r.ok) {\n    pass++\n    console.log(`  PASS  ${r.name}`)\n  } else {\n    fail++\n    console.log(`  FAIL  ${r.name}`)\n  }\n  if (r.detail) console.log(`        ${r.detail}`)\n}\n\nconsole.log('\\n' + '='.repeat(70))\nconsole.log(`结果：${pass} 通过 / ${fail} 失败`)\nconsole.log('='.repeat(70))\nprocess.exit(fail ? 1 : 0)\n" },
  { n: "sim-lyric-double-tap-seek.js", s: "/**\n * sim-lyric-double-tap-seek.js\n *\n * 「大歌词双击跳转播放」契约（第 55 轮第 1 条）。\n *\n * 用户原话：**「播放详情页，大小歌词区域，取消单击歌词跳转播放功能，要么改为单击右侧三角\n * 按钮实现歌词跳转，要么双击歌词跳转播放。」** 定案（用户二选一后确认）：**双击跳转**，\n * 浮层右侧的播放三角原样保留（两条路都在）；**只改大歌词**（竖屏 / 横屏），\n * 小歌词（MiniLyric）不动 —— 它的单击是「切到歌词页」，要加双击就得给单击加 300ms 延迟。\n *\n * 改动前的行为：`handleLinePress` 里单击任何一行就 `setProgress(line.time)` 跳转播放，\n * 在歌词页上滑一下就误跳，是用户报的痛点。现在单击只记时间戳、直接 return；\n * 只有「同一行 + 间隔 < LYRIC_DOUBLE_TAP_MS(300)」的第二次点击才走跳转。\n *\n * 本脚本钉五件事（前四件是静态判据，第五件是行为模型）：\n *   ① 窗口常量单源：`lyricAnimation.ts` 导出 `LYRIC_DOUBLE_TAP_MS = 300`，\n *      两个大歌词都从该文件 import（与小歌词回位时长同一种「单源」口径）；\n *   ② 双击门本身：单击分支（门体）只写 `lastLineTapRef` + `return`，\n *      **不得**出现 seek / 定位 / 收浮层 —— 否则「单击即跳转」就回来了；\n *   ③ 门的判据必须同时看「同一行」与「窗口」两个条件（只看时间会把「点 A 行、\n *      紧接着点 B 行」误判成双击 B）；\n *   ④ 双击分支保留原行为：seek 恰好 1 处、在门之后；清定位态 / 收浮层的四件套不变；\n *      三角通道（`handlePlayLine` 的 `setProgress(time)`）本轮一字未动；\n *      小歌词里**不得**出现本轮的窗口常量（防「顺手也改了小歌词」）。\n *   ⑤ 行为模型：把门 1:1 复刻成 JS，断言单击 0 次 seek、双击（同一样、窗口内）1 次 seek、\n *      超窗 / 换行不 seek、边界值 300 与 301 的行为与源码的 `>` 一致。\n *\n * 契约强度说明：①②③④ 是文本级静态断言（通过 ≠ 能编译 ≠ 真机手感对）；\n * ⑤ 是行为级模型证明，证明的是**这个判定逻辑**自洽，不含 RN 触摸事件时序\n *（双击靠 TouchableOpacity 的两次 onPress，若某天 iOS 手势系统把第二次点击吞了，\n * 本脚本看不出来）。\n *\n * 运行：node scripts/sim-lyric-double-tap-seek.js\n * 退出码：不变量全过且反例全被拦下时为 0，否则 1。\n */\n\n'use strict'\n\nconst fs = require('fs')\nconst path = require('path')\n\nconst ROOT = path.join(__dirname, '..')\nconst read = (p) => fs.readFileSync(path.join(ROOT, p), 'utf8').replace(/\\r\\n/g, '\\n')\n/** 去注释：否则「把某行注释掉」或注释里出现的关键字会被当成仍然存在 */\nconst stripComments = (src) => src.replace(/\\/\\*[\\s\\S]*?\\*\\//g, '').replace(/\\/\\/[^\\n]*/g, '')\n\nconst F = {\n  anim: 'src/screens/PlayDetail/lyricAnimation.ts',\n  vertical: 'src/screens/PlayDetail/Vertical/Lyric.tsx',\n  horizontal: 'src/screens/PlayDetail/Horizontal/Lyric.tsx',\n  mini: 'src/screens/PlayDetail/components/MiniLyric.tsx',\n}\nconst RAW = Object.fromEntries(Object.entries(F).map(([k, v]) => [k, read(v)]))\nconst SRC = Object.fromEntries(Object.entries(RAW).map(([k, v]) => [k, stripComments(v)]))\n\nconst DOUBLE_TAP_MS = 300\n/** 双击门的判据原文（三处：源码、判据、模型 —— 必须逐字同构） */\nconst GATE = 'if (lastTap.index !== index || now - lastTap.at > LYRIC_DOUBLE_TAP_MS)'\nconst TAP_IMPORT = /import\\s*\\{[^}]*\\bLYRIC_DOUBLE_TAP_MS\\b[^}]*\\}\\s*from\\s*'@\\/screens\\/PlayDetail\\/lyricAnimation'/\n\nlet pass = 0, fail = 0\nconst results = []\nconst check = (group, name, ok, detail = '') => {\n  results.push({ group, name, ok, detail })\n  ok ? pass++ : fail++\n}\n\n/** 从 anchor（正则，匹配到「开始大括号之前」）之后取出配平的大括号块体（不含两侧大括号） */\nconst blockAfter = (src, anchor) => {\n  const m = anchor.exec(src)\n  if (!m) return null\n  const open = src.indexOf('{', m.index + m[0].length)\n  if (open < 0) return null\n  let depth = 0\n  for (let i = open; i < src.length; i++) {\n    const c = src[i]\n    if (c === '{') depth++\n    else if (c === '}') {\n      depth--\n      if (depth === 0) return src.slice(open + 1, i)\n    }\n  }\n  return null\n}\n\nconst countOf = (s, needle) => s.split(needle).length - 1\n\n/** 唯一命中才替换：命中数 ≠ 1 直接抛错（String.replace 只换第一处，锚点不唯一会静默假通过） */\nconst tamper = (src, from, to) => {\n  const n = countOf(src, from)\n  if (n !== 1) throw new Error(`反例锚点命中 ${n} 次（应为 1 次）：${JSON.stringify(from.slice(0, 60))}`)\n  return src.replace(from, to)\n}\n\nconst LINE_PRESS_ANCHOR = /const handleLinePress = useCallback\\(\\(index: number\\) =>/\nconst PLAY_LINE_ANCHOR = /const handlePlayLine = useCallback\\(\\(time: number\\) =>/\n\n// ---------------------------------------------------------------------------\n// 单个大歌词文件的不变量（竖屏 / 横屏跑同一套；反例对篡改后的源码跑同一套）\n// ---------------------------------------------------------------------------\nfunction fileInvariants(label, src) {\n  const out = []\n  const add = (n, ok, detail = '') => out.push({ name: `${label} · ${n}`, ok, detail })\n\n  const pressDecl = countOf(src, 'const handleLinePress = useCallback(')\n  const body = blockAfter(src, LINE_PRESS_ANCHOR)\n  add('handleLinePress 唯一且函数体可配平提取',\n    pressDecl === 1 && body != null,\n    `声明 ${pressDecl} 处${body ? ` / 函数体 ${body.split('\\n').length} 行` : ' / 函数体未提取到'}`)\n  if (body == null) return out\n\n  // ① 单击分支（双击门体）：只记录 + return\n  const gate = blockAfter(body, /if \\(lastTap\\.index !== index \\|\\| now - lastTap\\.at > LYRIC_DOUBLE_TAP_MS\\)/)\n  if (gate == null) {\n    add('双击门存在（同一行 + 窗口两个条件）', false, '未找到门的 if 块')\n  } else {\n    const records = /lastLineTapRef\\.current = \\{ index, at: now \\}/.test(gate)\n    const returns = /(^|\\n)\\s*return\\b/.test(gate)\n    const leaks = ['global.app_event', 'setProgress(', 'handleScrollToActive(', 'setVisible(', 'setForceScroll(']\n      .filter((k) => gate.includes(k))\n    add('双击门存在（同一行 + 窗口两个条件）', true, '门体 ' + gate.trim().split('\\n').length + ' 行')\n    add('单击分支只记时间戳（lastLineTapRef = { index, at: now }）并立即 return',\n      records && returns, `记录=${records} 早退=${returns}`)\n    add('单击分支不得 seek / 定位 / 收浮层（否则「单击即跳转」回归）',\n      leaks.length === 0, leaks.length ? `混入：${leaks.join('、')}` : '无越界语句')\n  }\n\n  // ② 门只看时间不行：必须同时比对行号\n  add('门的判据含「同一行」比对（lastTap.index !== index）',\n    body.includes('lastTap.index !== index'), GATE)\n\n  // ③ seek 在门之后，且恰好 1 处\n  const seekIdx = body.indexOf('global.app_event.setProgress(')\n  const gateIdx = body.indexOf('LYRIC_DOUBLE_TAP_MS')\n  add('跳转 seek 恰好 1 处，且位置在双击门之后',\n    countOf(body, 'global.app_event.setProgress(') === 1 && seekIdx > gateIdx && gateIdx >= 0,\n    `seek ${countOf(body, 'global.app_event.setProgress(')} 处 / 函数体内偏移：门 @${gateIdx}、seek @${seekIdx}`)\n\n  // ④ 双击分支的清理四件套（原行为不能丢）\n  const clean = ['isPauseScrollRef.current = false', 'dragStartOffsetRef.current = null',\n    'isOverlayShownRef.current = false', 'playLineRef.current?.setVisible(false)']\n    .filter((k) => body.includes(k))\n  add('双击分支仍清定位态 / 收浮层（四件套一字未丢）',\n    clean.length === 4, `命中 ${clean.length}/4：${clean.length === 4 ? '齐' : clean.join('、')}`)\n\n  // ⑤ 窗口常量来自单源\n  const tapRef = /const lastLineTapRef = useRef<\\{ index: number, at: number \\}>\\(\\{ index: -1, at: 0 \\}\\)/\n  add('lastLineTapRef 用 ref（单击不触发重渲染）且初值 index=-1 / at=0',\n    tapRef.test(src), tapRef.test(src) ? '声明在位' : '未找到声明')\n  add('窗口常量从 lyricAnimation 单源引入（不在本文件另写字面量）',\n    TAP_IMPORT.test(src) && !/const LYRIC_DOUBLE_TAP_MS = \\d+/.test(src),\n    `导入=${TAP_IMPORT.test(src)} 本地字面量=${/const LYRIC_DOUBLE_TAP_MS = \\d+/.test(src)}`)\n\n  // ⑥ 三角通道本轮未动\n  const playBody = blockAfter(src, PLAY_LINE_ANCHOR)\n  add('浮层播放三角通道仍在（handlePlayLine 内 setProgress(time)）',\n    playBody != null && playBody.includes('global.app_event.setProgress(time)'),\n    playBody ? `setProgress(time) ${countOf(playBody, 'global.app_event.setProgress(time)')} 处` : 'handlePlayLine 未提取到')\n\n  return out\n}\n\nconsole.log('sim-lyric-double-tap-seek：大歌词双击跳转播放契约\\n')\nconsole.log('='.repeat(92))\n\n// ---------------------------------------------------------------------------\n// A. 窗口常量单源 + 只改大歌词的边界（小歌词不动是用户二选一的定案）\n// ---------------------------------------------------------------------------\n{\n  const declared = new RegExp(`export const LYRIC_DOUBLE_TAP_MS = (\\\\d+)`).exec(SRC.anim)\n  check('A 窗口常量', `lyricAnimation 导出 LYRIC_DOUBLE_TAP_MS = ${DOUBLE_TAP_MS}`,\n    declared != null && Number(declared[1]) === DOUBLE_TAP_MS,\n    declared ? `= ${declared[1]}` : '未找到导出')\n\n  const miniTouched = SRC.mini.includes('LYRIC_DOUBLE_TAP_MS')\n  const miniPress = /const handlePress = useCallback\\(\\(\\) => \\{\\s*onPress\\?\\.\\(\\)\\s*\\}, \\[onPress\\]\\)/.test(SRC.mini)\n  check('A 只改大歌词', '小歌词（MiniLyric）未被本轮波及：无窗口常量、单击仍是「切到歌词页」',\n    !miniTouched && miniPress,\n    `出现窗口常量=${miniTouched} 单击透传 onPress?.()=${miniPress}`)\n}\n\n// ---------------------------------------------------------------------------\n// B. 两个大歌词的结构不变量\n// ---------------------------------------------------------------------------\nfor (const [key, label] of [['vertical', '竖屏大歌词'], ['horizontal', '横屏大歌词']]) {\n  for (const r of fileInvariants(label, SRC[key])) {\n    check('B 结构不变量', r.name, r.ok, r.detail)\n  }\n}\n\n// ---------------------------------------------------------------------------\n// C. 行为模型：1:1 复刻双击门\n// ---------------------------------------------------------------------------\n{\n  // 复刻源码门的语义（与 GATE 逐字同构）：同一行 + 间隔 ≤ 窗口 ⇒ 双击\n  const makeHandler = () => {\n    const state = { index: -1, at: 0 }\n    const seeks = []\n    return {\n      seeks,\n      press: (index, now) => {\n        const lastTap = state\n        if (lastTap.index !== index || now - lastTap.at > DOUBLE_TAP_MS) {\n          state.index = index\n          state.at = now\n          return\n        }\n        state.index = -1\n        state.at = 0\n        seeks.push(index)\n      },\n    }\n  }\n  const run = (presses) => {\n    const h = makeHandler()\n    for (const [index, at] of presses) h.press(index, at)\n    return h.seeks\n  }\n\n  const cases = [\n    ['单击一次不跳转', [[3, 0]], []],\n    ['双击同一行（间隔 120ms）跳转一次，行号正确', [[3, 0], [3, 120]], [3]],\n    ['双击间隔超窗（400ms）按两次单击处理，不跳转', [[3, 0], [3, 400]], []],\n    ['点 A 行后紧接着点 B 行（间隔 100ms）不算双击（不能误跳）', [[3, 0], [4, 100]], []],\n    ['A→A→B（0/100/200ms）：A 被判双击跳一次，B 只是新的第一次', [[3, 0], [3, 100], [4, 200]], [3]],\n    ['边界：间隔恰为窗口值 300ms 仍算双击（源码用 >，不是 >=）', [[3, 0], [3, 300]], [3]],\n    ['边界：间隔 301ms 不算双击', [[3, 0], [3, 301]], []],\n    ['三连击（A→A→A，0/100/200ms）只跳一次：命中后状态立即复位', [[3, 0], [3, 100], [3, 200]], [3]],\n  ]\n  for (const [name, presses, want] of cases) {\n    const got = run(presses)\n    check('C 行为模型', `模型：${name}`,\n      JSON.stringify(got) === JSON.stringify(want),\n      `按下 ${JSON.stringify(presses)} → seek ${JSON.stringify(got)}（期望 ${JSON.stringify(want)}）`)\n  }\n\n  // 模型必须与源码逐字同构，否则模型证明的不是源码\n  const modelSame = SRC.vertical.includes(GATE) && SRC.horizontal.includes(GATE)\n  check('C 行为模型', '模型用的判据与两个大歌词源码逐字同构',\n    modelSame, modelSame ? GATE : '源码里的门与模型不一致')\n}\n\n// ---------------------------------------------------------------------------\n// D. 反例：每条改动都必须被某个不变量拦下\n// ---------------------------------------------------------------------------\nconst tamperCases = [\n  {\n    label: '竖屏：删掉单击分支的 return（单击又直接往下走）',\n    file: 'vertical',\n    mutate: (s) => tamper(s,\n      '      lastLineTapRef.current = { index, at: now }\\n      return\\n',\n      '      lastLineTapRef.current = { index, at: now }\\n'),\n  },\n  {\n    label: '竖屏：单击分支里掺一句 seek（凭「点一下也跳」）',\n    file: 'vertical',\n    mutate: (s) => tamper(s,\n      '      lastLineTapRef.current = { index, at: now }\\n      return\\n',\n      '      lastLineTapRef.current = { index, at: now }\\n      global.app_event.setProgress(0)\\n      return\\n'),\n  },\n  {\n    label: '竖屏：门里的记录写成 { index: -1, at: 0 }（永远凑不成双击）',\n    file: 'vertical',\n    mutate: (s) => tamper(s,\n      'lastLineTapRef.current = { index, at: now }',\n      'lastLineTapRef.current = { index: -1, at: 0 }'),\n  },\n  {\n    label: '竖屏：门丢掉「同一行」比对，只看时间（点 A 再点 B 会被误判双击）',\n    file: 'vertical',\n    mutate: (s) => tamper(s, 'lastTap.index !== index || ', ''),\n  },\n  {\n    label: '竖屏：窗口比较改成恒真（>= 0），双击永远不成立',\n    file: 'vertical',\n    mutate: (s) => tamper(s, 'now - lastTap.at > LYRIC_DOUBLE_TAP_MS', 'now - lastTap.at >= 0'),\n  },\n  {\n    label: '竖屏：import 里去掉窗口常量（改为本地字面量）',\n    file: 'vertical',\n    mutate: (s) => tamper(s, 'LINE_CHANGE_HOLD_MS, LYRIC_DOUBLE_TAP_MS, OVERLAY_FADE_MS',\n      'LINE_CHANGE_HOLD_MS, OVERLAY_FADE_MS')\n      .replace('const handleLinePress = useCallback((index: number) => {',\n        'const LYRIC_DOUBLE_TAP_MS = 300\\n  const handleLinePress = useCallback((index: number) => {'),\n  },\n  {\n    label: '竖屏：双击分支里丢掉「收浮层」（点完行浮层还挂着）',\n    file: 'vertical',\n    mutate: (s) => tamper(s, '    playLineRef.current?.setVisible(false)\\n    const line = lyricLines[index]', '    const line = lyricLines[index]'),\n  },\n  {\n    label: '竖屏：双击分支里的 seek 被删掉（双击什么都不做）',\n    file: 'vertical',\n    mutate: (s) => tamper(s,\n      '      global.app_event.setProgress(line.time / 1000)\\n',\n      ''),\n  },\n  {\n    label: '竖屏：三角通道的 seek 被删掉（只剩双击一条路）',\n    file: 'vertical',\n    mutate: (s) => tamper(s, '    global.app_event.setProgress(time)\\n  }, [])\\n\\n  useEffect(() => {', '  }, [])\\n\\n  useEffect(() => {'),\n  },\n  {\n    label: '横屏：删掉单击分支的 return（单击又直接往下走）',\n    file: 'horizontal',\n    mutate: (s) => tamper(s,\n      '      lastLineTapRef.current = { index, at: now }\\n      return\\n',\n      '      lastLineTapRef.current = { index, at: now }\\n'),\n  },\n  {\n    label: '横屏：门丢掉「同一行」比对，只看时间',\n    file: 'horizontal',\n    mutate: (s) => tamper(s, 'lastTap.index !== index || ', ''),\n  },\n  {\n    label: 'anim：窗口常量被改成 0（双击不可能成立）',\n    file: 'anim',\n    mutate: (s) => tamper(s, 'export const LYRIC_DOUBLE_TAP_MS = 300', 'export const LYRIC_DOUBLE_TAP_MS = 0'),\n  },\n  {\n    label: 'mini：顺手给小歌词也加双击（用户明确说不动它）',\n    file: 'mini',\n    mutate: (s) => tamper(s,\n      '  const handlePress = useCallback(() => {\\n    onPress?.()\\n  }, [onPress])',\n      '  const handlePress = useCallback(() => {\\n    if (Date.now() - 0 > LYRIC_DOUBLE_TAP_MS) return\\n    onPress?.()\\n  }, [onPress])'),\n  },\n]\n\nfor (const c of tamperCases) {\n  let patched = null\n  try {\n    patched = c.mutate(SRC[c.file])\n  } catch (e) {\n    check('D 反例', `反例 ${c.label} 的锚点仍唯一命中`, false, String(e.message || e))\n    continue\n  }\n  if (patched === SRC[c.file]) {\n    check('D 反例', `反例 ${c.label} 被拦下`, false, '替换未命中：源码已变，反例失效需同步')\n    continue\n  }\n  // 与真跑同一套口径：竖屏/横屏跑文件不变量，另两个文件跑 A 组的全局判据\n  let failed\n  if (c.file === 'vertical' || c.file === 'horizontal') {\n    failed = fileInvariants(c.file === 'vertical' ? '竖屏大歌词' : '横屏大歌词', patched).filter((r) => !r.ok)\n  } else if (c.file === 'anim') {\n    const m = /export const LYRIC_DOUBLE_TAP_MS = (\\d+)/.exec(patched)\n    failed = (m != null && Number(m[1]) === DOUBLE_TAP_MS) ? [] : [{ name: '常量值' }]\n  } else {\n    const m = !patched.includes('LYRIC_DOUBLE_TAP_MS') &&\n      /const handlePress = useCallback\\(\\(\\) => \\{\\s*onPress\\?\\.\\(\\)\\s*\\}, \\[onPress\\]\\)/.test(patched)\n    failed = m ? [] : [{ name: '小歌词边界' }]\n  }\n  check('D 反例', `反例 ${c.label} 被拦下`, failed.length > 0,\n    failed.length ? `命中：${failed.map((r) => r.name.split('· ').pop()).join('、')}` : '未被任何不变量拦下（守卫无效）')\n}\n\n// ---------------------------------------------------------------------------\n// 输出\n// ---------------------------------------------------------------------------\nlet lastGroup = ''\nfor (const r of results) {\n  if (r.group !== lastGroup) {\n    console.log(`\\n--- ${r.group} ---`)\n    lastGroup = r.group\n  }\n  console.log(`  ${r.ok ? 'PASS' : 'FAIL'}  ${r.name}`)\n  if (r.detail) console.log(`        ${r.detail}`)\n}\n\nconsole.log('\\n' + '='.repeat(92))\nconsole.log(`结果：${pass} 通过 / ${fail} 失败`)\nconsole.log('='.repeat(92))\nprocess.exit(fail ? 1 : 0)\n" },
  { n: "sim-lyric-manual-position.js", s: "/**\n * sim-lyric-manual-position.js\n *\n * 「歌词手动定位跳转播放」（PlayLine 浮层）契约。\n *\n * 背景：浮层由三处挂载——同屏小歌词（MiniLyric，本批之前就有）、竖屏大歌词\n * （Vertical/Lyric.tsx）、横屏大歌词（Horizontal/Lyric.tsx，本批补齐）。浮层本身是\n * 纯展示件（`PlayLine.tsx`），它的正确性**完全**依赖调用方喂进来的三样东西：\n *   ① `updateScrollInfo(滚动事件)`  —— 列表真实偏移 + 视口高度；\n *   ② `updateLayoutInfo({ spaceHeight, lineHeights })` —— 基准线上方的留白 + 逐行行高；\n *   ③ `topPercent` —— 基准线在容器高度上的位置。\n * 三者只要有一个与「高亮行定位」的口径不一致，用户看到的就是「虚线压在 A 行、\n * 点播放三角却跳到 B 行」——而且浮层照样显示、点击照样有反应，属于最难自查的一类。\n *\n * 本脚本做两件事：\n *   A. 数值模型：1:1 复刻 `PlayLine` 的选行循环与 `LyricScrollLayout.getTargetOffsetPrecise`\n *      的居中公式，证明「topPercent = 0.5 且 spaceHeight = 视高/2」时，虚线必然落在\n *      被 `handleScrollToActive` 居中的那一行上（含激活行更高时的鲁棒性）；并给出\n *      topPercent = 0.4（参考工程大歌词的原值）作为反例——它会稳定偏一行。\n *   B. 结构不变量：三处挂载点的渲染门控、几何表达式、seek 收口、以及拖动生命周期\n *      （`dragStartOffsetRef` 的赋值与清空必须成对，因为它是「用户正在拖」的唯一判据）。\n *   B2. 回位时长同速：小歌词（MiniLyric）停手回位与竖屏大歌词的回位滑动必须同值同源\n *      （lyricAnimation.RETURN_TO_ACTIVE_MS）——用户报过「小歌词滑完返回播放进度比大歌词快」。\n *\n * 契约强度说明：B 部分是静态断言（源码文本级），通过 ≠ 能编译 ≠ 真机观感对；\n * A 部分是模型级证明，证明的是**公式之间**自洽，不含 RN 布局/原生事件时序。\n *\n * 运行：node scripts/sim-lyric-manual-position.js\n * 退出码：不变量全过且反例全被拦下时为 0，否则 1。\n */\n\n'use strict'\n\nconst fs = require('fs')\nconst path = require('path')\n\nconst ROOT = path.join(__dirname, '..')\nconst read = (p) => fs.readFileSync(path.join(ROOT, p), 'utf8').replace(/\\r\\n/g, '\\n')\n/** 去行注释与块注释：否则「把某行注释掉」的篡改会被当成仍然存在 */\nconst stripComments = (src) => src.replace(/\\/\\*[\\s\\S]*?\\*\\//g, '').replace(/\\/\\/[^\\n]*/g, '')\n\nconst F = {\n  playLine: 'src/screens/PlayDetail/components/PlayLine.tsx',\n  lyricScroll: 'src/utils/lyricScroll.ts',\n  mini: 'src/screens/PlayDetail/components/MiniLyric.tsx',\n  vertical: 'src/screens/PlayDetail/Vertical/Lyric.tsx',\n  horizontal: 'src/screens/PlayDetail/Horizontal/Lyric.tsx',\n}\nconst REAL = Object.fromEntries(Object.entries(F).map(([k, v]) => [k, read(v)]))\n\n// 三处浮层各自的视高来源变量名不同（小歌词 topPadding / 竖屏 pageHeightRef / 横屏 listHeightRef），\n// 但**倍率必须都是 0.5**，且必须与各自 handleScrollToActive 的 viewPosition 一致。\nconst TOP_PERCENT = 0.5\n\n// ---------------------------------------------------------------------------\n// A. 数值模型\n// ---------------------------------------------------------------------------\n\n/** 复刻 LyricScrollLayout.getTargetOffsetPrecise（spaceHeight=0、useActiveHeight=true、usePlayed=false 路径） */\nconst targetOffsetPrecise = ({ index, listHeight, heights, viewPosition = 0.5, paddingV = 0 }) => {\n  let offset = 0\n  for (let i = 0; i < index; i++) offset += heights[i]\n  const itemHeight = heights[index]\n  return Math.max(0, paddingV + offset + itemHeight * viewPosition - listHeight * viewPosition)\n}\n\n/** 复刻 PlayLine 的选行循环（PlayLine.tsx:138-147 逐句对应） */\nconst pickLine = ({ contentOffsetY, layoutMeasurementHeight, topPercent, spaceHeight, lineHeights }) => {\n  const offset = contentOffsetY + layoutMeasurementHeight * topPercent\n  let lineOffset = spaceHeight\n  for (let line = 0; line < lineHeights.length; line++) {\n    lineOffset += lineHeights[line]\n    if (lineOffset < offset) continue\n    return line\n  }\n  return lineHeights.length - 1\n}\n\n// 一屏高 700、54 行歌词：其中每 7 行有一行长句（行高 ≈ 2 倍，实测约 71/108）\nconst H = 700\nconst heights = Array.from({ length: 54 }, (_, i) => (i % 7 === 3 ? 108 : i % 5 === 2 ? 71 : 54))\nconst SPACE = H * 0.5\n\nlet pass = 0, fail = 0\nconst check = (name, ok, detail) => {\n  console.log(`  ${ok ? '✓' : '✗'} ${name}${detail ? '  — ' + detail : ''}`)\n  ok ? pass++ : fail++\n}\n\nconsole.log('sim-lyric-manual-position：歌词手动定位浮层契约\\n')\nconsole.log('--- A. 数值模型（虚线落点 vs 居中行） ---')\n\n/** 返回全部 54 行的「虚线指向行 - 居中行」偏差列表 */\nconst offsetsFor = ({ topPercent, spaceHeight, paddingV = H * 0.5, viewPosition = 0.5, hs = heights }) => {\n  const out = []\n  for (let i = 0; i < hs.length; i++) {\n    const T = targetOffsetPrecise({ index: i, listHeight: H, heights: hs, viewPosition, paddingV })\n    const picked = pickLine({\n      contentOffsetY: T,\n      layoutMeasurementHeight: H,\n      topPercent,\n      spaceHeight,\n      lineHeights: hs,\n    })\n    out.push(picked - i)\n  }\n  return out\n}\n\n{\n  // 断言 1：本批的参数（topPercent=0.5、spaceHeight=H/2、paddingV=H/2、viewPosition=0.5）\n  // → 虚线与居中行**逐行相等**（偏差全 0），即点播放三角永远跳到你看到的那一行。\n  const d = offsetsFor({ topPercent: TOP_PERCENT, spaceHeight: SPACE })\n  const worst = Math.max(...d.map(Math.abs))\n  check('topPercent=0.5 且 spaceHeight=视高/2 → 54 行逐行零偏差（虚线 = 居中行）',\n    worst === 0, `最大偏差 ${worst} 行（全 0 才对）`)\n}\n\n{\n  // 断言 2（鲁棒性）：激活行因换行被挤成 2 倍高（useActiveHeight 用的就是这份高度，\n  // 而喂给浮层的是非激活高度）时，落点是否仍落在同一行。\n  // 数学：选行条件为 cum(i)+space ≥ offset > cum(i)+space-... 只要求 h_i^normal ≥ h_i^active/2，\n  // 长句最多挤到 2 倍，故恒成立——这条断言把这个不等式钉住。\n  const hs = heights.slice()\n  const doubled = hs.map((_, i) => i)\n  const out = []\n  for (const i of doubled) {\n    const active = hs.slice()\n    active[i] = hs[i] * 2 // 激活行高度翻倍\n    const T = targetOffsetPrecise({ index: i, listHeight: H, heights: active, viewPosition: 0.5, paddingV: H * 0.5 })\n    const picked = pickLine({\n      contentOffsetY: T,\n      layoutMeasurementHeight: H,\n      topPercent: TOP_PERCENT,\n      spaceHeight: SPACE,\n      lineHeights: hs, // 浮层拿到的是非激活高度\n    })\n    out.push(picked - i)\n  }\n  const worst = Math.max(...out.map(Math.abs))\n  check('激活行高度翻倍时落点仍不偏（选行只需 h_normal ≥ h_active/2）',\n    worst === 0, `最大偏差 ${worst} 行`)\n}\n\n{\n  // 断言 3（反例）：topPercent 沿用参考工程大歌词的 0.4 → 虚线恒定偏一行。\n  // 这是本工程**刻意**不照抄参考值的地方：参考工程把高亮行钉在 40%，本工程钉在正中，\n  // 浮层若照抄 0.4 就会「看到一行、跳到上一行」。\n  const d = offsetsFor({ topPercent: 0.4, spaceHeight: SPACE })\n  const off = d.filter((x) => x !== 0).length\n  check('反例：topPercent=0.4（参考工程原值）→ 大量行偏一行（证明必须随定位口径改 0.5）',\n    off > heights.length / 2, `${off}/${heights.length} 行落点偏离`)\n}\n\n{\n  // 断言 4（反例）：spaceHeight 与定位用的 paddingV 不一致（浮层留白取 0）→ 落点整体偏移。\n  const d = offsetsFor({ topPercent: TOP_PERCENT, spaceHeight: 0 })\n  const off = d.filter((x) => x !== 0).length\n  check('反例：spaceHeight 未与定位留白同源（取 0）→ 落点整体偏移',\n    off > heights.length / 2, `${off}/${heights.length} 行落点偏离`)\n}\n\n{\n  // 断言 5（反例）：viewPosition 与 topPercent 不一致（定位改 0.4、浮层留 0.5）同样偏。\n  const d = offsetsFor({ topPercent: TOP_PERCENT, spaceHeight: SPACE, viewPosition: 0.4 })\n  const off = d.filter((x) => x !== 0).length\n  check('反例：定位 viewPosition 改了而浮层 topPercent 没跟着改 → 落点偏离',\n    off > heights.length / 2, `${off}/${heights.length} 行落点偏离`)\n}\n\n{\n  // 断言 6：浮层选出的行 → 时间标签取的就是该行时间（`lyricLines[targetLineNum].time`），\n  // 并收口到 maxPlayTime 之前 0.5s。模型：末尾行时间恰等于总时长时，seek 目标必须 < 总时长，\n  // 否则会被播完判定当成「已到结尾」直接切下一首。\n  const maxPlayTime = 245\n  const lineTimes = [0, 12.5, 30, 60, 120, 180, 245]\n  const seekTargets = lineTimes.map((t) => (maxPlayTime > 0 && t >= maxPlayTime ? Math.max(maxPlayTime - 0.5, 0) : t))\n  const allUnder = seekTargets.every((t) => t < maxPlayTime)\n  const lastIsClamped = seekTargets[seekTargets.length - 1] === 244.5\n  check('末行时间 = 总时长时 seek 目标收口到 总时长-0.5（不会被当成播完而切歌）',\n    allUnder && lastIsClamped, `末行目标 ${seekTargets[seekTargets.length - 1]}s / 总时长 ${maxPlayTime}s`)\n}\n\n// ---------------------------------------------------------------------------\n// B. 结构不变量（三处挂载点）\n// ---------------------------------------------------------------------------\n\n/**\n * 单个挂载点的不变量。`src` = 组件源码（已去注释），`label` = 显示名。\n * 拆成函数是为了反例能对**篡改后的源码**跑同一套判断。\n */\nfunction surfaceInvariants(label, src) {\n  const out = []\n  const add = (n, ok, detail = '') => out.push({ name: `${label} · ${n}`, ok, detail })\n\n  // 1. 浮层渲染：必须挂 ref / topPercent / onPlayLine 三件套，且由设置位门控\n  {\n    const render = new RegExp(\n      `<PlayLine\\\\s+ref=\\\\{playLineRef\\\\}\\\\s+topPercent=\\\\{${String(TOP_PERCENT).replace('.', '\\\\.')}\\\\}\\\\s+onPlayLine=\\\\{handlePlayLine\\\\}\\\\s*/>`,\n    ).test(src)\n    const gated = /isShowLyricProgress\\s*\\?\\s*\\([\\s\\S]{0,400}?<PlayLine[\\s\\S]{0,400}?\\)\\s*:\\s*null/.test(src)\n    const setting = /const\\s+isShowLyricProgress\\s*=\\s*useSettingValue\\(['\"]playDetail\\.isShowLyricProgressSetting['\"]\\)/.test(src)\n    add('invariant 1: <PlayLine topPercent={0.5} onPlayLine> 由 isShowLyricProgress 门控',\n      render && gated && setting,\n      `渲染=${render} 门控=${gated} 读设置=${setting}`)\n  }\n\n  // 2. 几何同源：喂浮层的 spaceHeight 必须是「视高 × 0.5」，倍率与定位口径一致\n  {\n    const m = /spaceHeight:\\s*([A-Za-z0-9_.]+)\\s*\\*\\s*(0?\\.\\d+|\\d+)/.exec(src)\n    const ok = m != null && Number(m[2]) === TOP_PERCENT\n    add(`invariant 2: spaceHeight = 视高 × ${TOP_PERCENT}（与 topPercent 同倍率）`,\n      ok, m ? `取到 ${m[1]} * ${m[2]}` : '未找到 spaceHeight 表达式')\n  }\n\n  // 3. 定位口径：居中定位（viewPosition 0.5）与上下留白必须同时存在\n  {\n    const centered = /getTargetOffsetPrecise\\([\\s\\S]{0,200}?,\\s*0\\.5\\s*,/.test(src)\n    // 上下留白：竖屏/横屏写在 contentContainerStyle（或 listPadding），值 = 视高 × 0.5\n    const padding = /(?:paddingTop|paddingV)[\\s\\S]{0,120}?\\*\\s*0\\.5/.test(src)\n    add('invariant 3: 定位 viewPosition=0.5 且上下留白 = 视高 × 0.5（与浮层同源）',\n      centered && padding, `居中定位=${centered} 留白×0.5=${padding}`)\n  }\n\n  // 4. 浮层几何在进入拖动时快照，且行高取自 LyricScrollLayout（与定位同一份缓存）\n  {\n    const snapshot = /playLineRef\\.current\\?\\.updateLayoutInfo\\(/.test(src)\n    const heights = /lyricScrollLayoutRef\\.current\\.getLineHeights\\(lyricLines\\.length\\)/.test(src)\n    add('invariant 4: updateLayoutInfo 用 LyricScrollLayout.getLineHeights（与定位同一份行高）',\n      snapshot && heights, `喂几何=${snapshot} 行高来源=${heights}`)\n  }\n\n  // 5. seek 收口：末行时间等于总时长时收回到总长之前（否则被当成播完而切歌），\n  //    且只 seek、不提前滚列表（避免「先滚回旧行再滑向新行」的二次动画）\n  {\n    const clamp = /const\\s+maxTime\\s*=\\s*playerState\\.progress\\.maxPlayTime/.test(src) &&\n      /time\\s*=\\s*Math\\.max\\(maxTime\\s*-\\s*0\\.5,\\s*0\\)/.test(src)\n    const seek = /global\\.app_event\\.setProgress\\(time\\)/.test(src)\n    const body = /\\n\\s*const handlePlayLine = useCallback\\(\\(time: number\\) => \\{([\\s\\S]*?)\\n\\s*\\}, \\[\\]\\)/.exec(src)\n    const noDoubleAnim = body != null && !/handleScrollToActive\\(/.test(body[1])\n    add('invariant 5: handlePlayLine 收口到 总时长-0.5 后只 seek（不提前滚列表）',\n      clamp && seek && noDoubleAnim, `收口=${clamp} seek=${seek} 无二次滚动=${noDoubleAnim}`)\n  }\n\n  // 6. 拖动生命周期：dragStartOffsetRef 是「用户正在拖」的唯一判据，\n  //    它必须在 handleScroll 里被用作门控，且**每一个**收起浮层的调用点所在的代码块里\n  //    都要清空它。漏一条的症状：浮层在自动回位/自动跟随时被重新弹出来，虚线乱扫。\n  //    ⚠️ 判据必须锚在「同一个代码块」上，不能用「前后 400 字符内出现过清空」：\n  //    onScrollEndDrag 的早退分支（只清不收起）离超时分支（收起）只有约 200 字符，\n  //    用窗口判据时前者的清空会把后者补齐 —— 恰好漏掉真正危险的那一条（本批修的就是它）。\n  {\n    const gate = /if\\s*\\(dragStartOffsetRef\\.current == null\\)\\s*return/.test(src)\n    const hides = [...src.matchAll(/playLineRef\\.current\\?\\.setVisible\\(false\\)/g)]\n    // 从调用点向前扫到「包含它的那个 { 」：即最近的未闭合块起点\n    const blockStart = (s, idx) => {\n      let depth = 0\n      for (let i = idx - 1; i >= 0; i--) {\n        if (s[i] === '}') depth++\n        else if (s[i] === '{') {\n          if (depth === 0) return i\n          depth--\n        }\n      }\n      return 0\n    }\n    const uncovered = hides.filter((m) => {\n      const seg = src.slice(blockStart(src, m.index), m.index)\n      return !/dragStartOffsetRef\\.current = null/.test(seg)\n    }).length\n    const clears = (src.match(/dragStartOffsetRef\\.current = null/g) ?? []).length\n    add('invariant 6: handleScroll 以 dragStartOffsetRef 非空为门控，且每个收起浮层的代码块内都清空了它',\n      gate && hides.length > 0 && uncovered === 0,\n      `门控=${gate} 收起浮层 ${hides.length} 处，其中所在块内未清空 ${uncovered} 处；清空语句共 ${clears} 处`)\n  }\n\n  // 7. 「是否真的动过」的阈值必须与小歌词同值（三处观感一致）\n  {\n    const m = /const\\s+OVERLAY_SHOW_MOVE\\s*=\\s*(\\d+)/.exec(src)\n    add('invariant 7: OVERLAY_SHOW_MOVE 常量存在（拖动超过阈值才显示浮层）',\n      m != null && Number(m[1]) > 0, m ? `= ${m[1]}pt` : '未找到')\n  }\n\n  return out\n}\n\nconsole.log('\\n--- B. 结构不变量（三处挂载点） ---')\nconst SURFACES = [\n  ['竖屏大歌词', 'vertical'],\n  ['横屏大歌词', 'horizontal'],\n]\nconst results = []\nfor (const [label, key] of SURFACES) {\n  for (const r of surfaceInvariants(label, stripComments(REAL[key]))) {\n    results.push({ group: '不变量', ...r })\n  }\n}\n\n// 小歌词（本批未改，作为另外两处的样板）：只钉「三处观感一致」的那几条，\n// 不套用 invariant 6 的严格清空规则——它有自己成对的显示/隐藏生命周期（含重新显示路径），\n// 且是用户已在真机上确认可用的实现，本批不对它做任何改动。\nfor (const r of surfaceInvariants('小歌词', stripComments(REAL.mini))) {\n  if (r.name.includes('invariant 1') || r.name.includes('invariant 7')) {\n    results.push({ group: '不变量', ...r })\n  }\n}\n\n// 三处 topPercent 必须完全一致（否则三处浮层的基准线含义不同）\n{\n  const percents = [REAL.mini, REAL.vertical, REAL.horizontal].map((src) => {\n    const m = /<PlayLine[\\s\\S]{0,120}?topPercent=\\{([\\d.]+)\\}/.exec(src)\n    return m ? Number(m[1]) : null\n  })\n  results.push({\n    group: '不变量',\n    name: '三处挂载点的 topPercent 完全一致（小歌词 / 竖屏 / 横屏）',\n    ok: percents.every((p) => p === TOP_PERCENT),\n    detail: `取到 ${percents.join(' / ')}`,\n  })\n}\n\n// 浮层的默认值仍是参考工程的 0.4（不许偷偷把默认值改成 0.5 来「让调用点少写一个 prop」：\n// 默认值是「参考工程大歌词在 40% 处」这一语义的记录，改掉会让默认值失去参照意义）\n{\n  const m = /const\\s+DEFAULT_TOP_PERCENT\\s*=\\s*([\\d.]+)/.exec(stripComments(REAL.playLine))\n  results.push({\n    group: '不变量',\n    name: 'PlayLine 默认 topPercent 仍为 0.4（参考工程语义），调用点必须显式传值',\n    ok: m != null && Number(m[1]) === 0.4,\n    detail: m ? `DEFAULT_TOP_PERCENT = ${m[1]}` : '未找到',\n  })\n}\n\n// ---------------------------------------------------------------------------\n// B2. 回位时长同速（用户报的 bug：小歌词滑完返回播放进度时比大歌词快）\n// ---------------------------------------------------------------------------\n//\n// 竖屏大歌词的回位不是另起一套动画：停手后它往连续滚动循环里排一个 glide 任务，\n// 走自己的换行滑动轨迹（固定时长 + easeInOutQuad）。小歌词此前按距离取\n// getReturnDuration（[120,300]），同一屏对比就是「小歌词更快」——用户报的 bug。\n// 现在两边共同引用 lyricAnimation 的 RETURN_TO_ACTIVE_MS，只钉四件事：\n//   ① 共享常量存在且值为对齐参考工程的 600；② 大歌词侧不再写死字面量；\n//   ③ 小歌词侧不再出现按距离取值的旧路；④ 两侧曲线同为 easeInOutQuad\n//（时长相同 + 曲线相同才谈得上「同速」）。\n\nconst ANIM_FILE = 'src/screens/PlayDetail/lyricAnimation.ts'\n\n/** 对 { anim, mini, vertical }（均已去注释）求值；反例可对篡改后的快照跑同一套判断。 */\nfunction returnDurationInvariants(srcs) {\n  const out = []\n  const add = (n, ok, detail = '') => out.push({ group: '不变量', name: n, ok, detail })\n  const { anim, mini, vertical } = srcs\n  const importsShared = (src) =>\n    /import\\s*\\{[^}]*RETURN_TO_ACTIVE_MS[^}]*\\}\\s*from\\s*'@\\/screens\\/PlayDetail\\/lyricAnimation'/.test(src)\n\n  const declared = /export const RETURN_TO_ACTIVE_MS = (\\d+)/.exec(anim)\n  add('invariant 8: lyricAnimation 导出 RETURN_TO_ACTIVE_MS = 600（= 大歌词对齐参考工程的滑动时长）',\n    declared != null && Number(declared[1]) === 600,\n    declared ? `= ${declared[1]}` : '未找到')\n\n  const verticalShared = /LINE_CHANGE_GLIDE_REF_MS = RETURN_TO_ACTIVE_MS/.test(vertical)\n  add('invariant 9: 竖屏大歌词滑动时长 = RETURN_TO_ACTIVE_MS（不再各写一份字面量）',\n    importsShared(vertical) && verticalShared,\n    `导入=${importsShared(vertical)} 赋值同源=${verticalShared}`)\n\n  const miniShared = /duration \\?\\? RETURN_TO_ACTIVE_MS/.test(mini)\n  const miniNoDistance = !/getReturnDuration/.test(mini)\n  add('invariant 10: 小歌词回位 = RETURN_TO_ACTIVE_MS，且不再引用 getReturnDuration（按距离取值正是快慢不一致的来源）',\n    importsShared(mini) && miniShared && miniNoDistance,\n    `导入=${importsShared(mini)} 回位同源=${miniShared} 无按距离取值=${miniNoDistance}`)\n\n  const miniCurve = /eased = t < 0\\.5 \\? 2 \\* t \\* t/.test(mini)\n  const verticalCurve = /eased = p < 0\\.5 \\? 2 \\* p \\* p/.test(vertical)\n  add('invariant 11: 两侧回位曲线同为 easeInOutQuad（时长相同 + 曲线相同 = 完全同速）',\n    miniCurve && verticalCurve, `小歌词=${miniCurve} 大歌词=${verticalCurve}`)\n\n  return out\n}\n\n{\n  const srcs = {\n    anim: stripComments(read(ANIM_FILE)),\n    mini: stripComments(REAL.mini),\n    vertical: stripComments(REAL.vertical),\n  }\n  results.push(...returnDurationInvariants(srcs))\n\n  const tamperReturn = [\n    {\n      label: '⑧ 小歌词回位退回按距离取 getReturnDuration（复现用户报的「小歌词更快」）',\n      key: 'mini',\n      mutate: (s) => s\n        .replace(\n          'import { IDLE_RETURN_MS, LINE_CHANGE_GLIDE_MS, RETURN_TO_ACTIVE_MS }',\n          'import { getReturnDuration, IDLE_RETURN_MS, LINE_CHANGE_GLIDE_MS }',\n        )\n        .replace('duration ?? RETURN_TO_ACTIVE_MS', 'duration ?? getReturnDuration(distance)'),\n    },\n    {\n      label: '⑨ 大歌词把 600 写死回本地（两边各持一份，改一处不再同步）',\n      key: 'vertical',\n      mutate: (s) => s.replace('const LINE_CHANGE_GLIDE_REF_MS = RETURN_TO_ACTIVE_MS', 'const LINE_CHANGE_GLIDE_REF_MS = 600'),\n    },\n    {\n      label: '⑩ 共享常量被改成 designMotion.quick 的 200（回位整体变快、与参考工程定案脱钩）',\n      key: 'anim',\n      mutate: (s) => s.replace('export const RETURN_TO_ACTIVE_MS = 600', 'export const RETURN_TO_ACTIVE_MS = 200'),\n    },\n  ]\n  for (const c of tamperReturn) {\n    const patched = { ...srcs, [c.key]: c.mutate(srcs[c.key]) }\n    if (patched[c.key] === srcs[c.key]) {\n      results.push({ group: '反例', name: `反例 ${c.label}`, ok: false, detail: '替换未命中：源码已变，反例失效需同步' })\n      continue\n    }\n    const failed = returnDurationInvariants(patched).filter((r) => !r.ok)\n    results.push({\n      group: '反例',\n      name: `反例 ${c.label} 被拦下`,\n      ok: failed.length > 0,\n      detail: failed.length\n        ? `命中：${failed.map((r) => r.name.split(':')[0]).join('、')}`\n        : '未被任何不变量拦下（守卫无效）',\n    })\n  }\n}\n\n// ---------------------------------------------------------------------------\n// C. 反例：篡改后的源码必须被同一套不变量拦下\n// ---------------------------------------------------------------------------\n\nconsole.log('\\n--- C. 反例自检 ---')\n\nconst verticalSrc = REAL.vertical\nconst tamper = [\n  {\n    label: '① 去掉设置位门控（浮层永远显示，关掉设置也关不掉）',\n    mutate: (s) => s.replace(/isShowLyricProgress \\? \\(\\s*<PlayLine ref=\\{playLineRef\\} topPercent=\\{0\\.5\\} onPlayLine=\\{handlePlayLine\\} \\/>\\s*\\) : null/,\n      '<PlayLine ref={playLineRef} topPercent={0.5} onPlayLine={handlePlayLine} />'),\n  },\n  {\n    label: '② topPercent 改回参考工程的 0.4（虚线偏一行）',\n    mutate: (s) => s.replace('<PlayLine ref={playLineRef} topPercent={0.5}', '<PlayLine ref={playLineRef} topPercent={0.4}'),\n  },\n  {\n    label: '③ spaceHeight 倍率改错（与 topPercent 不同源）',\n    mutate: (s) => s.replace(/spaceHeight: (listHeight|pageHeightRef\\.current > 0 \\? pageHeightRef\\.current : pagerHeight) \\* 0\\.5/,\n      (m) => m.replace('* 0.5', '* 0.4')),\n  },\n  {\n    label: '④ 删掉末行 seek 收口（点到末行会被当成播完而切歌）',\n    mutate: (s) => s.replace('    if (maxTime > 0 && time >= maxTime) time = Math.max(maxTime - 0.5, 0)\\n', ''),\n  },\n  {\n    label: '⑤ 删掉拖动起点的清空（浮层在自动回位时被重新弹出）',\n    mutate: (s) => s.replace(/\\n\\s*dragStartOffsetRef\\.current = null\\n\\s*isOverlayShownRef\\.current = false\\n\\s*playLineRef\\.current\\?\\.setVisible\\(false\\)\\n\\s*\\/\\/ 到时即回位/,\n      '\\n      isOverlayShownRef.current = false\\n      playLineRef.current?.setVisible(false)\\n      // 到时即回位'),\n  },\n  {\n    label: '⑥ handleScroll 去掉「正在拖」门控（自动跟随每帧都喂浮层）',\n    mutate: (s) => s.replace('if (dragStartOffsetRef.current == null) return', 'if (false) return'),\n  },\n  {\n    label: '⑦ 把 <PlayLine /> 注释掉（去注释后必须失效）',\n    mutate: (s) => s.replace('<PlayLine ref={playLineRef} topPercent={0.5} onPlayLine={handlePlayLine} />',\n      '// <PlayLine ref={playLineRef} topPercent={0.5} onPlayLine={handlePlayLine} />'),\n  },\n]\n\nfor (const c of tamper) {\n  const patched = c.mutate(verticalSrc)\n  if (patched === verticalSrc) {\n    results.push({ group: '反例', name: `反例 ${c.label}`, ok: false, detail: '替换未命中：源码已变，反例失效需同步' })\n    continue\n  }\n  const failed = surfaceInvariants('竖屏大歌词', stripComments(patched)).filter((r) => !r.ok)\n  results.push({\n    group: '反例',\n    name: `反例 ${c.label} 被拦下`,\n    ok: failed.length > 0,\n    detail: failed.length\n      ? `命中：${failed.map((r) => r.name.split('· ')[1].split(':')[0]).join('、')}`\n      : '未被任何不变量拦下（守卫无效）',\n  })\n}\n\n// ---------------------------------------------------------------------------\n// 输出\n// ---------------------------------------------------------------------------\n\nlet lastGroup = ''\nfor (const r of results) {\n  if (r.group !== lastGroup) {\n    console.log(`\\n--- ${r.group} ---`)\n    lastGroup = r.group\n  }\n  if (r.ok) {\n    pass++\n    console.log(`  PASS  ${r.name}`)\n  } else {\n    fail++\n    console.log(`  FAIL  ${r.name}`)\n  }\n  if (r.detail) console.log(`        ${r.detail}`)\n}\n\nconsole.log('\\n' + '='.repeat(70))\nconsole.log(`结果：${pass} 通过 / ${fail} 失败`)\nconsole.log('='.repeat(70))\nprocess.exit(fail ? 1 : 0)\n" },
  { n: "sim-lyric-resume-instant.js", s: "#!/usr/bin/env node\n/**\n * sim-lyric-resume-instant.js —— 「切回来歌词瞬时到位」契约（用户第 12 轮第 1 条）\n *\n * 需求原话（2026-10-02）：播放大歌词在我切换 / 打开 / 退出播放详情页后再次返回时，\n * 会从切走前的旧位置滑一段才追上当前行，太慢；要求「不管从什么地方切回来，只会显示\n * 实时的当前进度」「大小歌词部分也一样，要实时显示歌词加载位置」。\n *\n * 收敛结果（竖屏 Vertical/Lyric.tsx 与横屏 Horizontal/Lyric.tsx 同构）：\n *   rAF 连续滚动循环被**整段停掉**的场景（暂停 isPlay=false、被压栈页盖住\n *   panelVisible=false）在停帧时置 resumeInstantRef=true；恢复首帧（wasPauseRef 分支）\n *   直接走既有 force 通道 handleScrollToActiveRef.current(line, true)\n *   = scrollToOffset({animated:false}) + 把所有平滑基准 / 切行滑动状态对齐到目标，\n *   不再从旧位置播 600ms easeInOutQuad（原来的「慢慢加载歌词位置」）。\n *\n * 边界（刻意保留，脚本一并钉住）：用户手动滚动 / 拖动歌词期间循环**没有**停\n *   （只是逐帧早退），那条路径保持原来的平滑回位观感 —— resumeInstantRef 只在\n *   停帧守卫里置真，且每个文件只允许出现一处 `= true`。\n *\n * 本脚本从源码解析实际结构（不硬编码行号），并为每条关键断言带一个「删掉就该判不合格」\n * 的反例自检。\n *\n * 运行：node scripts/sim-lyric-resume-instant.js\n */\n'use strict'\n\nconst fs = require('fs')\nconst path = require('path')\n\nconst ROOT = path.resolve(__dirname, '..')\nconst read = (p) => fs.readFileSync(path.join(ROOT, p), 'utf8')\n\nconst results = []\nlet failed = 0\nconst check = (label, ok, detail) => {\n  results.push({ label, ok: !!ok, detail })\n  if (!ok) failed++\n}\n\n/** 取一段块体：从 headerRe 命中处起，到第一个「缩进 = indent 个空格的 }」为止。 */\nconst blockBody = (s, headerRe, indent = 4) => {\n  const m = headerRe.exec(s)\n  if (!m) return null\n  const rest = s.slice(m.index + m[0].length)\n  const end = new RegExp(`\\\\n {${indent}}\\\\}`).exec(rest)\n  return end ? rest.slice(0, end.index) : null\n}\n\nconst GUARD_RE = /if \\(!isPlay \\|\\| !panelVisible\\) \\{/\nconst RESUME_RE = /if \\(wasPauseRef\\.current\\) \\{/\nconst CONSUME_RE = /if \\(resumeInstantRef\\.current\\) \\{/\n\nconst FILES = [\n  { name: '竖屏', file: 'src/screens/PlayDetail/Vertical/Lyric.tsx' },\n  { name: '横屏', file: 'src/screens/PlayDetail/Horizontal/Lyric.tsx' },\n]\n\nconsole.log('='.repeat(92))\nconsole.log('「切回来歌词瞬时到位」契约模型（摘自源码）')\nconsole.log('='.repeat(92))\n\nfor (const { name, file } of FILES) {\n  const src = read(file)\n  console.log(`\\n【${name}】${file}`)\n\n  const decl = /const resumeInstantRef = useRef\\(false\\)/.test(src)\n  const totalUses = (src.match(/resumeInstantRef\\.current/g) || []).length\n  const setTrueCount = (src.match(/resumeInstantRef\\.current = true/g) || []).length\n  const setFalseCount = (src.match(/resumeInstantRef\\.current = false/g) || []).length\n\n  const guardBody = blockBody(src, GUARD_RE)\n  const guardSetsFlag = !!guardBody && /resumeInstantRef\\.current = true/.test(guardBody)\n\n  // 缩进对齐真实结构：wasPauseRef 分支在 rAF 循环体内（8 空格），消费块再内嵌一层（10 空格）\n  const resumeBody = blockBody(src, RESUME_RE, 8)\n  const consumeBody = resumeBody ? blockBody(resumeBody, CONSUME_RE, 10) : null\n  const consumeCallsForce = !!consumeBody &&\n    /handleScrollToActiveRef\\.current\\(lineRef\\.current\\.line, true\\)/.test(consumeBody)\n  const consumeClearsFlag = !!consumeBody && /resumeInstantRef\\.current = false/.test(consumeBody)\n\n  // 恢复首帧原本的「重取平滑基准」不能丢：瞬时定位之外，暂停前旧基准也不该被沿用\n  const resumeKeepsBaseline = !!resumeBody && /smoothOffsetRef\\.current = (scrollYRef|scrollInfoRef)/.test(resumeBody)\n\n  console.log(`  声明=${decl ? '✅' : '❌'}  置真=${setTrueCount}处  消费=${setFalseCount}处  总引用=${totalUses}`)\n  console.log(`  停帧守卫置真=${guardSetsFlag ? '✅' : '❌'}  恢复首帧 force 定位=${consumeCallsForce ? '✅' : '❌'}  重取基准保留=${resumeKeepsBaseline ? '✅' : '❌'}`)\n\n  // -- 反例自检：删掉消费块 / 把 force 改成 false / 在守卫外多置一次真 --\n  const negNoConsume = src.replace(CONSUME_RE, 'if (false) {')\n  const negNoConsumeStillFound = CONSUME_RE.test(negNoConsume)\n  const negNoForce = src.replace(\n    /handleScrollToActiveRef\\.current\\(lineRef\\.current\\.line, true\\)/,\n    'handleScrollToActiveRef.current(lineRef.current.line, false)',\n  )\n  const negNoForceBody = (() => {\n    const r = blockBody(negNoForce, RESUME_RE, 8)\n    return r ? blockBody(r, CONSUME_RE, 10) : null\n  })()\n  const negNoForceStillForce = !!negNoForceBody &&\n    /handleScrollToActiveRef\\.current\\(lineRef\\.current\\.line, true\\)/.test(negNoForceBody)\n  // 在守卫之外（文件末尾）多置一次真 → 「只允许一处置真」的计数断言必须判不合格\n  const negExtraArm = src + '\\nconst _negOutsideGuard = () => { resumeInstantRef.current = true }\\n'\n  const negExtraArmCount = (negExtraArm.match(/resumeInstantRef\\.current = true/g) || []).length\n\n  check(`[${name}] resumeInstantRef 声明在位`, decl, 'useRef(false)')\n  check(`[${name}] 只在停帧守卫里置真（手动滚动路径不受影响）`, guardSetsFlag && setTrueCount === 1,\n    `守卫内=${guardSetsFlag} 全文件置真 ${setTrueCount} 处（应=1）`)\n  check(`[${name}] 恢复首帧消费标记并走 force 瞬时定位`, !!consumeBody && consumeCallsForce && consumeClearsFlag,\n    'handleScrollToActiveRef.current(lineRef.current.line, true)')\n  check(`[${name}] 恢复首帧仍重取平滑基准（不沿用暂停前旧基准）`, resumeKeepsBaseline, 'smoothOffsetRef = 列表真实位置')\n  check(`[${name}] 反例：删掉消费块必须判不合格`, !negNoConsumeStillFound, '消费块正则不再命中')\n  check(`[${name}] 反例：force 改成 false 必须判不合格`, !negNoForceStillForce, '退化成 animated:true 动画滚动被检出')\n  check(`[${name}] 反例：守卫外多置一次真必须判不合格`, negExtraArmCount === 2, `计数=${negExtraArmCount} 应=2`)\n}\n\nconsole.log()\nconsole.log('='.repeat(92))\nfor (const r of results) {\n  console.log(`  ${r.ok ? '✅' : '❌'}  ${r.label}${r.detail ? '   [' + r.detail + ']' : ''}`)\n}\nconsole.log()\nconsole.log(`结果：${results.length - failed}/${results.length} 通过${failed ? `（${failed} 项失败）` : ''}`)\nprocess.exit(failed ? 1 : 0)\n" },
  { n: "sim-lyric-scroll-single-writer.js", s: "/**\n * ⑥ 「滚动唯一写者」契约（第六轮需求 6 的钉子）。\n *\n * 需求原话：歌词逐字加载动画要加强，防止歌词上下抖动、回跳、停在错误的位置。\n *\n * 第六轮的收敛结果（`src/screens/PlayDetail/Vertical/Lyric.tsx`）：\n *   播放中，歌词列表的偏移**只能由每帧连续滚动循环（scrollToActiveContinuous）写**。\n *   其余两条非强制定位（行高测量回正 scheduleRecentre、停手 1.5s 回位）不再自己发\n *   滚动，改为把「滑到 targetOffset」排进 pendingGlideRef，由循环按同一条 easeInOut\n *   轨迹落地。此前两路写者互抢同一个偏移 = 抖动 / 回跳 / 停在错误位置。\n *\n * 本脚本从源码解析实际结构（不硬编码行号），断言这套不变式还在：\n *   A. 两个 ref 声明在位，且带「单写者」不变式注释（防被后来的改动静默删掉）；\n *   B. 非强制分支在循环运行时**只排队、不滚**（块内不得出现任何 scrollToOffset），\n *      且这个守卫出现在该函数唯一写点之前；\n *   C. 硬跳（force：seek / 切歌 / 点歌词）清空排队；\n *   D. 循环消费排队请求；\n *   E. 循环存活标记：起 rAF 前置 true、cleanup 里复位（守卫的判据就是它）；\n *   F. 停手回位只有一条入口 armIdleReturn()，松手与惯性结束都走它，\n *      且 onMomentumScrollEnd 真的挂到了 FlatList 上；\n *   G. 换歌（lyricLines 变化）清空排队（旧歌词表算出的落点在新歌里没有意义）；\n *   H. 总账：全文件所有 scrollToOffset 写点都在白名单内，没有多出第三方写者；\n *   I. 反例自检：删掉排队分支 / 把惯性结束接成空实现 / 在非强制分支塞回一个写点，\n *      必须被判不合格。\n *\n * 运行：node scripts/sim-lyric-scroll-single-writer.js\n */\n\nconst fs = require('fs')\nconst path = require('path')\n\nconst ROOT = path.resolve(__dirname, '..')\nconst read = (p) => fs.readFileSync(path.join(ROOT, p), 'utf8')\n\nconst results = []\nlet failed = 0\nconst check = (label, ok, detail) => {\n  results.push({ label, ok: !!ok, detail })\n  if (!ok) failed++\n}\n\nconst FILE = 'src/screens/PlayDetail/Vertical/Lyric.tsx'\nconst src = read(FILE)\n\n/** 取一段块体：从 headerRe 命中处起，到第一个「缩进 = indent 个空格的 }」为止。\n *  indent 传块体的**闭合缩进**（嵌套 if 用 4，顶层 const 箭头函数用 2）。 */\nconst blockBody = (s, headerRe, indent = 4) => {\n  const m = headerRe.exec(s)\n  if (!m) return null\n  const rest = s.slice(m.index + m[0].length)\n  const end = new RegExp(`\\\\n {${indent}}\\\\}`).exec(rest)\n  return end ? rest.slice(0, end.index) : null\n}\n\n// --- A. 声明 ---\nconst loopFlagDecl = /const isScrollLoopRunningRef = useRef\\(false\\)/.test(src)\nconst pendingDecl = /const pendingGlideRef = useRef<\\{ index: number, target: number \\} \\| null>\\(null\\)/.test(src)\nconst invariantComment = /偏移\\*\\*只能由它写\\*\\*|单写者/.test(src)\n\n// --- B. 非强制分支只排队不滚 ---\nconst enqueueBody = blockBody(src, /if \\(!force && isScrollLoopRunningRef\\.current\\) \\{/)\nconst enqueueQueues = !!enqueueBody && /pendingGlideRef\\.current = \\{ index, target: targetOffset \\}/.test(enqueueBody)\nconst enqueueReturns = !!enqueueBody && /\\breturn\\b/.test(enqueueBody)\nconst enqueueWrites = !!enqueueBody && /scrollToOffset|scrollToIndex/.test(enqueueBody)\n\n// 该函数唯一的写点：必须在排队守卫之后（守卫在前 = 先分流再写）\nconst firstWriteInHandler = /const handleScrollToActive = useCallback\\([\\s\\S]*?flatListRef\\.current\\.scrollToOffset/.exec(src)\nconst guardBeforeWrite = !!(firstWriteInHandler && enqueueBody && firstWriteInHandler[0].includes(enqueueBody))\n\n// --- C. 硬跳清队列 ---\nconst forceBody = blockBody(src, /if \\(force\\) \\{/)\nconst forceClears = !!forceBody && /pendingGlideRef\\.current = null/.test(forceBody)\n\n// --- D. 循环消费 ---\nconst consumeBody = blockBody(src, /if \\(pendingGlide\\) \\{/)\nconst consumeTakes = !!consumeBody && /pendingGlideRef\\.current = null/.test(consumeBody) &&\n  /continuousOffset = pendingGlide\\.target/.test(consumeBody)\nconst consumeReads = /const pendingGlide = pendingGlideRef\\.current/.test(src)\n\n// --- E. 循环存活标记 ---\n// 置位必须在起 rAF 之前（守卫的判据 = 真的起了 rAF），复位在 cleanup 里。\nconst setTrueAt = src.indexOf('isScrollLoopRunningRef.current = true')\nconst loopDefAt = src.indexOf('const loop = (ts: number) => {')\nconst rafAt = src.indexOf('rafId = requestAnimationFrame(loop)')\nconst setTrueBeforeRaf = setTrueAt > -1 && loopDefAt > setTrueAt && rafAt > loopDefAt\nconst resetInCleanup = /return \\(\\) => \\{\\n\\s+isScrollLoopRunningRef\\.current = false\\n\\s+cancelAnimationFrame\\(rafId\\)/.test(src)\n\n// --- F. 停手回位单一入口 ---\nconst armDef = /const armIdleReturn = \\(\\) => \\{/.test(src)\nconst armCallsHandler = /const armIdleReturn = \\(\\) => \\{[\\s\\S]*?handleScrollToActive\\(\\)[\\s\\S]*?\\n {2}\\}/.test(src)\nconst endDragBody = blockBody(src, /const onScrollEndDrag = \\(\\) => \\{/, 2)\nconst momentumBody = blockBody(src, /const onMomentumScrollEnd = \\(\\) => \\{/, 2)\nconst endDragArms = !!endDragBody && /armIdleReturn\\(\\)/.test(endDragBody)\nconst momentumArms = !!momentumBody && /armIdleReturn\\(\\)/.test(momentumBody)\nconst momentumWired = /onMomentumScrollEnd=\\{onMomentumScrollEnd\\}/.test(src)\n\n// --- G. 换歌清队列 ---\n// 文件里有不止一个 [lyricLines] effect（歌词内容变化重置 remount key 的那个不含排队清理），\n// 逐个检查，只要有一个带 `pendingGlideRef.current = null` 即可。\nconst lyricResetEffects = [...src.matchAll(/useEffect\\(\\(\\) => \\{([\\s\\S]*?)\\n {2}\\}, \\[lyricLines\\]\\)/g)]\n  .map((m) => m[1])\nconst songChangeClears = lyricResetEffects.some((body) => /pendingGlideRef\\.current = null/.test(body))\n\n// --- H. 总账：所有写点 ---\nconst writeSites = [...src.matchAll(/flatListRef\\.current\\.scrollToOffset\\(\\{ offset: ([^,}]+), animated: ([^}]+) \\}\\)/g)]\n  .map((m) => ({ at: src.slice(0, m.index).split('\\n').length, offset: m[1].trim(), animated: m[2].trim() }))\nconst ALLOWED = [\n  { offset: 'targetOffset', animated: '!force' },              // handleScrollToActive 的唯一点\n  { offset: 'smoothOffsetRef.current', animated: 'false' },    // 连续滚动循环\n  { offset: '0', animated: 'false' },                          // 换歌重置（此时列表已 remount）\n]\nconst unexpected = writeSites.filter((w) =>\n  !ALLOWED.some((a) => a.offset === w.offset && a.animated === w.animated))\n\n// --- I. 反例自检 ---\n// 1) 把排队分支整个删掉：B 组断言必须判不合格\nconst negNoQueue = src.replace(/if \\(!force && isScrollLoopRunningRef\\.current\\) \\{[\\s\\S]*?\\n {4}\\}/, '')\nconst negNoQueueOk = /if \\(!force && isScrollLoopRunningRef\\.current\\) \\{/.test(negNoQueue)\n// 2) 惯性结束接成空实现：F 组断言必须判不合格\nconst negMomentum = src.replace(\n  /const onMomentumScrollEnd = \\(\\) => \\{[\\s\\S]*?\\n {2}\\}/,\n  'const onMomentumScrollEnd = () => {}',\n)\nconst negMomentumBody = blockBody(negMomentum, /const onMomentumScrollEnd = \\(\\) => \\{/, 2)\nconst negMomentumOk = !!negMomentumBody && /armIdleReturn\\(\\)/.test(negMomentumBody)\n// 3) 往非强制分支塞回一个原生动画滚动：B 组断言必须判不合格\nconst negSecondWriter = src.replace(\n  /if \\(!force && isScrollLoopRunningRef\\.current\\) \\{/,\n  'if (!force && isScrollLoopRunningRef.current) {\\n      flatListRef.current.scrollToOffset({ offset: targetOffset, animated: true })',\n)\nconst negSecondWriterBody = blockBody(negSecondWriter, /if \\(!force && isScrollLoopRunningRef\\.current\\) \\{/)\nconst negSecondWriterOk = !(!!negSecondWriterBody && /scrollToOffset|scrollToIndex/.test(negSecondWriterBody))\n\nconsole.log('='.repeat(92))\nconsole.log('「歌词滚动唯一写者」契约模型（摘自源码）')\nconsole.log('='.repeat(92))\nconsole.log(`  声明：isScrollLoopRunningRef=${loopFlagDecl ? '✅' : '❌'}  pendingGlideRef=${pendingDecl ? '✅' : '❌'}  不变式注释=${invariantComment ? '✅' : '❌'}`)\nconsole.log(`  非强制分支：排队=${enqueueQueues ? '✅' : '❌'} return=${enqueueReturns ? '✅' : '❌'} 块内无写点=${enqueueWrites ? '❌ 有写点' : '✅'}`)\nconsole.log(`  守卫先于唯一写点：${guardBeforeWrite ? '✅' : '❌'}`)\nconsole.log(`  硬跳清队列：${forceClears ? '✅' : '❌'}   循环消费：${consumeReads && consumeTakes ? '✅' : '❌'}`)\nconsole.log(`  存活标记：起 rAF 前置位=${setTrueBeforeRaf ? '✅' : '❌'}  cleanup 复位=${resetInCleanup ? '✅' : '❌'}`)\nconsole.log(`  停手回位：armIdleReturn=${armDef && armCallsHandler ? '✅' : '❌'}  松手=${endDragArms ? '✅' : '❌'}  惯性结束=${momentumArms ? '✅' : '❌'}  挂载=${momentumWired ? '✅' : '❌'}`)\nconsole.log(`  换歌清队列：[lyricLines] effect 内=${songChangeClears ? '✅' : '❌'}`)\nconsole.log()\nconsole.log(`  全文件 scrollToOffset 写点（${writeSites.length} 处）：`)\nfor (const w of writeSites) console.log(`    L${w.at}  offset: ${w.offset}  animated: ${w.animated}`)\nconsole.log(`  白名单之外的写点：${unexpected.length ? unexpected.map((w) => `L${w.at}`).join(', ') : '无'}`)\nconsole.log()\n\nconsole.log('='.repeat(92))\nconsole.log('断言')\nconsole.log('='.repeat(92))\n\ncheck('isScrollLoopRunningRef 声明在位（唯一写者的判据）', loopFlagDecl, 'useRef(false)')\ncheck('pendingGlideRef 声明在位（排队请求）', pendingDecl, 'useRef<{ index, target } | null>(null)')\ncheck('文件内保留「单写者 / 只能由它写」的不变式注释', invariantComment, '防后来者静默删守卫')\n\ncheck('非强制 + 循环运行中：把定位排进 pendingGlideRef', enqueueQueues && enqueueReturns,\n  enqueueQueues ? '排队并 return' : '排队分支缺失')\ncheck('非强制分支块内不得出现任何滚动写点（只排队、不自己滚）', !enqueueWrites,\n  enqueueWrites ? '块内有 scrollToOffset/scrollToIndex' : '无写点')\ncheck('排队守卫出现在 handleScrollToActive 唯一写点之前', guardBeforeWrite, '先分流、后写')\n\ncheck('硬跳（force）清空排队请求', forceClears, 'pendingGlideRef.current = null')\ncheck('连续滚动循环读取并消费排队请求', consumeReads && consumeTakes,\n  'pendingGlide → continuousOffset = pendingGlide.target')\n\ncheck('循环起 rAF 前置 isScrollLoopRunningRef = true', setTrueBeforeRaf, 'cleanup 前')\ncheck('循环 cleanup 复位 isScrollLoopRunningRef = false', resetInCleanup, '与 cancelAnimationFrame 同段')\n\ncheck('armIdleReturn 提取为共用入口并调用 handleScrollToActive', armDef && armCallsHandler, '松手 / 惯性结束共用')\ncheck('onScrollEndDrag 走 armIdleReturn', endDragArms, '抬手重新计时')\ncheck('onMomentumScrollEnd 走 armIdleReturn（惯性结束才真正停手）', momentumArms, '抖动/回跳的直接修复点')\ncheck('onMomentumScrollEnd 已挂到 FlatList', momentumWired, 'onMomentumScrollEnd={onMomentumScrollEnd}')\ncheck('换歌（[lyricLines] effect）清空排队请求', songChangeClears, 'pendingGlideRef.current = null')\ncheck(`全文件滚动写点总账：${writeSites.length} 处全部在白名单内`, unexpected.length === 0,\n  unexpected.length ? unexpected.map((w) => `L${w.at}`).join(', ') : 'handleScrollToActive / 循环 / 换歌重置')\n\ncheck('反例：删掉排队分支，必须判不合格', !negNoQueueOk, '守卫正则不再命中')\ncheck('反例：把 onMomentumScrollEnd 接成空实现，必须判不合格', !negMomentumOk, 'armIdleReturn 不再被调用')\ncheck('反例：非强制分支塞回原生动画滚动，必须判不合格', !negSecondWriterOk, '块内写点被检出')\n\nconsole.log()\nfor (const r of results) {\n  console.log(`  ${r.ok ? '✅' : '❌'}  ${r.label}${r.detail ? '   [' + r.detail + ']' : ''}`)\n}\nconsole.log()\nconsole.log(`结果：${results.length - failed}/${results.length} 通过${failed ? `（${failed} 项失败）` : ''}`)\nprocess.exit(failed ? 1 : 0)\n" },
  { n: "sim-mini-lyric-return-timing.js", s: "#!/usr/bin/env node\n/**\n * sim-mini-lyric-return-timing.js —— 小歌词「换行过程被瞬跳复位打快」的防复发契约\n * （用户第 22 轮第 3 条 + 中途补充）。\n *\n * 需求原话（2026-10-03）：\n *   「播放详情页的小歌词，滑动歌词后返回播放进度时，这个动画和大歌词动画的速度不一致，\n *     我发现，歌曲播放时，加载歌词比较快的情况下，一滑动歌词，它会马上跳回原位置，特别快，\n *     速度和正常速度完全不一样，有时候一滑出去，就回来了，请规范整体返回时间，特别是正在播放时。」\n * 中途补充原话：\n *   「小歌词问题，主要发生在歌词换行过程中，会出现上面速度快的 bug」\n *\n * 根因（两条瞬时复位入口，都在歌词换行时被触发）：\n *   ① 复位 effect 依赖写着 [lyricLines, resetScroll]，而 resetScroll 的依赖链是\n *      rowHeights → rowOffsets → getScrollOffset → resetScroll —— rowHeights 依赖\n *      activeLine，**每次换行都换引用**，于是「整份歌词变了才复位」变成「每次换行都复位」：\n *      瞬跳（animated:false）会把刚起步的换行滑行（followActiveLine / LINE_CHANGE_GLIDE_MS）\n *      当场取消，观感就是「快到不正常」。\n *   ② onContentSizeChange 直接挂 resetScroll：当前行带/摘翻译槽时内容总高每次换行都变，\n *      于是同一次换行又白跑一次瞬跳复位。\n *\n * 收敛结果：\n *   一、复位 effect 走 ref、依赖只写 [lyricLines]（useLrcSet 只在整份歌词变更时换引用）；\n *   二、onContentSizeChange 换成「窗口高度真变了才同步」的 handleContentSizeChange，\n *      换行引起的行高变化交给跟随滑行；\n *   三、resetScroll / handleContentSizeChange 都保持「手动定位期间绝不抢滚动」的纪律；\n *   四、时长口径不动：换行跟随 LINE_CHANGE_GLIDE_MS、回位 duration ?? RETURN_TO_ACTIVE_MS\n *      （与大歌词同源，见 sim-lyric-manual-position.js）。\n *\n * 带反例自检（这类回归 tsc/eslint 无感：hooks 依赖数组多写一个变量完全合法）。\n * 运行：node scripts/sim-mini-lyric-return-timing.js\n * 退出码：不变量全过、且全部反例被拦下时为 0，否则 1。\n */\n'use strict'\n\nconst fs = require('fs')\nconst path = require('path')\n\nconst ROOT = path.join(__dirname, '..')\nconst FILE = 'src/screens/PlayDetail/components/MiniLyric.tsx'\nconst read = (p) => fs.readFileSync(path.join(ROOT, p), 'utf8').replace(/\\r\\n/g, '\\n')\nconst stripComments = (src) => src.replace(/\\/\\*[\\s\\S]*?\\*\\//g, '').replace(/\\/\\/[^\\n]*/g, '')\n\nconst invariants = (rawFile) => {\n  const reasons = []\n  const code = stripComments(rawFile)\n\n  // ① 复位只在「整份歌词换了引用」时跑：ref 转发 + 依赖只写 [lyricLines]\n  if (!/const resetScrollRef = useRef\\(resetScroll\\)\\s*\\n\\s*resetScrollRef\\.current = resetScroll\\s*\\n\\s*useEffect\\(\\(\\) => \\{\\s*\\n\\s*resetScrollRef\\.current\\(\\)\\s*\\n\\s*\\}, \\[lyricLines\\]\\)/.test(code)) {\n    reasons.push('复位 effect 未走「ref 转发 + 仅依赖 [lyricLines]」（rowHeights 每次换行换引用 → resetScroll 换引用 → 每次换行都瞬跳复位）')\n  }\n  if (/\\[lyricLines, resetScroll\\]/.test(code)) {\n    reasons.push('复位 effect 依赖又写回了 resetScroll（每次歌词换行都会重建引用、触发瞬跳复位，用户报的「换行过程中特别快」）')\n  }\n\n  // ② resetScroll 第一道纪律：手动定位期间直接跳过（绝不抢滚动）\n  if (!/const resetScroll = useCallback\\(\\(\\) => \\{\\s*\\n\\s*if \\(isPauseScrollRef\\.current\\) return/.test(code)) {\n    reasons.push('resetScroll 缺少「手动定位期间直接跳过」守卫（用户滑动中的位置会被复位抢走）')\n  }\n\n  // ③ onContentSizeChange 不再直挂 resetScroll，走「窗口高度真变了才同步」的处理器\n  if (code.includes('onContentSizeChange={resetScroll}')) {\n    reasons.push('onContentSizeChange 又直挂 resetScroll（换行时当前行翻译槽增减会改内容总高 → 每次换行白跑一次瞬跳复位）')\n  }\n  if (!code.includes('onContentSizeChange={handleContentSizeChange}')) {\n    reasons.push('onContentSizeChange 未挂 handleContentSizeChange')\n  }\n  if (!/const sizeHandledHeightRef = useRef\\(containerHeight\\)\\s*\\n\\s*const handleContentSizeChange = useCallback\\(\\(\\) => \\{\\s*\\n\\s*if \\(sizeHandledHeightRef\\.current === containerHeight\\) return/.test(code)) {\n    reasons.push('handleContentSizeChange 未按「窗口高度（containerHeight）真变了才处理」去重（普通内容高变化不该触发同步）')\n  }\n  const hcBody = /const handleContentSizeChange = useCallback\\(\\(\\) => \\{([\\s\\S]*?)\\}, \\[containerHeight, getScrollOffset, cancelScroll\\]\\)/.exec(code)\n  if (!hcBody) {\n    reasons.push('handleContentSizeChange 处理体抽取失败（锚点漂移）')\n  } else {\n    for (const [needle, label] of [\n      ['sizeHandledHeightRef.current = containerHeight', '更新已处理窗口高度'],\n      ['if (isPauseScrollRef.current) return', '手动定位期间不抢滚动'],\n      ['cancelScroll()', '取消进行中的定位动画'],\n      ['listRef.current?.scrollToOffset({ offset: getScrollOffset(activeLineRef.current), animated: false })', '同步到当前行'],\n    ]) {\n      if (!hcBody[1].includes(needle)) reasons.push(`handleContentSizeChange 语义被改动（缺 ${label}）`)\n    }\n  }\n\n  // ④ 时长口径不动：换行跟随 = LINE_CHANGE_GLIDE_MS，回位 = duration ?? RETURN_TO_ACTIVE_MS\n  if (!code.includes(\"import { IDLE_RETURN_MS, LINE_CHANGE_GLIDE_MS, RETURN_TO_ACTIVE_MS } from '@/screens/PlayDetail/lyricAnimation'\")) {\n    reasons.push('三个动画时长常量未从 lyricAnimation 单一来源引入（时长口径漂移）')\n  }\n  if (!/const total = Math\\.max\\(duration \\?\\? RETURN_TO_ACTIVE_MS, 1\\)/.test(code)) {\n    reasons.push('回位时长未走 duration ?? RETURN_TO_ACTIVE_MS（手动定位后的回位时长漂移）')\n  }\n  if (!/animateToLine\\(index, LINE_CHANGE_GLIDE_MS\\)/.test(code)) {\n    reasons.push('换行跟随未用 LINE_CHANGE_GLIDE_MS（换行滑行时长漂移）')\n  }\n  if (!/animateToLine\\(target, undefined,/.test(code)) {\n    reasons.push('停手回位未用「不传 duration 的回位口径」（应走 duration ?? RETURN_TO_ACTIVE_MS）')\n  }\n\n  // ⑤ 换行跟随 effect 仍在（activeLine 变化 → followActiveLine），且手动定位期间不插队\n  if (!/useEffect\\(\\(\\) => \\{\\s*\\n\\s*if \\(activeLine < 0\\) return\\s*\\n[\\s\\S]{0,120}?if \\(isPauseScrollRef\\.current\\) return\\s*\\n\\s*followActiveLine\\(activeLine\\)\\s*\\n\\s*\\}, \\[activeLine, followActiveLine\\]\\)/.test(code)) {\n    reasons.push('换行跟随 effect 被改动（activeLine 变化 → followActiveLine 的链路缺失或守卫丢失）')\n  }\n\n  return reasons\n}\n\n// ---------------------------------------------------------------------------\n// 反例（对篡改后的源码跑同一套判断，必须被拦下）\n// ---------------------------------------------------------------------------\n\nconst tamper = (src, find, replace) => {\n  if (!src.includes(find)) throw new Error(`tamper 锚点未命中: ${find.slice(0, 60)}`)\n  return src.replace(find, replace)\n}\n\nconst REAL = read(FILE)\n\nconst runCounterExamples = () => {\n  const results = []\n  const check = (name, fn, expectReasonSubstr) => {\n    let reasons = []\n    try {\n      reasons = fn()\n    } catch (e) {\n      results.push({ name, ok: false, detail: `抛异常: ${e.message}` })\n      return\n    }\n    const hit = reasons.some(r => r.includes(expectReasonSubstr))\n    results.push({ name, ok: hit, detail: hit ? '已拦下' : `未拦下（reasons=${JSON.stringify(reasons)}）` })\n  }\n\n  // c1 复位 effect 退回 [lyricLines, resetScroll]（换行即瞬跳的老写法）\n  check('c1 复位依赖退回 resetScroll', () => invariants(tamper(REAL,\n    '    resetScrollRef.current()\\n  }, [lyricLines])',\n    '    resetScroll()\\n  }, [lyricLines, resetScroll])')),\n  '复位 effect 未走「ref 转发 + 仅依赖 [lyricLines]」')\n\n  // c2 onContentSizeChange 退回直挂 resetScroll\n  check('c2 内容高变化退回瞬跳复位', () => invariants(tamper(REAL,\n    'onContentSizeChange={handleContentSizeChange}',\n    'onContentSizeChange={resetScroll}')),\n  'onContentSizeChange 又直挂 resetScroll')\n\n  // c3 拆掉 resetScroll 的手动定位守卫\n  check('c3 拆掉 resetScroll 定位守卫', () => invariants(tamper(REAL,\n    '  const resetScroll = useCallback(() => {\\n    if (isPauseScrollRef.current) return\\n',\n    '  const resetScroll = useCallback(() => {\\n')),\n  'resetScroll 缺少「手动定位期间直接跳过」守卫')\n\n  // c4 拆掉内容高去重（普通换行又触发瞬跳同步）\n  check('c4 拆掉内容高去重', () => invariants(tamper(REAL,\n    '    if (sizeHandledHeightRef.current === containerHeight) return\\n',\n    '')),\n  'handleContentSizeChange 未按「窗口高度（containerHeight）真变了才处理」去重')\n\n  // c5 换行跟随时长漂移\n  check('c5 换行跟随时长漂移', () => invariants(tamper(REAL,\n    'animateToLine(index, LINE_CHANGE_GLIDE_MS)',\n    'animateToLine(index, 120)')),\n  '换行跟随未用 LINE_CHANGE_GLIDE_MS')\n\n  return results\n}\n\n// ---------------------------------------------------------------------------\n// 主流程\n// ---------------------------------------------------------------------------\n\nconsole.log('=== sim-mini-lyric-return-timing ===')\nconsole.log('小歌词换行不被瞬跳复位打快（第 22 轮第 3 条 + 中途补充）')\nconsole.log()\n\nconst reasons = invariants(REAL)\nif (reasons.length === 0) {\n  console.log('[不变量] PASS —— 复位只跟整份歌词走；内容高变化按窗口高度去重；时长口径同源')\n} else {\n  console.log('[不变量] FAIL')\n  reasons.forEach(r => console.log('  FAIL ' + r))\n}\n\nconsole.log('\\n[反例自检]')\nconst ceResults = runCounterExamples()\nlet ceAllOk = true\nfor (const r of ceResults) {\n  console.log(`  ${r.ok ? 'PASS' : 'FAIL'} ${r.name} —— ${r.detail}`)\n  if (!r.ok) ceAllOk = false\n}\n\nconst invOk = reasons.length === 0\nconst allOk = invOk && ceAllOk\nconsole.log(`\\n结果：${allOk ? 'ALL PASS' : '有失败项'}（不变量 ${invOk ? 1 : 0}/1；反例 ${ceResults.filter(r => r.ok).length}/${ceResults.length}）`)\nprocess.exit(allOk ? 0 : 1)\n" },
  { n: "sim-local-toggle-source-lyric.js", s: "#!/usr/bin/env node\n/**\n * sim-local-toggle-source-lyric.js —— 「试听列表里的 local/下载条目：换源不再崩、能按歌名换源、\n * 自动获取在线歌词」契约（第 31 轮）。\n *\n * 需求原话（2026-10-03 第 31 轮，随 RN 红屏截图一起报的）：\n *   「又发现bug：1、播放本地与下载歌曲时，在试听列表选择local歌曲，选择歌曲换源后弹出报错，\n *     local歌曲可以按照歌名来换源修复。」\n *   「而且这些local歌曲，没有自动获取歌词，需要修补」\n *\n * 崩溃现场：`Fatal: TypeError Cannot read property 'albumName' of undefined`，栈落在 SourceDetail。\n * 根因（两条叠在一起）：\n *   ① 试听列表（LIST_IDS.DEFAULT）里混着**不是标准 MusicInfo** 的条目 ——\n *      LocalDownload 的 taskToPlayItem 是 `{ id, isComplate, status, progress, metadata: {...} }`，\n *      没有 name/singer/meta：播放「本地与下载」里的下载歌曲后，选中换源时 SourceDetail 读\n *      `info.meta.albumName` 直接抛；localFileToPlayItem 有 meta，但 name/singer 由文件名派生\n *      （parseFileName 把「歌手 - 歌名」拆成 name=左、singer=右，常常是反的），按原样搜什么都搜不到。\n *   ② 同一类未加可选链的解引用还在多处（试听列表搜索行、重复歌曲弹窗、我的列表按专辑排序）。\n * 歌词那头：普通本地/下载条目的歌词走 core/music/localPlay.getLyricInfo，而它的在线匹配只有\n * 一轮 `searchMusic(歌名, 歌手)` —— 文件名把歌名/歌手拆反时这一轮搜不到就返回空歌词，永远不会\n * 像 WebDAV 那样换组合重搜，用户看到的就是「这些 local 歌曲没有自动获取歌词」。\n *\n * 本轮口径：\n *   条一（换源不崩 + 能搜到）\n *     ① listAction 新增 normalizeToggleInfo：从 metadata.musicInfo 抠出真正的歌曲信息，补齐\n *        name/singer/source/meta（albumName 空串兜底、filePath 三处来源归一）。**只用于展示与\n *        搜索**：确认换源仍拿原始条目（handleToggleSource 靠原始 id 在列表里定位旧项）。\n *     ② 渲染处一律 meta?.albumName（SourceDetail 4 处 + 列表行 + 试听列表搜索行 + 重复歌曲弹窗\n *        + 我列表专辑排序）。\n *     ③ 搜索候选 getToggleSearchCandidates：本地/下载条目按 ①原样 → ②歌名歌手对调 →\n *        ③文件名整段/两种拆法 → ④只按歌名搜 逐组试（上限 5 组），上一组一个结果都没有才试下一组；\n *        在线歌曲只有一组候选，行为不变。结果列表过滤 toNewMusicInfo 的 null。\n *     ④ loadData 入参设防：Empty 的「重新加载」把点击事件当 selectInfo 传进来，不能直接读\n *        event.musicInfo。\n *   条二（自动获取歌词）\n *     ⑤ localPlay.getLyricInfo 升级成与 WebDAV 同一条链路：内嵌 → 同名 .lrc →\n *        getCachedLyricInfo（已落库）→ matchOnlineLyric（本地文件走 local.ts 导出的\n *        getOtherSourceByLocal 多轮拆分重试；下载任务/汽水走 getOtherSource 跨平台搜索；\n *        候选交给 getOnlineOtherSourceLyricInfo 做 existTimeExp 时间轴校验，成功后 saveLyric\n *        按条目 id 落库）→ 旧的轻量兜底 → 空歌词。\n *     ⑥ index.ts 把原条目（musicInfo）透传进 target：落库/读缓存按 id，多轮拆分按文件名。\n *\n * 为什么必须靠契约脚本：「内层条目怎么抠、哪些渲染点的可选链、候选分几组什么顺序、确认换源\n * 用哪份对象、歌词链路的先后与落库」全是形状与顺序，不是类型 —— 把 normalizeToggleInfo 换成\n * 直传原始条目、把候选组删成一组、把 .filter(Boolean) 删掉、把 getOtherSourceByLocal 那段删掉、\n * 把 saveLyric 删掉，tsc/eslint 全是绿的，真机上就是「换源红屏 / 搜不到 / 永远没有歌词」。\n * 带反例自检。\n *\n * 运行：node scripts/sim-local-toggle-source-lyric.js\n * 退出码：不变量全过、且全部反例被拦下时为 0，否则 1。\n */\n'use strict'\n\nconst fs = require('fs')\nconst path = require('path')\n\nconst ROOT = path.join(__dirname, '..')\nconst read = (p) => fs.readFileSync(path.join(ROOT, p), 'utf8').replace(/\\r\\n/g, '\\n')\n\n// 只去块注释与整行 `//` 注释（不能按 `/\\/\\/[^\\n]*/g` 朴素切：本文件要看 `'file://'` 这类字符串字面量）\nconst stripComments = (src) => src\n  .replace(/\\/\\*[\\s\\S]*?\\*\\//g, '')\n  .split('\\n')\n  .map((line) => (/^\\s*\\/\\//.test(line) ? '' : line))\n  .join('\\n')\n\nconst F = {\n  listAction: 'src/screens/Home/Views/Mylist/MusicList/listAction.ts',\n  modal: 'src/screens/Home/Views/Mylist/MusicList/MusicToggleModal.tsx',\n  listSearch: 'src/screens/Home/Views/Mylist/MusicList/ListMusicSearch.tsx',\n  dup: 'src/screens/Home/Views/Mylist/MyList/DuplicateMusic.tsx',\n  mylistUtils: 'src/screens/Home/Views/Mylist/MyList/utils.ts',\n  localPlay: 'src/core/music/localPlay.ts',\n  musicIndex: 'src/core/music/index.ts',\n  local: 'src/core/music/local.ts',\n}\n\nconst REAL = {}\nfor (const [key, file] of Object.entries(F)) REAL[key] = read(file)\n\nconst slice = (src, from, to) => {\n  const start = src.indexOf(from)\n  if (start < 0) return null\n  const end = src.indexOf(to, start + from.length)\n  if (end <= start) return null\n  return src.slice(start, end)\n}\n\n// ---------------------------------------------------------------------------\n// 不变量 A（条一）：换源不崩（规整条目 / 可选链 / 原始条目确认）+ 能按歌名换源（候选组）\n// ---------------------------------------------------------------------------\n\nconst toggleCrashInvariants = (files) => {\n  const reasons = []\n  const la = files.listAction\n  const laCode = stripComments(la)\n  const modal = files.modal\n  const modalCode = stripComments(modal)\n\n  // ① 规整函数：下载任务条目要能抠出 metadata.musicInfo，且补齐三个必经字段\n  const helpers = slice(la, 'export const normalizeToggleInfo = (', 'export const handleToggleSource = async(')\n  if (!helpers) {\n    reasons.push('换源辅助函数切片失败（锚点漂移：normalizeToggleInfo / handleToggleSource）')\n    return reasons\n  }\n  if (!helpers.includes('raw.metadata?.musicInfo ?? raw.musicInfo ?? raw')) {\n    reasons.push('normalizeToggleInfo 没有从 metadata.musicInfo 抠出真正的歌曲信息（下载任务条目没有 name/singer/meta，SourceDetail 读 undefined.albumName 必崩）')\n  }\n  if (!helpers.includes(\"albumName: meta.albumName ?? ''\")) {\n    reasons.push('normalizeToggleInfo 没有给 meta.albumName 兜底空串（meta 缺失时 SourceDetail 的渲染分支全靠这层兜底）')\n  }\n  if (!helpers.includes('filePath: meta.filePath ?? raw.filePath ?? raw.metadata?.filePath ?? meta.songId')) {\n    reasons.push('normalizeToggleInfo 没有把三处分散的文件路径（meta.filePath / 条目 filePath / metadata.filePath）归一（换源搜索与歌词拆分都靠它拿到文件名）')\n  }\n\n  // ② 展示用规整条目，确认换源仍用原始条目\n  if (!modalCode.includes('info={normalizeToggleInfo(infoRef.current.musicInfo)}')) {\n    reasons.push('SourceDetail 没有拿到规整后的条目（下载任务条目进 SourceDetail 读 info.meta.albumName 就是那条 Fatal）')\n  }\n  if (!modalCode.includes('handleToggleSource(infoRef.current.listId, infoRef.current.musicInfo, musicInfo)')) {\n    reasons.push('确认换源没有继续用原始条目（handleToggleSource 靠原始 id 在列表里定位旧项，传规整后的内层 id 会找不到）')\n  }\n\n  // ③ 渲染处一律可选链：guard 位置出现 `.meta.albumName ?` / `==` / `.localeCompare` 就是没兜住\n  const renderFiles = {\n    'MusicToggleModal.tsx': modalCode,\n    'ListMusicSearch.tsx': stripComments(files.listSearch),\n    'DuplicateMusic.tsx': stripComments(files.dup),\n    'MyList/utils.ts': stripComments(files.mylistUtils),\n    'MusicList/listAction.ts': laCode,\n  }\n  for (const [key, code] of Object.entries(renderFiles)) {\n    for (const bad of ['.meta.albumName ?', '.meta.albumName ==', '.meta.albumName.localeCompare']) {\n      if (code.includes(bad)) {\n        reasons.push(`${key} 里还有未加可选链的「${bad}」（列表里混着下载任务条目时读 meta 就是 undefined → 红屏 Fatal）`)\n      }\n    }\n  }\n  if (!modalCode.includes('info.meta?.albumName ? (')) {\n    reasons.push('SourceDetail 的专辑名渲染没有改成 info.meta?.albumName（本轮崩溃点之一）')\n  }\n  if (!renderFiles['ListMusicSearch.tsx'].includes(\"item.meta?.albumName ? ` (${item.meta.albumName})` : ''\")) {\n    reasons.push('ListMusicSearch 的搜索结果行没有改成可选链形式（试听列表里搜同一首歌会踩同一个坑）')\n  }\n  if (!renderFiles['DuplicateMusic.tsx'].includes('info.musicInfo.meta?.albumName ? (')) {\n    reasons.push('DuplicateMusic 的专辑名渲染没有改成可选链形式（重复歌曲弹窗里同样会炸）')\n  }\n  if (!renderFiles['MyList/utils.ts'].includes('const aAlbum = a.meta?.albumName') ||\n      !renderFiles['MyList/utils.ts'].includes('const bAlbum = b.meta?.albumName')) {\n    reasons.push('MyList/utils.ts 的专辑排序没有先取可选链局部变量（按专辑排序时对下载任务条目解引用会炸）')\n  }\n\n  // ④ 候选组：本地/下载条目要多组重试，在线歌曲保持单组\n  if (!helpers.includes('export const getToggleSearchCandidates = (')) {\n    reasons.push('listAction 没有导出 getToggleSearchCandidates（换源搜索还是单组，本地歌曲拆反了就搜不到）')\n  }\n  if (!helpers.includes(\"return [{ name, singer }]\")) {\n    reasons.push('getToggleSearchCandidates 对在线歌曲没有保持单组候选（在线行为会跟着变）')\n  }\n  if (!helpers.includes('push(singer, name)')) {\n    reasons.push('候选组没有「歌名/歌手对调」那一组（parseFileName 把「歌手 - 歌名」拆反时就靠它）')\n  }\n  if (!helpers.includes(\"push(name, '')\")) {\n    reasons.push('候选组没有「只按歌名搜」的兜底组（用户明确要求 local 歌曲能按歌名换源）')\n  }\n  if (!helpers.includes('candidates.slice(0, 5)')) {\n    reasons.push('候选组没有上限（本地歌曲会退化成十几轮全平台搜索）')\n  }\n\n  // ⑤ loadData：入参设防 + 逐组回退 + 过滤 null\n  const loadData = slice(modal, '  const loadData = useCallback(', '  useImperativeHandle(ref, () => ({')\n  if (!loadData) {\n    reasons.push('loadData 切片失败（锚点漂移：loadData / useImperativeHandle）')\n  } else {\n    if (!loadData.includes('selectInfo?.musicInfo ? selectInfo : infoRef.current')) {\n      reasons.push('loadData 的入参没有设防（Empty 的「重新加载」把点击事件当 selectInfo 传进来，读 event.musicInfo 直接抛）')\n    }\n    if (!loadData.includes('getToggleSearchCandidates(target.musicInfo)')) {\n      reasons.push('loadData 没有用 getToggleSearchCandidates 组候选（本地歌曲只有一组搜索，拆反了就永远搜不到）')\n    }\n    if (!loadData.includes('if (!candidates.length) {')) {\n      reasons.push('loadData 没有处理候选组为空的情况（歌名歌手都空时会 candidate.name 抛错）')\n    }\n    if (!loadData.includes('return searchNext(index + 1)')) {\n      reasons.push('候选组没有逐组回退（第一组没结果就停在空列表，本次修复等于没做）')\n    }\n    if (!loadData.includes('.filter(Boolean)')) {\n      reasons.push('搜索结果没有过滤 toNewMusicInfo 的 null（缺 .filter(Boolean)，缺 songmid 的条目会在 FlatList 渲染时炸）')\n    }\n  }\n\n  // ⑥ 换源定位旧项仍按原始 id\n  const toggle = slice(la, 'export const handleToggleSource = async(', 'export const handleDownload = async(')\n  if (!toggle || !toggle.includes('const oldId = musicInfo.id')) {\n    reasons.push('handleToggleSource 没有按原始 id 定位旧项（换源替换会找不到原来的条目）')\n  }\n\n  return reasons\n}\n\n// ---------------------------------------------------------------------------\n// 不变量 B（条二）：本地/下载条目自动获取在线歌词（多轮匹配 + 时间轴校验 + 落库 + 缓存）\n// ---------------------------------------------------------------------------\n\nconst localLyricInvariants = (files) => {\n  const reasons = []\n  const lp = files.localPlay\n  const lpCode = stripComments(lp)\n\n  if (!lpCode.includes(\"import { getOtherSourceByLocal } from './local'\")) {\n    reasons.push('localPlay 没有复用 local.ts 的多轮匹配（getOtherSourceByLocal），本地文件名拆反时搜不到就是空歌词')\n  }\n  if (!lpCode.includes('musicInfo?: LX.Music.MusicInfo | LX.Download.ListItem')) {\n    reasons.push('LocalPlayTarget 没有带原始条目（匹配成功后没法按 id 落库，也没法做文件名拆分重搜）')\n  }\n\n  const match = slice(lp, 'const matchOnlineLyric = async(', 'export const getLyricInfo = async({')\n  if (!match) {\n    reasons.push('matchOnlineLyric 切片失败（锚点漂移：matchOnlineLyric / getLyricInfo）')\n  } else {\n    if (!match.includes('getOtherSourceByLocal(originInfo as LX.Music.MusicInfoLocal, tryMatch)')) {\n      reasons.push('本地文件没有走 local.ts 的多轮拆分匹配（getOtherSourceByLocal）——「歌手 - 歌名」拆反时只有这条路能搜到')\n    }\n    if (!match.includes('return tryMatch(await getOtherSource(originInfo))')) {\n      reasons.push('下载任务/汽水条目没有走 getOtherSource 跨平台搜索（这两个条目的歌名歌手本来就是对的，别绕远路）')\n    }\n    if (!match.includes('getOnlineOtherSourceLyricInfo({')) {\n      reasons.push('候选没有交给 getOnlineOtherSourceLyricInfo（没有 existTimeExp 时间轴校验，纯文本歌词会被当成命中）')\n    }\n    if (!match.includes('musicInfos: [...otherSource],')) {\n      reasons.push('候选列表没有拷贝就传进去（getOnlineOtherSourceLyricInfo 会 shift 掉原数组）')\n    }\n    if (!match.includes('onToggleSource: () => {}')) {\n      reasons.push('匹配过程传了真实的换源回调（本地/下载链路不走自定义源换源，回调会把播放器切到别的源）')\n    }\n    if (!match.includes('if (!isFromCache) void saveLyric(')) {\n      reasons.push('匹配成功的歌词没有落库（每次都重搜，下次播放还是慢慢等 / 刷新前一直空）')\n    }\n  }\n\n  const lyric = slice(lp, 'export const getLyricInfo = async({', 'export const getPicUrl = async({')\n  if (!lyric) {\n    reasons.push('localPlay.getLyricInfo 切片失败（锚点漂移：getLyricInfo / getPicUrl）')\n  } else {\n    const ordered = [\n      ['readLyric(', '内嵌歌词'],\n      ['readSidecarLyric(', '同名 .lrc'],\n      ['getCachedLyricInfo(', '已落库歌词缓存'],\n      ['matchOnlineLyric(', '跨平台在线匹配'],\n      ['searchCandidates(', '轻量兜底搜索'],\n      [\"buildLyricInfo({ lyric: '' })\", '空歌词兜底'],\n    ]\n    let lastAt = -1\n    let broken = false\n    for (const [needle, label] of ordered) {\n      const at = lyric.indexOf(needle)\n      if (at < 0 || at < lastAt) {\n        broken = true\n        reasons.push(`localPlay.getLyricInfo 的取歌词顺序不对：${label}（${needle}）缺失或排错位（离线优先、在线匹配次之、空歌词最后）`)\n        break\n      }\n      lastAt = at\n    }\n    if (!broken && !lyric.includes('const originInfo = target.musicInfo')) {\n      reasons.push('localPlay.getLyricInfo 没有从 target 取原始条目（多轮匹配与落库都拿不到入口）')\n    }\n  }\n\n  if (!stripComments(files.local).includes('export const getOtherSourceByLocal = async <T>(')) {\n    reasons.push('local.ts 没有导出 getOtherSourceByLocal（localPlay 复用不了，只能各写一份多轮匹配）')\n  }\n\n  const idx = files.musicIndex\n  const target = slice(idx, 'const getTaskTarget = (', 'export const getMusicUrl = async({')\n  if (!target || !target.includes('\\n    musicInfo,\\n')) {\n    reasons.push('getTaskTarget 没有把下载任务原条目带进 target（下载歌曲的歌词匹配与落库都拿不到 id/文件名）')\n  }\n  if (!idx.includes('// 本地文件条目：在线歌词匹配多轮重试 + 按 id 落库都要用它\\n        musicInfo,')) {\n    reasons.push('index.ts 的本地歌词分支没有带 musicInfo（普通本地歌曲仍走单轮搜索）')\n  }\n  if (!idx.includes('        picUrl: null,\\n        musicInfo,')) {\n    reasons.push('index.ts 的汽水歌词分支没有带 musicInfo')\n  }\n\n  return reasons\n}\n\n// ---------------------------------------------------------------------------\n// 反例自检\n// ---------------------------------------------------------------------------\n\nconst tamper = (src, from, to) => {\n  if (!src.includes(from)) throw new Error('反例锚点未命中: ' + from.slice(0, 70))\n  return src.replace(from, to)\n}\n\n// 同一段写法在文件里出现多次时（例如 normalizeToggleInfo 的三个规整函数），\n// 只改第一处不足以破坏不变量 —— 反例要把全部出现一起改回旧实现\nconst tamperAll = (src, from, to) => {\n  if (!src.includes(from)) throw new Error('反例锚点未命中: ' + from.slice(0, 70))\n  return src.split(from).join(to)\n}\n\nconst runCounterExamples = () => {\n  const results = []\n  const check = (name, reasons, expectKeyword) => {\n    const hit = reasons.some((r) => r.includes(expectKeyword))\n    results.push({\n      name,\n      ok: hit,\n      detail: hit ? '已拦下' : '未拦下（缺失期望理由：' + expectKeyword + '）',\n    })\n  }\n\n  // c1 SourceDetail 直传原始条目（第 31 轮之前的写法）\n  check('c1 SourceDetail 直传原始条目', toggleCrashInvariants({\n    ...REAL,\n    modal: tamper(REAL.modal, 'info={normalizeToggleInfo(infoRef.current.musicInfo)}', 'info={infoRef.current.musicInfo}'),\n  }),\n  'SourceDetail')\n\n  // c2 规整函数不抠 metadata.musicInfo（同一写法在 listAction 里出现三处，反例必须一起改）\n  check('c2 不抠 metadata.musicInfo', toggleCrashInvariants({\n    ...REAL,\n    listAction: tamperAll(REAL.listAction, 'const inner = (raw.metadata?.musicInfo ?? raw.musicInfo ?? raw) as any', 'const inner = raw as any'),\n  }),\n  'metadata.musicInfo')\n\n  // c3 albumName 不兜底\n  check('c3 albumName 不兜底', toggleCrashInvariants({\n    ...REAL,\n    listAction: tamper(REAL.listAction, \"albumName: meta.albumName ?? '',\", 'albumName: meta.albumName as any,'),\n  }),\n  '兜底空串')\n\n  // c4 filePath 不归一\n  check('c4 filePath 不归一', toggleCrashInvariants({\n    ...REAL,\n    listAction: tamper(REAL.listAction,\n      'filePath: meta.filePath ?? raw.filePath ?? raw.metadata?.filePath ?? meta.songId,',\n      'filePath: meta.filePath,'),\n  }),\n  '三处分散的文件路径')\n\n  // c5 单轮搜索（候选组没了）\n  check('c5 退回单轮搜索', toggleCrashInvariants({\n    ...REAL,\n    modal: tamper(REAL.modal,\n      'const candidates = getToggleSearchCandidates(target.musicInfo)',\n      'const candidates = [{ name: target.musicInfo.name, singer: target.musicInfo.singer }]'),\n  }),\n  'getToggleSearchCandidates')\n\n  // c6 候选组不逐组回退\n  check('c6 不逐组回退', toggleCrashInvariants({\n    ...REAL,\n    modal: tamper(REAL.modal,\n      '        if (!tags.length && index + 1 < candidates.length) return searchNext(index + 1)',\n      '        if (false) return searchNext(index)'),\n  }),\n  '逐组回退')\n\n  // c7 不过滤 toNewMusicInfo 的 null\n  check('c7 不过滤 null', toggleCrashInvariants({\n    ...REAL,\n    modal: tamper(REAL.modal,\n      'const list = s.list.map(info => toNewMusicInfo(info)).filter(Boolean) as LX.Music.MusicInfoOnline[]',\n      'const list = s.list.map(info => toNewMusicInfo(info)) as LX.Music.MusicInfoOnline[]'),\n  }),\n  'filter(Boolean)')\n\n  // c8 loadData 入参不设防（Empty 重新加载把事件当参数）\n  check('c8 入参不设防', toggleCrashInvariants({\n    ...REAL,\n    modal: tamper(REAL.modal,\n      'const target = selectInfo?.musicInfo ? selectInfo : infoRef.current',\n      'const target = selectInfo as SelectInfo'),\n  }),\n  '重新加载')\n\n  // c9 ListMusicSearch 可选链回退\n  check('c9 ListMusicSearch 可选链回退', toggleCrashInvariants({\n    ...REAL,\n    listSearch: tamper(REAL.listSearch,\n      \"{item.singer}{item.meta?.albumName ? ` (${item.meta.albumName})` : ''}\",\n      '{item.singer} ({item.meta.albumName})'),\n  }),\n  'ListMusicSearch')\n\n  // c10 我列表专辑排序可选链回退（升降序两个分支各有一处，反例必须一起改）\n  check('c10 专辑排序可选链回退', toggleCrashInvariants({\n    ...REAL,\n    mylistUtils: tamperAll(REAL.mylistUtils, 'const aAlbum = a.meta?.albumName', 'const aAlbum = a.meta.albumName as any'),\n  }),\n  '专辑排序')\n\n  // c11 确认换源改用规整条目（原始 id 丢了）\n  check('c11 确认换源用规整条目', toggleCrashInvariants({\n    ...REAL,\n    modal: tamper(REAL.modal,\n      'handleToggleSource(infoRef.current.listId, infoRef.current.musicInfo, musicInfo)',\n      'handleToggleSource(infoRef.current.listId, normalizeToggleInfo(infoRef.current.musicInfo), musicInfo)'),\n  }),\n  '原始条目')\n\n  // c12 本地歌词不走多轮拆分匹配\n  check('c12 本地歌词不走多轮匹配', localLyricInvariants({\n    ...REAL,\n    localPlay: tamper(REAL.localPlay,\n      'return getOtherSourceByLocal(originInfo as LX.Music.MusicInfoLocal, tryMatch)',\n      'return tryMatch(await getOtherSource(originInfo))'),\n  }),\n  'getOtherSourceByLocal')\n\n  // c13 匹配成功不落库\n  check('c13 匹配不落库', localLyricInvariants({\n    ...REAL,\n    localPlay: tamper(REAL.localPlay,\n      'if (!isFromCache) void saveLyric(originInfo as LX.Music.MusicInfo, lyricInfo as LX.Music.LyricInfo)',\n      'if (false) void 0'),\n  }),\n  '落库')\n\n  // c14 不读已落库缓存\n  check('c14 不读歌词缓存', localLyricInvariants({\n    ...REAL,\n    localPlay: tamper(REAL.localPlay,\n      'const cached = await getCachedLyricInfo(originInfo as LX.Music.MusicInfo).catch(() => null)',\n      'const cached: any = null'),\n  }),\n  'getCachedLyricInfo')\n\n  // c15 候选不交给时间轴校验\n  check('c15 跳过时间轴校验', localLyricInvariants({\n    ...REAL,\n    localPlay: tamper(REAL.localPlay,\n      '    const { lyricInfo, isFromCache } = await getOnlineOtherSourceLyricInfo({',\n      '    const { lyricInfo, isFromCache } = await searchCandidates({'),\n  }),\n  'getOnlineOtherSourceLyricInfo')\n\n  // c16 index.ts 本地歌词分支不带 musicInfo\n  check('c16 本地分支不带 musicInfo', localLyricInvariants({\n    ...REAL,\n    musicIndex: tamper(REAL.musicIndex,\n      '        // 本地文件条目：在线歌词匹配多轮重试 + 按 id 落库都要用它\\n        musicInfo,\\n',\n      ''),\n  }),\n  'index.ts')\n\n  // c17 getTaskTarget 不带原条目\n  check('c17 getTaskTarget 不带原条目', localLyricInvariants({\n    ...REAL,\n    musicIndex: tamper(REAL.musicIndex,\n      \"    quality: 'quality' in musicInfo ? (musicInfo as any).quality : undefined,\\n    // 【第 31 轮】原文条目：在线歌词匹配与落库（saveLyric/getCachedLyricInfo）都用它\\n    musicInfo,\",\n      \"    quality: 'quality' in musicInfo ? (musicInfo as any).quality : undefined,\"),\n  }),\n  'getTaskTarget')\n\n  // c18 local.ts 不再导出多轮匹配\n  check('c18 多轮匹配不再导出', localLyricInvariants({\n    ...REAL,\n    local: tamper(REAL.local, 'export const getOtherSourceByLocal = async <T>(', 'const getOtherSourceByLocal = async <T>('),\n  }),\n  'local.ts 没有导出')\n\n  // c19 离线歌词优先级被拆（内嵌歌词那步删掉）\n  check('c19 内嵌歌词那步删掉', localLyricInvariants({\n    ...REAL,\n    localPlay: tamper(REAL.localPlay,\n      'const embedded = await readLyric(target.filePath).catch(() => null)',\n      'const embedded = null'),\n  }),\n  '取歌词顺序')\n\n  return results\n}\n\n// ---------------------------------------------------------------------------\n// 主流程\n// ---------------------------------------------------------------------------\n\nconsole.log('=== sim-local-toggle-source-lyric ===')\nconsole.log('试听列表 local/下载条目：换源不崩（规整条目 + 可选链 + 原始条目确认）')\nconsole.log('                          能按歌名换源（候选组逐组回退 + 过滤 null）')\nconsole.log('                          自动获取在线歌词（多轮拆分匹配 + 时间轴校验 + 落库缓存）（第 31 轮）')\nconsole.log()\n\nconst checks = [\n  ['条一 换源不崩 + 能按歌名换源（normalizeToggleInfo / meta 可选链 / 候选组 / loadData 回退与过滤）', () => toggleCrashInvariants(REAL)],\n  ['条二 本地/下载条目自动获取在线歌词（内嵌→sidecar→缓存→多轮匹配→落库→兜底 的顺序与形状）', () => localLyricInvariants(REAL)],\n]\n\nlet invOk = true\nconst passCount = []\nfor (const [name, fn] of checks) {\n  const reasons = fn()\n  if (reasons.length === 0) {\n    passCount.push(name)\n    console.log(`\\n[${name}]\\n  PASS`)\n  } else {\n    invOk = false\n    console.log(`\\n[${name}]`)\n    ;[...new Set(reasons)].forEach((r) => console.log('  FAIL ' + r))\n  }\n}\n\nconsole.log('\\n[反例自检]')\nconst ceResults = runCounterExamples()\nlet ceAllOk = true\nfor (const r of ceResults) {\n  console.log(`  ${r.ok ? 'PASS' : 'FAIL'} ${r.name} —— ${r.detail}`)\n  if (!r.ok) ceAllOk = false\n}\n\nconst allOk = invOk && ceAllOk\nconsole.log(`\\n结果：${allOk ? 'ALL PASS' : '有失败项'}（不变量 ${passCount.length}/${checks.length}；反例 ${ceResults.filter((r) => r.ok).length}/${ceResults.length}）`)\nprocess.exit(allOk ? 0 : 1)\n" },
  { n: "sim-seek-lyric-follow.js", s: "#!/usr/bin/env node\n/**\n * sim-seek-lyric-follow.js —— seek 后「歌词跟随正在出声的音频」守卫\n *\n * 背景（对齐上游 lx-m 桌面版 seek→歌词时序）：\n * - 上游 setProgress 不碰歌词；audio 元素 seek 后 `waiting`→lrc.pause()（歌词冻在\n *   当前行）、真正从落点出声时 `playing`→lrc.play(引擎绝对时间)（歌词跳到落点行）。\n *   歌词永远跟「正在出声的位置」，从不在音频之前跳。\n * - 旧实现（回归版）在 seek 瞬间 syncLyric(目标)+hold(目标)：引擎还在放旧内容/\n *   静音缓冲的整个窗口里（nativeFlac 重新解码可达数秒），App 内歌词已显示目标行\n *   ——「快进/快退后歌词与音频不同步」。\n * - 新实现：seek 只立即跳进度条（nowPlayTime），歌词时钟不干涉；setCurrentTime\n *   resolve 后按引擎状态分派（playing→立即重锚落点 / buffering|paused→自冻结当前\n *   行）；轮询缓冲期按时钟锚点分派——已有锚点自冻结（nativeFlac 缓冲期 position\n *   回报的是 seek 目标，直接 hold(position) 会把行提前拽到目标行），无锚点（恢复\n *   进度起播）保持 hold(引擎位置) 旧行为。\n *\n * 每条关键断言用旧模型跑出反例（旧行为必须使断言失败），验证脚本区分力。\n */\n'use strict'\n\n// ---------------------------------------------------------------------------\n// 模型组件（1:1 复刻 src/core 侧语义，时间单位：模型内 ms）\n// ---------------------------------------------------------------------------\n\n/** AudioClock 复刻（src/core/player/audioClock.ts） */\nfunction createClock() {\n  return {\n    anchorPositionMs: 0,\n    anchorSystemMs: 0,\n    rate: 1,\n    playing: false,\n    holding: false,\n    holdMs: 0,\n    get hasAnchor() { return this.anchorSystemMs > 0 },\n    setAnchor(positionMs, rate = 1, playing = true) {\n      this.anchorPositionMs = positionMs\n      this.anchorSystemMs = nowMs\n      this.rate = rate\n      this.playing = playing\n      this.holding = false\n    },\n    hold(ms) {\n      this.holding = true\n      this.holdMs = ms\n    },\n    getTime() {\n      if (this.holding) return this.holdMs\n      if (!this.playing) return this.anchorPositionMs\n      return this.anchorPositionMs + (nowMs - this.anchorSystemMs) * this.rate\n    },\n  }\n}\n\n/** 歌词行引擎复刻（times 秒升序；findLineIndexByTime 语义） */\nfunction createLyric(timesSec) {\n  return {\n    times: timesSec.map(s => s * 1000),\n    line: -1,\n    lineAt(ms) {\n      const ts = this.times\n      if (!ts.length || ms <= ts[0]) return 0\n      let lo = 0\n      let hi = ts.length - 1\n      while (lo < hi) {\n        const mid = (lo + hi) >>> 1\n        if (ts[mid] <= ms) lo = mid + 1\n        else hi = mid\n      }\n      return ts[lo] > ms ? lo - 1 : lo\n    },\n    syncTo(ms) {\n      const next = this.lineAt(ms)\n      if (next !== this.line) this.line = next\n    },\n  }\n}\n\n/** 引擎复刻：可编排的 state/position（nativeFlac seek 后 position 立即=目标） */\nfunction createEngine() {\n  return {\n    state: 'playing',\n    pos: 0,\n    seekResolvePosition: null,\n    getPosition() { return this.pos },\n    getState() { return this.state },\n  }\n}\n\n// 虚拟时钟：setTimeout 以「待办队列 + 推进」模拟\nlet nowMs = 0\nconst timers = []\nfunction after(ms, fn) { timers.push({ at: nowMs + ms, fn }) }\nfunction runUntil(untilMs) {\n  for (;;) {\n    timers.sort((a, b) => a.at - b.at)\n    const next = timers[0]\n    if (!next || next.at > untilMs) {\n      nowMs = Math.max(nowMs, untilMs)\n      return\n    }\n    timers.shift()\n    nowMs = next.at\n    next.fn()\n  }\n}\n\n/**\n * 播放进度状态机复刻（playProgress.ts 的 seek 相关子集）。\n * variant='old' = 回归前行为；variant='new' = 对齐上游后行为。\n */\nfunction createProgress({ variant, lyric, clock, engine, isPlayRef }) {\n  let seekTargetPosition = null\n  let seekHoldUntil = 0\n\n  const state = { uiNowPlayTime: 0, recoveredPublishes: 0 }\n\n  const setNowPlayTime = (t) => { state.uiNowPlayTime = t }\n  const syncLyric = (time) => { lyric.syncTo(time * 1000) }\n\n  const getCurrentTime = () => {\n    const position = engine.getPosition()\n    // seek 生效窗口\n    if (seekTargetPosition != null && nowMs < seekHoldUntil) {\n      if (Math.abs(position - seekTargetPosition) >= 1.5) {\n        if (variant === 'old') clock.hold(seekTargetPosition * 1000) // 旧：冻到目标行\n        return // 新：只拦 UI 发布，不干涉歌词时钟\n      }\n      seekTargetPosition = null\n      seekHoldUntil = 0\n    }\n    setNowPlayTime(position)\n    const engineState = engine.getState()\n    const isBuffering = engineState === 'buffering' || engineState === 'loading'\n    if (!isPlayRef.value) return\n    if (isBuffering) {\n      // 缓冲分支：旧=hold(引擎位置)；新=有时钟锚点自冻结 / 无锚点锚引擎位置\n      if (variant === 'old') {\n        clock.hold(position * 1000)\n      } else {\n        clock.hold((clock.hasAnchor ? clock.getTime() : position) * 1000)\n      }\n      return\n    }\n    clock.setAnchor(position * 1000, 1, isPlayRef.value)\n    lyric.syncTo(position * 1000)\n    state.recoveredPublishes++\n  }\n\n  const scheduleFastResync = () => {\n    after(300, () => { getCurrentTime() })\n  }\n\n  const setProgress = (time) => {\n    setNowPlayTime(time)\n    if (variant === 'old') {\n      // 旧：立即冻时钟到目标 + 歌词跳目标行（回归行为）\n      clock.hold(time * 1000)\n      syncLyric(time)\n    }\n    // 新：不碰时钟、不碰歌词。两版共用：seek 窗口（拦旧位置进 UI）\n    seekTargetPosition = time\n    seekHoldUntil = nowMs + 2000\n\n    // setCurrentTime(time).then(targetPosition => ...)\n    after(20, () => {\n      const targetPosition = engine.seekResolvePosition != null ? engine.seekResolvePosition : time\n      setNowPlayTime(targetPosition)\n      seekTargetPosition = targetPosition\n      seekHoldUntil = nowMs + 2000\n      // 引擎状态分派（new；旧版在此无条件 hold(落点)+syncLyric(落点)）\n      if (variant === 'new') {\n        after(30, () => {\n          if (engine.getState() === 'playing' && isPlayRef.value) {\n            clock.hold(targetPosition * 1000)\n            syncLyric(targetPosition)\n          } else {\n            clock.hold(clock.getTime())\n          }\n        })\n      } else {\n        clock.hold(targetPosition * 1000)\n        syncLyric(targetPosition)\n      }\n      scheduleFastResync()\n    })\n  }\n\n  return { setProgress, getCurrentTime, state }\n}\n\n// ---------------------------------------------------------------------------\n// 断言框架\n// ---------------------------------------------------------------------------\nlet passCount = 0\nlet failCount = 0\nfunction check(name, fn) {\n  try {\n    fn()\n    passCount++\n    console.log(`  PASS  ${name}`)\n  } catch (err) {\n    failCount++\n    console.log(`  FAIL  ${name}\\n        ${err.message}`)\n  }\n}\nfunction assert(cond, msg) { if (!cond) throw new Error(msg) }\n\n/**\n * 场景 A：nativeFlac 型 seek——seekTo 同步置 buffering、position 立即=目标，\n * 解码数秒后才出声。时间线：t=0 seek → t=20 resolve → t=50 状态分派 →\n * t=350 快路径 → t=2000 出声前最后一查 → t=2010 出声 → t=2020 出声确认。\n */\nfunction runNativeFlacSeek(variant) {\n  nowMs = 0\n  timers.length = 0\n  const lyric = createLyric([0, 10, 20, 30, 40, 50])\n  const clock = createClock()\n  const engine = createEngine()\n  const isPlayRef = { value: true }\n  engine.pos = 5\n  clock.setAnchor(5000, 1, true) // 正在播放 5s 处\n  lyric.syncTo(5000)\n  engine.seekResolvePosition = 35\n  const progress = createProgress({ variant, lyric, clock, engine, isPlayRef })\n\n  progress.setProgress(35)\n  const atSeek = { ui: progress.state.uiNowPlayTime, line: lyric.line }\n\n  engine.state = 'buffering' // nativeFlac seekTo 同步置 buffering\n  engine.pos = 35 // position 模型立即=目标\n  runUntil(100)\n  const afterDispatch = { line: lyric.line, engineState: engine.getState() }\n\n  runUntil(2000) // 350ms 快路径 + 缓冲期（模拟多轮轮询：手动 tick）\n  progress.getCurrentTime(); progress.getCurrentTime()\n  const duringBuffering = { line: lyric.line }\n\n  engine.state = 'playing' // 解码完成，从落点出声\n  engine.pos = 35.4\n  progress.getCurrentTime()\n  const afterSound = { line: lyric.line, ui: progress.state.uiNowPlayTime }\n\n  return {\n    atSeek, afterDispatch, duringBuffering, afterSound,\n    targetLine: lyric.lineAt(35000), oldLine: lyric.lineAt(5300),\n  }\n}\n\n/** 场景 B：AVPlayer 秒落——seekTo 稳定确认后才 resolve，resolve 时已 playing */\nfunction runAvPlayerInstantSeek() {\n  nowMs = 0\n  timers.length = 0\n  const lyric = createLyric([0, 10, 20, 30, 40, 50])\n  const clock = createClock()\n  const engine = createEngine()\n  const isPlayRef = { value: true }\n  engine.pos = 5\n  clock.setAnchor(5000, 1, true)\n  lyric.syncTo(5000)\n  engine.seekResolvePosition = 35.2\n  engine.state = 'playing'\n  const progress = createProgress({ variant: 'new', lyric, clock, engine, isPlayRef })\n\n  progress.setProgress(35)\n  runUntil(100) // resolve(20) + 状态分派(50) 完成，快路径(350)未到\n  const afterDispatch = { line: lyric.line }\n\n  engine.pos = 35.3\n  runUntil(400)\n  const afterFastResync = { line: lyric.line, ui: progress.state.uiNowPlayTime }\n  return { afterDispatch, afterFastResync, targetLine: lyric.lineAt(35200) }\n}\n\n/** 场景 C：暂停态 seek——歌词不动，恢复播放且出声后跳落点 */\nfunction runPausedSeek(variant) {\n  nowMs = 0\n  timers.length = 0\n  const lyric = createLyric([0, 10, 20, 30, 40, 50])\n  const clock = createClock()\n  const engine = createEngine()\n  const isPlayRef = { value: false }\n  engine.pos = 5\n  clock.setAnchor(5000, 1, false)\n  lyric.syncTo(5000)\n  engine.seekResolvePosition = 35\n  const progress = createProgress({ variant, lyric, clock, engine, isPlayRef })\n\n  progress.setProgress(35)\n  runUntil(100)\n  const pausedAfterSeek = { line: lyric.line }\n\n  isPlayRef.value = true\n  engine.state = 'playing'\n  engine.pos = 35.2\n  progress.getCurrentTime()\n  const afterResume = { line: lyric.line }\n  return { pausedAfterSeek, afterResume, targetLine: lyric.lineAt(35000), oldLine: lyric.lineAt(5000) }\n}\n\n/** 场景 D：setProgress 与 setCurrentTime resolve 之间引擎仍报旧位置（seek 未生效） */\nfunction runStaleWindow(variant) {\n  nowMs = 0\n  timers.length = 0\n  const lyric = createLyric([0, 10, 20, 30, 40, 50])\n  const clock = createClock()\n  const engine = createEngine()\n  const isPlayRef = { value: true }\n  engine.pos = 5\n  clock.setAnchor(5000, 1, true)\n  lyric.syncTo(5000)\n  engine.seekResolvePosition = 35\n  const progress = createProgress({ variant, lyric, clock, engine, isPlayRef })\n\n  progress.setProgress(35)\n  // 此时（resolve 前）轮询：引擎还在放旧内容（6s 处继续出声）\n  engine.pos = 6\n  progress.getCurrentTime()\n  return { ui: progress.state.uiNowPlayTime, line: lyric.line, targetLine: lyric.lineAt(35000), oldLine: lyric.lineAt(6000) }\n}\n\n/** 场景 E：非 seek 的恢复进度起播缓冲——时钟无锚点，缓冲期仍锚到引擎位置 */\nfunction runRestoreBuffering(variant) {\n  nowMs = 0\n  timers.length = 0\n  const lyric = createLyric([0, 10, 20, 30, 40, 50])\n  const clock = createClock() // 全新时钟，无锚点\n  const engine = createEngine()\n  const isPlayRef = { value: true }\n  engine.pos = 120\n  engine.state = 'buffering' // 恢复进度起播即缓冲\n  const progress = createProgress({ variant, lyric, clock, engine, isPlayRef })\n\n  progress.getCurrentTime() // 起播轮询（无 seek 窗口）\n  return { heldMs: clock.getTime() }\n}\n\n/** 场景 F：nativeFlac 快退（35s→5s）——方向无关性显式回归守卫 */\nfunction runNativeFlacRewind(variant) {\n  nowMs = 0\n  timers.length = 0\n  const lyric = createLyric([0, 10, 20, 30, 40, 50])\n  const clock = createClock()\n  const engine = createEngine()\n  const isPlayRef = { value: true }\n  engine.pos = 35\n  clock.setAnchor(35000, 1, true) // 正在播放 35s 处\n  lyric.syncTo(35000)\n  engine.seekResolvePosition = 5\n  const progress = createProgress({ variant, lyric, clock, engine, isPlayRef })\n\n  progress.setProgress(5) // 快退到 5s\n  const atSeek = { line: lyric.line }\n\n  engine.state = 'buffering' // seekTo 同步置 buffering\n  engine.pos = 5 // position 模型立即=目标（回退方向同样立即回报）\n  runUntil(100)\n  const afterDispatch = { line: lyric.line }\n\n  runUntil(2000)\n  progress.getCurrentTime(); progress.getCurrentTime()\n  const duringBuffering = { line: lyric.line }\n\n  engine.state = 'playing' // 回退解码完成，从 5s 出声\n  engine.pos = 5.3\n  progress.getCurrentTime()\n  const afterSound = { line: lyric.line }\n  return {\n    atSeek, afterDispatch, duringBuffering, afterSound,\n    targetLine: lyric.lineAt(5300), oldLine: lyric.lineAt(35300),\n  }\n}\n\n/** 场景 G：nativeFlac seek 缓冲期控制中心原生歌词时钟（AppDelegate.mm LXNowPlayingClockHold）\n *  原生时钟 = 锚点+速率外推；JS 正速率发布解冻并重锚（「见正 playbackRate 即解除」）。\n *  nativeFlac 的 emitState 只发 JS 桥，原生时钟收不到生命周期事件 → 冻结只能由\n *  seekTo 显式置位（新模型）；旧行为不置位 = 整个重解码缓冲期从旧位置继续外推。\n *  时间线：t=0 锚在 8s 播放中 → t=1000 快退 seek(目标 5s) → 缓冲解码 →\n *  t=3600 出声 → t=3900 JS 确认 playing 发布正速率+带戳真实位置 5.3s。 */\nfunction runNativeClockDuringSeek({ holdOnSeek }) {\n  nowMs = 0\n  const lyric = createLyric([0, 10, 20, 30, 40, 50])\n  const nc = {\n    anchorMs: 8000, anchorSys: 0, rate: 1, hold: false, line: -1,\n    position(ms) { return this.hold ? this.anchorMs : this.anchorMs + (ms - this.anchorSys) * this.rate },\n    sync() { const i = lyric.lineAt(this.position(nowMs)); if (i !== this.line) this.line = i },\n  }\n  nc.sync() // 播放中：时钟锚在 8s，外推\n  nowMs = 1000\n  if (holdOnSeek) nc.hold = true // 新：seekTo 置 LXNowPlayingClockHold=YES\n  nowMs = 3500 // 缓冲解码 2.5s（无任何 JS 正速率发布：在App时钟冻结 → 无行变化元数据）\n  nc.sync()\n  const duringBuffering = { line: nc.line, posMs: Math.round(nc.position(3500)) }\n  nowMs = 3900 // 出声后 JS 发布：正速率 + 带戳真实落点 5.3s\n  nc.anchorMs = 5600; nc.anchorSys = 3900; nc.rate = 1\n  if (nc.rate > 0) nc.hold = false // 「见正 playbackRate 即解除」\n  nc.sync()\n  const afterSound = { line: nc.line }\n  return { duringBuffering, afterSound, atSeekLine: lyric.lineAt(8000), driftedLine: lyric.lineAt(10500), targetLine: lyric.lineAt(5600) }\n}\n\n// ---------------------------------------------------------------------------\n// 用例\n// ---------------------------------------------------------------------------\nconsole.log('sim-seek-lyric-follow：seek 后歌词跟随正在出声的音频（对齐上游 waiting→冻结 / playing→重锚）\\n')\n\nconsole.log('[场景 A] nativeFlac 型 seek（缓冲期 position 已=目标）')\nconst newA = runNativeFlacSeek('new')\nconst oldA = runNativeFlacSeek('old')\ncheck('A1 新模型：seek 瞬间进度条 UI 立即跳目标（上游 audio.currentTime 语义）', () => {\n  assert(newA.atSeek.ui === 35, `ui=${newA.atSeek.ui} 应=35`)\n})\ncheck('A2 新模型：seek 瞬间歌词行不跳（仍停在正在出声的旧行）', () => {\n  assert(newA.atSeek.line === newA.oldLine, `line=${newA.atSeek.line} 应=${newA.oldLine}`)\n})\ncheck('A2x 反例：旧模型 seek 瞬间歌词行已跳到目标行（回归行为可被 A2 捕获）', () => {\n  assert(oldA.atSeek.line === oldA.targetLine, `旧模型 line=${oldA.atSeek.line} 预期=回归行为目标行 ${oldA.targetLine}（若不等则脚本无区分力）`)\n})\ncheck('A3 新模型：resolve 后引擎 buffering，状态分派自冻结，歌词行不跳', () => {\n  assert(newA.afterDispatch.engineState === 'buffering', `state=${newA.afterDispatch.engineState}`)\n  assert(newA.afterDispatch.line === newA.oldLine, `line=${newA.afterDispatch.line} 应=${newA.oldLine}`)\n})\ncheck('A4 新模型：缓冲解码期多轮轮询（引擎报目标 35、窗口已关）歌词行仍不提前跳', () => {\n  assert(newA.duringBuffering.line === newA.oldLine, `line=${newA.duringBuffering.line} 应=${newA.oldLine}（窗口关闭后缓冲轮询 hold(position) 会把行拽到目标行）`)\n})\ncheck('A4x 反例：旧模型缓冲期歌词行已在目标行（回归行为可被 A4 捕获）', () => {\n  assert(oldA.duringBuffering.line === oldA.targetLine, `旧模型 line=${oldA.duringBuffering.line} 预期=回归行为目标行 ${oldA.targetLine}（若不等则脚本无区分力）`)\n})\ncheck('A5 新模型：引擎从落点出声后歌词行跳到落点行（playing→重锚）', () => {\n  assert(newA.afterSound.line === newA.targetLine, `line=${newA.afterSound.line} 应=${newA.targetLine}`)\n  assert(newA.afterSound.ui >= 35, `ui=${newA.afterSound.ui} 应≥35`)\n})\n\nconsole.log('\\n[场景 B] AVPlayer 秒落（resolve 时已 playing）')\nconst newB = runAvPlayerInstantSeek()\ncheck('B1 新模型：resolve 状态分派立即重锚到落点行（~50ms，不等轮询）', () => {\n  assert(newB.afterDispatch.line === newB.targetLine, `line=${newB.afterDispatch.line} 应=${newB.targetLine}`)\n})\ncheck('B2 新模型：快路径后行保持落点行、UI 在落点', () => {\n  assert(newB.afterFastResync.line === newB.targetLine, `line=${newB.afterFastResync.line}`)\n  assert(newB.afterFastResync.ui >= 35, `ui=${newB.afterFastResync.ui} 应≥35`)\n})\n\nconsole.log('\\n[场景 C] 暂停态 seek')\nconst newC = runPausedSeek('new')\ncheck('C1 新模型：暂停态 seek 歌词行不动（上游 paused 不重锚）', () => {\n  assert(newC.pausedAfterSeek.line === newC.oldLine, `line=${newC.pausedAfterSeek.line} 应=${newC.oldLine}`)\n})\ncheck('C2 新模型：恢复播放且引擎出声后行跳到落点行', () => {\n  assert(newC.afterResume.line === newC.targetLine, `line=${newC.afterResume.line} 应=${newC.targetLine}`)\n})\n\nconsole.log('\\n[场景 D] resolve 前引擎仍报旧位置（seek 未生效）')\nconst newD = runStaleWindow('new')\nconst oldD = runStaleWindow('old')\ncheck('D1 新模型：窗口内旧位置不刷进进度条 UI（防抽帧保护保留）', () => {\n  assert(newD.ui === 35, `ui=${newD.ui} 应=35`)\n})\ncheck('D2 新模型：窗口内不干涉歌词时钟（歌词跟随正在出声的旧音频）', () => {\n  assert(newD.line === newD.oldLine, `line=${newD.line} 应=${newD.oldLine}（旧侧），不得=目标行 ${newD.targetLine}`)\n})\ncheck('D2x 反例：旧模型窗口内歌词行已在目标行（回归行为可被 D2 捕获）', () => {\n  assert(oldD.line === oldD.targetLine, `旧模型 line=${oldD.line} 预期=回归行为目标行 ${oldD.targetLine}（若不等则脚本无区分力）`)\n})\n\nconsole.log('\\n[场景 E] 非 seek 恢复进度起播缓冲（旧行为保留）')\nconst newE = runRestoreBuffering('new')\nconst oldE = runRestoreBuffering('old')\ncheck('E1 新模型：时钟无锚点时缓冲期锚到引擎位置（恢复进度的行同步依赖它）', () => {\n  assert(Math.abs(newE.heldMs - 120000) < 1, `heldMs=${newE.heldMs} 应=120000`)\n})\ncheck('E1x 反例：旧模型同场景行为一致（确认此路径两版等价、非回归点）', () => {\n  assert(Math.abs(oldE.heldMs - 120000) < 1, `heldMs=${oldE.heldMs}`)\n})\n\nconsole.log('\\n[场景 F] nativeFlac 快退（35s→5s，方向无关性）')\nconst newF = runNativeFlacRewind('new')\nconst oldF = runNativeFlacRewind('old')\ncheck('F1 新模型：快退瞬间歌词行不跳（仍停在 35s 正在出声的行）', () => {\n  assert(newF.atSeek.line === newF.oldLine, `line=${newF.atSeek.line} 应=${newF.oldLine}`)\n})\ncheck('F2 新模型：回退重解码缓冲期（position 已报目标 5s）歌词行不提前跳', () => {\n  assert(newF.afterDispatch.line === newF.oldLine, `dispatch line=${newF.afterDispatch.line}`)\n  assert(newF.duringBuffering.line === newF.oldLine, `buffering line=${newF.duringBuffering.line}（hold(position=5) 会把行提前拽回 5s）`)\n})\ncheck('F3 新模型：回退出声后歌词行跳到 5s 落点行（playing→重锚）', () => {\n  assert(newF.afterSound.line === newF.targetLine, `line=${newF.afterSound.line} 应=${newF.targetLine}`)\n})\ncheck('F3x 反例：旧模型快退缓冲期歌词行已在目标行（回归行为可被 F2 捕获）', () => {\n  assert(oldF.duringBuffering.line === oldF.targetLine, `旧模型 line=${oldF.duringBuffering.line} 预期=回归行为目标行 ${oldF.targetLine}（若不等则脚本无区分力）`)\n})\n\nconsole.log('\\n[场景 G] nativeFlac seek 缓冲期控制中心原生歌词时钟（LXNowPlayingClockHold）')\nconst newG = runNativeClockDuringSeek({ holdOnSeek: true })\nconst oldG = runNativeClockDuringSeek({ holdOnSeek: false })\ncheck('G1 新模型：seek 置 hold 后，缓冲期原生时钟冻结，控制中心歌词行停在旧行', () => {\n  assert(newG.duringBuffering.line === newG.atSeekLine, `line=${newG.duringBuffering.line} 应=${newG.atSeekLine}`)\n  assert(newG.duringBuffering.posMs === 8000, `pos=${newG.duringBuffering.posMs} 应冻结在 8000`)\n})\ncheck('G1x 反例：旧模型（seekTo 不置 hold）缓冲期原生时钟继续外推，行已越过旧行（回归行为可被 G1 捕获）', () => {\n  assert(oldG.duringBuffering.posMs > 8000, `pos=${oldG.duringBuffering.posMs} 预期已外推越过 8000（若相等则脚本无区分力）`)\n  assert(oldG.duringBuffering.line === oldG.driftedLine, `line=${oldG.duringBuffering.line} 预期=漂移行 ${oldG.driftedLine}`)\n})\ncheck('G2 新模型：出声后 JS 正速率发布解冻并重锚，控制中心歌词行跳到落点行', () => {\n  assert(newG.afterSound.line === newG.targetLine, `line=${newG.afterSound.line} 应=${newG.targetLine}`)\n})\n\nconsole.log(`\\n结果：${passCount} 过 / ${failCount} 败`)\nprocess.exit(failCount ? 1 : 0)\n" },
  { n: "sim-board-nav.js", s: "/**\n * sim-board-nav.js\n *\n * 「播放音乐 → 放后台一段时间 → 回前台 → 在推荐页点榜单卡片没反应」这条复现路径的守卫。\n *\n * 建模四件真实事实：\n *  1) `setNavActiveId` 有同值短路（`core/common.ts:76-83`）；\n *  2) PagerView 的原生落点(observedIndex)与 navActiveId 是两套状态：App 从后台恢复时\n *     原生落点可能被重置到 0（推荐页），而 navActiveId 保持不变；\n *  3) observedIndex 曾被乐观初始化，可能在未经原生确认时就「看起来等于目标」；\n *  4) **原生 pager 实例可能彻底失效**（2026-09-30 新增）：此时 `setPage*` 全是空操作\n *     —— 不报错、也不回 onPageSelected。首页横向滑动是关的（`scrollEnabled={false}`），\n *     页面只能靠 JS 切，于是第 ②③ 条的「强制同步」也只是再发一次空操作：\n *     表现为「点榜单卡片/平台切换按钮没反应，列表照样能上下滚」。\n *     修法：重试链全部失败后换 key **重建 PagerView 实例**，initialPage 落到目标页\n *     （点击 → 0/400/900ms 三次 setPage → 约 1.4s 后重建落位）。\n *\n * 注意：下面的状态机是**手写复刻**，只能证明逻辑自洽；真正把实现钉住的是「源码契约」节\n * （从 `Main.tsx` 解析关键写法，并对 5 例篡改断言必须被拦下）。\n *\n * 运行：node scripts/sim-board-nav.js\n * 退出码：断言与契约全过、且反例全被拦下时为 0，否则 1。\n */\n\nconst fs = require('fs')\nconst path = require('path')\n\nconst MAIN = 'src/screens/Home/Vertical/Main.tsx'\nconst SRC = fs.readFileSync(path.join(__dirname, '..', MAIN), 'utf8').replace(/\\r\\n/g, '\\n')\n\nconst results = []\nconst check = (name, ok, detail = '') => results.push({ name, ok, detail })\n\n// ============================================================================\n// 一、状态机复刻：navActiveId / observedIndex 失配 + 强制同步\n// ============================================================================\nconst VIEW = { nav_discovery: 0, nav_top: 1 } // viewMap\nlet navActiveId = 'nav_discovery'\nlet observedIndex = 0\nlet forceSync = false\nlet lastIssuedIndex = null\nlet pendingClearIndex = false\nlet setPageCalls = []\nlet log = []\n\n// 原生 pager 是否已失效（setPage 空操作）+ 兜底重建的状态\nlet nativeDead = false\nlet rebuilds = 0\nlet lastRebuildAt = 0\n\n// ---- 旧实现（修复前）----\nconst setNavActiveId_old = (id) => {\n  if (id === navActiveId) { log.push('setNavActiveId(' + id + ') 被同值短路'); return }\n  navActiveId = id\n  handleUpdate_old(id)\n}\nconst handleUpdate_old = (id) => {\n  const index = VIEW[id]\n  if (observedIndex === index) { log.push('handleUpdate 乐观短路(index=' + index + ')'); return }\n  setPageCalls.push(index); log.push('setPageWithoutAnimation(' + index + ')')\n  observedIndex = index\n}\n\n// ---- 新实现（修复后）----\nconst markIssued = (index) => {\n  lastIssuedIndex = index\n  // 模拟实现里的「0ms 宏任务清标记」：微任务批跑完后才失效\n  pendingClearIndex = true\n}\nconst flushTick = () => {\n  // 一批微任务（同一 tick 内的多次事件回调）跑完后，标记才失效\n  if (pendingClearIndex) { pendingClearIndex = false; lastIssuedIndex = null }\n}\nconst handleUpdate_new = (id) => {\n  const index = VIEW[id]\n  const isForce = forceSync && id === navActiveId\n  if (!isForce && observedIndex === index) {\n    log.push('handleUpdate 乐观短路(index=' + index + ')')\n    return\n  }\n  if (isForce && lastIssuedIndex === index) {\n    forceSync = false\n    log.push('强制同步被去重（本 tick 已为该 index 下发过 setPage）')\n    return\n  }\n  if (isForce) {\n    forceSync = false\n    observedIndex = -1\n    log.push('强制同步：原生落点标记为未知')\n  }\n  markIssued(index)\n  setPageCalls.push(index)\n  log.push('setPageWithoutAnimation(' + index + ')')\n  // 原生失效 ⇒ setPage 是空操作：不回执、落点不变\n  if (!nativeDead) observedIndex = index\n}\nconst setNavActiveId_new = (id) => {\n  if (id === navActiveId) { log.push('setNavActiveId(' + id + ') 被同值短路'); return }\n  navActiveId = id\n  handleUpdate_new(id)\n}\nconst forceSyncNavActiveId = () => { forceSync = true; handleUpdate_new(navActiveId) }\n\nconst reset = (dead = false) => {\n  navActiveId = 'nav_discovery'; observedIndex = 0; forceSync = false\n  lastIssuedIndex = null; pendingClearIndex = false; setPageCalls = []; log = []\n  nativeDead = dead; rebuilds = 0; lastRebuildAt = 0\n}\n\nconst run = (name, impl) => {\n  impl.setNav('nav_top')\n  flushTick() // 第一次进入是独立的一 tick\n  const afterFirst = observedIndex\n  observedIndex = 0 // 后台恢复后 iOS 重建原生子视图\n  const sceneOnReturn = 'navActiveId=' + navActiveId + ' 界面在第' + observedIndex + '页'\n  log = []\n  impl.open()\n  flushTick()\n  const ok = observedIndex === VIEW.nav_top\n  console.log('\\n【' + name + '】')\n  console.log('  首次进入后原生落点=' + afterFirst)\n  console.log('  后台回来：' + sceneOnReturn)\n  console.log('  点卡片后：原生落点=' + observedIndex + ' → ' + (ok ? '成功进入排行榜' : '点了没反应'))\n  console.log('  轨迹：' + log.join(' | '))\n  return ok\n}\n\nconst oldImpl = { setNav: setNavActiveId_old, open: () => setNavActiveId_old('nav_top') }\nconst newImpl = {\n  setNav: setNavActiveId_new,\n  open: () => { setNavActiveId_new('nav_top'); forceSyncNavActiveId() },\n}\n\nreset(); const r1 = run('旧实现（复现你的 bug）', oldImpl)\nreset(); const r2 = run('新实现', newImpl)\ncheck('旧实现能复现「点了没反应」', !r1)\ncheck('新实现（强制同步）在后端仅“落点失配”时能修复', r2)\n\nconsole.log('\\n【回归 A：正常情况（无后台失配，从推荐页点卡片）】')\nreset()\nnewImpl.open()\nflushTick()\nconsole.log('  点卡片后：原生落点=' + observedIndex + ' → ' + (observedIndex === VIEW.nav_top ? '正常切页' : '没切'))\nconsole.log('  轨迹：' + log.join(' | '))\nconsole.log('  setPage 次数=' + setPageCalls.length + '（期望 1：常规切页已下发，强制同步去重）')\ncheck('回归 A：正常路径只下发一次 setPage 且切页成功', setPageCalls.length === 1 && observedIndex === VIEW.nav_top)\n\nconsole.log('\\n【回归 B：已在排行榜页（state 与原生都一致）时再点卡片】')\nreset()\nnavActiveId = 'nav_top'; observedIndex = VIEW.nav_top\nflushTick()\nnewImpl.open()\nflushTick()\nconsole.log('  点卡片后：原生落点=' + observedIndex + ' → ' + (observedIndex === VIEW.nav_top ? '仍在排行榜' : '异常'))\nconsole.log('  轨迹：' + log.join(' | '))\nconsole.log('  setPage 次数=' + setPageCalls.length + '（期望 1：仅强制同步下发一次校正）')\ncheck('回归 B：已在目标页时不下发多余 setPage（除强制同步的一次校正外不改落点）', observedIndex === VIEW.nav_top)\n\n// ============================================================================\n// 二、原生死透：重试链 + 兜底重建\n// ============================================================================\nconst RETRY_FIRST = Number(/armRetry\\((\\d+), 1\\)/.exec(SRC)?.[1] ?? NaN) // 400\nconst RETRY_NEXT = Number(/armRetry\\((\\d+), attempt \\+ 1\\)/.exec(SRC)?.[1] ?? NaN) // 500\nconst MAX_REBUILDS = Number(/const MAX_PAGER_REBUILDS = (\\d+)/.exec(SRC)?.[1] ?? NaN)\nconst DEBOUNCE_MS = Number(/const PAGER_REBUILD_DEBOUNCE_MS = (\\d+)/.exec(SRC)?.[1] ?? NaN)\nconst EPOCH = 1700000000000 // lastRebuildAtRef 初值 0、Date.now() 是纪元毫秒，模型须同基准\n\ncheck('模型参数可从源码解析（重试时序/上限/防抖）', Number.isFinite(RETRY_FIRST) && Number.isFinite(RETRY_NEXT) && Number.isFinite(MAX_REBUILDS) && Number.isFinite(DEBOUNCE_MS), `first=${RETRY_FIRST} next=${RETRY_NEXT} max=${MAX_REBUILDS} debounce=${DEBOUNCE_MS}`)\n\n/** 一次点击在“原生死透”下的完整时序：3 次 setPage 全无回执 → 约 1.4s 后重建 */\nconst deadFailAt = (tapAt) => tapAt + RETRY_FIRST + RETRY_NEXT + RETRY_NEXT\nconst simulateDead = (tapTimes, { withRepair = true } = {}) => {\n  let page = 0\n  let n = 0\n  let lastAt = 0\n  const trail = []\n  for (const tapAt of tapTimes) {\n    if (!withRepair) { trail.push({ t: deadFailAt(tapAt), kind: 'giving-up' }); continue }\n    const t = deadFailAt(tapAt)\n    if (t - lastAt < DEBOUNCE_MS) { trail.push({ t, kind: 'skip:debounce' }); continue }\n    if (n >= MAX_REBUILDS) { trail.push({ t, kind: 'skip:limit' }); continue }\n    n += 1\n    lastAt = t\n    page = 1 // 重建后 initialPage = 目标页\n    trail.push({ t, kind: 'rebuild', page })\n  }\n  return { page, n, trail }\n}\n\n{\n  // ① 无重建（等于本次修复前）：点多少次都停在推荐页\n  const without = simulateDead([EPOCH, EPOCH + 5000, EPOCH + 10000], { withRepair: false })\n  check('反例·无重建时点多少次都停在推荐页（这正是用户遇到的「点了没反应」）', without.n === 0 && without.page === 0)\n\n  // ② 有重建：一次点击换来一次重建并落到目标页\n  const once = simulateDead([EPOCH])\n  check('一次点击触发 1 次重建并落到目标页', once.n === 1 && once.page === 1, `rebuilds=${once.n} page=${once.page}`)\n  check(`重建发生在重试链跑完之后（≥ ${RETRY_FIRST + RETRY_NEXT + RETRY_NEXT}ms）`, once.trail[0].t - EPOCH >= RETRY_FIRST + RETRY_NEXT + RETRY_NEXT)\n\n  // ③ 防抖：窗口内连点只重建一次\n  const spam = simulateDead([EPOCH, EPOCH + 800, EPOCH + 1600])\n  check(`防抖（${DEBOUNCE_MS}ms）内连点只重建一次`, spam.n === 1, `rebuilds=${spam.n}`)\n\n  // ④ 会话上限\n  const many = simulateDead(Array.from({ length: 10 }, (_, i) => EPOCH + i * (DEBOUNCE_MS + 1000)))\n  check(`会话上限：最多重建 ${MAX_REBUILDS} 次（实测 ${many.n}）`, many.n === MAX_REBUILDS)\n}\n\n// ============================================================================\n// 三、源码契约（把实现钉住；判断前必须去行注释，否则「注释掉某行」会假绿）\n// ============================================================================\nconst code = (src) => src.replace(/\\/\\/[^\\n]*/g, '')\nconst contract = (rawSrc) => {\n  const src = code(rawSrc)\n  const out = []\n  const push = (name, ok) => out.push({ name, ok })\n  // repairPager 的函数体：有些写法（如 observedIndexRef.current = -1）在别处也有，\n  // 必须收窄到本函数体内判断，否则篡改它不会被发现（反例⑥第一版就是这么假绿的）。\n  const repairAt = src.indexOf('const repairPager = useCallback(')\n  const repairBody = repairAt < 0 ? '' : src.slice(repairAt, src.indexOf('}, [])', repairAt))\n  push('PagerView 的 key 含 pagerRebuild（换 key 才会重建原生实例）', /key=\\{`\\$\\{pagerKey\\}#\\$\\{pagerRebuild\\}`\\}/.test(src))\n  push('重试链失败后调用 repairPager(index)', /else repairPager\\(index\\)/.test(src))\n  push('repairPager 有防抖 + 会话上限两道闸', /PAGER_REBUILD_DEBOUNCE_MS\\) return/.test(repairBody) && /rebuildCountRef\\.current >= MAX_PAGER_REBUILDS\\) return/.test(repairBody))\n  push('initialPageIndex 优先取重建目标且依赖 pagerRebuild', /const target = rebuildTargetRef\\.current/.test(src) && /\\[viewMap, visibleNavs\\.length, pagerRebuild\\]/.test(src))\n  push('repairPager 内部把原生落点置为未知（-1），不残留乐观值', repairBody.length > 0 && /observedIndexRef\\.current = -1/.test(repairBody))\n  push('repairPager 记录重建目标页（initialPage 才有依据）', repairBody.length > 0 && /rebuildTargetRef\\.current = index/.test(repairBody))\n  push('onPageSelected 清掉重建目标（原生回执后恢复常规口径）', /observedIndexRef\\.current = nativeEvent\\.position[\\s\\S]{0,400}rebuildTargetRef\\.current = null/.test(src))\n  return out\n}\nfor (const r of contract(SRC)) check(r.name, r.ok)\n\nconst TAMPERS = [\n  { label: '① 去掉失败后的重建调用（回到本次修复前）', from: '            else repairPager(index)', to: '            // else repairPager(index)' },\n  { label: '② key 不再包含 pagerRebuild（重建不生效）', from: 'key={`${pagerKey}#${pagerRebuild}`}', to: 'key={pagerKey}' },\n  { label: '③ 去掉防抖（连点会反复重建）', from: 'if (now - lastRebuildAtRef.current < PAGER_REBUILD_DEBOUNCE_MS) return', to: '// debounce removed' },\n  { label: '④ 去掉会话上限（修不好就一直重建）', from: 'if (rebuildCountRef.current >= MAX_PAGER_REBUILDS) return', to: '// limit removed' },\n  { label: '⑤ 重建目标不清空（后续 remount 落错页）', from: 'rebuildTargetRef.current = null\\n', to: '' },\n  { label: '⑥ 重建前不重置原生落点（乐观值残留）', from: 'observedIndexRef.current = -1', to: 'observedIndexRef.current = index' },\n]\nfor (const t of TAMPERS) {\n  if (!SRC.includes(t.from)) {\n    check(`反例 ${t.label}`, false, '替换未命中：源码已变，反例失效需同步')\n    continue\n  }\n  const failed = contract(SRC.replace(t.from, t.to)).filter(r => !r.ok)\n  check(`反例 ${t.label} 被拦下`, failed.length > 0, failed.length ? `命中：${failed.map(r => r.name.slice(0, 16)).join('、')}` : '未被任何契约拦下')\n}\n\nconsole.log('\\n结论：旧实现能否复现失败=' + (!r1) + '；强制同步修复=' + r2 + '；原生死透由重建兜底=' + (simulateDead([EPOCH]).page === 1))\n\nconst failedCount = results.filter(r => !r.ok).length\nconsole.log(`\\n${results.length - failedCount}/${results.length} 通过`)\nfor (const r of results) if (!r.ok) console.log(`  ❌ ${r.name}${r.detail ? ' — ' + r.detail : ''}`)\nprocess.exit(failedCount ? 1 : 0)\n" },
]

const fmt = (v) => {
  if (typeof v === 'string') return v
  try { return JSON.stringify(v) } catch (e) { return String(v) }
}

// 与 run.py 的 runner.html 逐字同形的 require 映射（成员平时就是这么跑的）
const makeRequire = () => (name) => {
  if (name === 'fs' || name === 'node:fs') return require('fs')
  if (name === 'path' || name === 'node:path') return require('path')
  if (name === 'os' || name === 'node:os') return { EOL: '\n', platform: () => 'win32', cpus: () => [] }
  if (name === 'child_process' || name === 'node:child_process') return {
    execSync: () => '',
    spawnSync: () => ({ status: 0, stdout: '', stderr: '', error: null }),
    exec: () => ({ on: () => {}, stdout: { on: () => {} }, stderr: { on: () => {} } }),
  }
  if (name === 'util' || name === 'node:util') return { inspect: fmt }
  throw new Error('MODULE_NOT_SUPPORTED: ' + name)
}

// 成员看到的 __dirname / __filename：**拿套件自己的那一份**，两种运行环境下都正确 ——
// 浏览器 runner 里套件作用域的 __dirname 是 '/scripts'（HTTP 根即工程根），
// 真实 node 里是 '<工程根>\scripts'。这里**不能写死** '/scripts'：真实 node 下
// path.resolve('/scripts', '..') 会落到盘根（E:\），成员一律 ENOENT。
const DIRNAME = (typeof __dirname === 'string' && __dirname) ? __dirname : '/scripts'

const RESULTS = []
MEMBERS.forEach((m, i) => {
  const tag = `[${i + 1}/${MEMBERS.length}] ${m.n}`
  console.log(`===== ${tag} =====`)
  const lines = []
  const memberConsole = {
    log: (...a) => lines.push(a.map(fmt).join(' ')),
    error: (...a) => lines.push('[err] ' + a.map(fmt).join(' ')),
    warn: (...a) => lines.push('[warn] ' + a.map(fmt).join(' ')),
  }
  let code = null
  const memberProcess = {
    // runner.html 的 shim 也是「记下退出码，不真的退出」—— 逐字保持同形，
    // 这样「合并前跑一次、合并后跑一次」的输出与退出码才可比
    exit: (c) => { if (code === null) code = (c === undefined ? 0 : c) },
    argv: ['node', 'scripts/' + m.n],
    cwd: () => '/',
    env: {},
    platform: 'win32',
    version: 'v20.11.0',
    versions: { node: '20.11.0' },
  }
  let fatal = null
  try {
    const mod = { exports: {} }
    // 与 runner.html 完全同形的两步预处理：剥掉开头的 BOM 与 shebang
    //（`#!` 不是合法 JS —— 独立跑时由 runner 剥，收进套件后必须由套件自己剥，
    //  否则带 shebang 的成员会当场 SyntaxError），再追加 sourceURL 注释让栈指回成员名
    const src = String(m.s).replace(/^\uFEFF/, '').replace(/^#![^\n]*\r?\n/, '')
    const fn = new Function('require', 'process', 'console', '__dirname', '__filename', 'module', 'exports',
      src + '\n//# sourceURL=scripts/' + m.n)
    fn(makeRequire(), memberProcess, memberConsole, DIRNAME, DIRNAME + '/' + m.n, mod, mod.exports)
  } catch (e) {
    fatal = (e && e.stack) ? e.stack : String(e)
  }
  if (fatal != null) {
    lines.push('[FATAL] ' + fatal)
    if (code === null) code = 1
  }
  for (const l of lines) console.log(l)
  const rc = code === null ? 0 : code
  RESULTS.push({ name: m.n, rc, exited: code !== null })
  console.log(`===== ${tag} → exit ${rc} =====`)
})

const failed = RESULTS.filter((r) => r.rc !== 0)
const noExit = RESULTS.filter((r) => !r.exited)
console.log('')
console.log(`成员 ${RESULTS.length} 个；退出 0 的 ${RESULTS.length - failed.length} 个；`
  + `非 0 的 ${failed.length} 个${noExit.length ? `；没调 process.exit 的 ${noExit.length} 个` : ''}`)
if (failed.length) {
  for (const r of failed) console.log(`  FAIL 成员 ${r.name} → exit ${r.rc}`)
}
console.log(`结果：${failed.length ? '有失败成员' : 'ALL PASS'}（成员 ${RESULTS.length - failed.length}/${RESULTS.length}；`
  + `主题 ${THEME}）`)
process.exit(failed.length ? failed[0].rc : 0)
